]={npc="Горный пехотинец Кэдрелл", tgt="Горный пехотинец Кэдрелл", desc="Горный пехотинец Кэдрелл ходит туда-обратно по дороге через Телсамар (32.6, 49.7 - 36.8, 42.0). Если его здесь нет, идите вдоль дороги."}, [89]={npc="Горный пехотинец Грозовая Вершина", tgt="Горный пехотинец Грозовая Вершина"}, [90]={npc="Горный пехотинец Грозовая Вершина", tgt="Горный пехотинец Грозовая Вершина"}, [91]={npc="Горный пехотинец Грозовая Вершина", tgt="Горный пехотинец Грозовая Вершина"}, [92]={npc="Горный пехотинец Грозовая Вершина", tgt="Горный пехотинец Грозовая Вершина"}, [93]={hint="Принесите из Рудника у Серебряного ручейка 4 ящика оборудования горному пехотинцу Грозовой Вершине."}, [94]={hint="Принесите 12 ушей кобольдов-туннельщиков горному пехотинцу Кэдреллу в Телсамар."}, [95]={text="Тяжелая шипастая палица", npc="Нилиен Аденмар", tag="Необязательно", desc="Ограниченный товар. Покупайте, только если есть в наличии."}, [96]={npc="Горный пехотинец Грозовая Вершина", tgt="Горный пехотинец Грозовая Вершина"}, [97]={bindA="{a:144}"}, [98]={npc="Горный пехотинец Кэдрелл", tgt="Горный пехотинец Кэдрелл", tag="Требуются материалы", desc="Горный пехотинец Кэдрелл ходит туда-обратно по дороге через Телсамар (32.6, 49.7 - 36.8, 42.0). Если его здесь нет, идите вдоль дороги."}, [99]={desc="Если камень возвращения еще на перезарядке, слетайте из Телсамара в Стальгорн, а затем на подземном поезде доберитесь до Штормграда."}, [100]={npc="Торгрум Боррелсон", tgt="Торгрум Боррелсон"}, [101]={npc="Торгрум Боррелсон", tgt="Торгрум Боррелсон"}, [102]={to="Стальгорн", desc="Если Стальгорна нет на карте полетов, идите на запад через перевал обратно в Дун Морог и по большой дороге войдите в Стальгорн."}, [103]={npc="Голнир Твердопал", tgt="Голнир Твердопал"}, [104]={npc="Голнир Твердопал", tgt="Голнир Твердопал"}, [105]={npc="Лаго Злобноверт", tgt="Лаго Злобноверт", desc="Люди-чернокнижники берут «Приглашение Гакина» в Златоземье, так что это задание пропускайте."}, [106]={npc="Грит Турден", tgt="Грит Турден"}, [107]={npc="Балтус Шлифовальщик", tgt="Балтус Шлифовальщик", tag="Необязательно"}, [108]={npc="Гретта Остроигл", tgt="Гретта Остроигл", tag="Необязательно"}, [109]={npc="Рейна Каменная Ветвь", tgt="Рейна Каменная Ветвь", tag="Необязательно"}, [110]={npc="Утрар Трекс", tgt="Утрар Трекс", tag="Необязательно"}, [111]={text="Из Стальгорна сядьте на подземный поезд до Штормграда."}, [112]={npc="Фьюрен Длиннобород", tgt="Фьюрен Длиннобород"}, [113]={npc="Верховная жрица Лорена", tgt="Верховная жрица Лорена"}, [114]={npc="Верховная жрица Лорена", tgt="Верховная жрица Лорена"}, [116]={text="Привяжите камень возвращения в таверне Штормграда (60.50, 75.20)."}, [117]={text="Блесна"}, [118]={text="Выползки"}, [119]={npc="Гилберт Грей", tgt="Гилберт Грей"}, [120]={npc="Гилберт Грей", tgt="Гилберт Грей"}, [121]={to="Аубердин", from="Stormwind", desc="Садитесь на корабль у причала в порту Штормграда."}}},
    ["02-10"] = {steps={[1]={npc="Бацбах Кривошип", tgt="Бацбах Кривошип"}, [2]={npc="Гвеннид Блай'Леггонд", tgt="Гвеннид Блай'Леггонд"}, [3]={node="Аубердин"}, [4]={hint="Добудьте 6 ножек крабов и поместите их в Жужжалку 827.", desc="Собирайте лапы крабов 9-10-го уровня на берегу южнее Аубердина. Если задания о выброшенном на берег существе у вас ещё нет, возьмите его, когда в следующий раз будете у причала на уровне 11 или выше."}, [5]={hint="Соберите кости морской твари, выброшенной на берег к югу от Аубердина, и принесите их Гвеннид Блай'Леггонд в Аубердин."}, [6]={npc="Жужжалка 827", npcObj=true}, [7]={npc="Жужжалка 827", npcObj=true}, [8]={npc="Гвеннид Блай'Леггонд", tgt="Гвеннид Блай'Леггонд"}, [9]={npc="Гвеннид Блай'Леггонд", tgt="Гвеннид Блай'Леггонд"}, [10]={hint="Принесите 8 партий элунитовой руды и медальон Элуры Эланарии из Дарнасса."}, [11]={npc="Кириллиан Белый Коготь", tgt="Кириллиан Белый Коготь"}, [12]={hint="Извлеките останки морской черепахи из скелета морской черепахи, лежащего в воде к западу от Аубердина, а затем поговорите с Гвеннид Блай'Леггонд в Аубердине."}, [13]={hint="Добудьте 3 глаза крепкозуба с крепкозубов Темного Берега, которые водятся в море неподалеку от Жужжалки 411."}, [14]={npc="Тандрис Ветропряд", tgt="Тандрис Ветропряд"}, [15]={npc="Тандрис Ветропряд", tgt="Тандрис Ветропряд"}, [16]={npc="Тарнариун Исцелитель Деревьев", tgt="Тарнариун Исцелитель Деревьев"}, [17]={npc="Терентис", tgt="Терентис"}, [18]={hint="Поймайте бешеного колючешерстного медведя отведите его Тарнариуну."}, [19]={hint="Посыпьте лунной пылью Кенария камень лунного совуха в Аубердине, чтобы вызвать Лунокогтя. Победите Лунокогтя, чтобы получить силу его тела и духа."}, [20]={npc="Астерион", tgt="Астерион"}, [21]={npc="Астерион", tgt="Астерион"}, [22]={hint="Соберите 8 серег греллей для Астериона в Башал'Аране."}, [23]={npc="Астерион", tgt="Астерион"}, [24]={npc="Астерион", tgt="Астерион"}, [25]={hint="Добудьте древнюю печать из лунного камня и принесите ее Астериону в Башал'Аран."}, [26]={npc="Астерион", tgt="Астерион"}, [27]={npc="Астерион", tgt="Астерион"}, [28]={npc="Тарнариун Исцелитель Деревьев", tgt="Тарнариун Исцелитель Деревьев"}, [29]={npc="Тарнариун Исцелитель Деревьев", tgt="Тарнариун Исцелитель Деревьев"}, [30]={npc="Часовой Глинда Нал'Шия", tgt="Часовой Глинда Нал'Шия"}, [31]={npc="Баритас Лунный Сумрак", tgt="Баритас Лунный Сумрак"}, [32]={npc="Розыск: Глубомрак!", npcObj=true}, [33]={npc="Гвеннид Блай'Леггонд", tgt="Гвеннид Блай'Леггонд"}, [34]={hint="Направляйтесь на восток от Аубердина и поищите большой красный кристалл в горной гряде на востоке Темного Берега. Вернитесь с докладом к часовому Глинде Нал'Шие в Аубердин."}, [35]={npc="Часовой Тиша Лунный Клинок", tgt="Часовой Тиша Лунный Клинок"}, [36]={hint="Изучите таблички, рассказывающие об Амет'Аране и его падении, а затем возвращайтесь к часовому Тише Лунный Клинок, находящейся на Темных берегах."}, [37]={hint="Освободите дух Анайи Вестницы Рассвета и принесите ее подвеску Кириллиану Белому Когтю в Аубердин."}, [38]={hint="Добудьте 7 реликвий высокорожденных для Тандриса Ветропряда в Аубердине."}, [39]={hint="Уничтожьте древнюю печать из лунного камня у древнего огня в Амет'Аране, затем вернитесь к Астериону в Башал'Аран."}, [40]={hint="Найдите и убейте сову Джай'ванель и добудьте одно из ее перьев. Эту черную сову видели к северу от руин Амет'Арана у подножия горы. Доложите о смерти Джай'ванель часовому Глинде Нал'Шии в Аубердине."}, [41]={npc="Часовой Тиша Лунный Клинок", tgt="Часовой Тиша Лунный Клинок"}, [42]={npc="Выброшенная на берег морская черепаха", npcObj=true, desc="Идите на юг и бейте бешеных колючешерстных медведей, также около 38, 60. Остановитесь на 6-10."}, [43]={hint="Найдите оскверненный лагерь фурболгов на Темном Берегу и вернитесь к Терентису в Аубердин."}, [44]={npc="Гвеннид Блай'Леггонд", tgt="Гвеннид Блай'Леггонд"}, [45]={npc="Кириллиан Белый Коготь", tgt="Кириллиан Белый Коготь"}, [46]={npc="Часовой Глинда Нал'Шия", tgt="Часовой Глинда Нал'Шия"}, [47]={npc="Часовой Глинда Нал'Шия", tgt="Часовой Глинда Нал'Шия", desc="Наполните пустую колбу для воды у ближайшего лунного колодца."}, [48]={npc="Часовой Глинда Нал'Шия", tgt="Часовой Глинда Нал'Шия"}, [49]={npc="Терентис", tgt="Терентис"}, [50]={npc="Терентис", tgt="Терентис"}, [51]={npc="Терентис", tgt="Терентис"}, [52]={npc="Часовой Элисса Звездный Ветер", tgt="Часовой Элисса Звездный Ветер"}, [53]={npc="Тандрис Ветропряд", tgt="Тандрис Ветропряд"}, [54]={npc="Тандрис Ветропряд", tgt="Тандрис Ветропряд"}, [55]={npc="Тандрис Ветропряд", tgt="Тандрис Ветропряд"}, [56]={npc="Тандрис Ветропряд", tgt="Тандрис Ветропряд"}, [57]={hint="Убейте 8 следопытов и 5 заклинателей ветра из клана Чернолесья, а затем вернитесь к Терентису в Аубердин."}, [58]={desc="Если камень возвращения не привязан к Штормграду или на перезарядке, сядьте на корабль в порту Аубердина и плывите в Штормград."}, [59]={to="Stormwind", from="Аубердин"}, [60]={text="Привяжите камень возвращения в таверне Штормграда (60.50, 75.20)."}}},
    ["02-11"] = {steps={[1]={node="Stormwind"}, [2]={npc="Ильса Корбин", tgt="Ильса Корбин", tag="Необязательно", desc="Вводное задание можно пропустить: сразу идите к Гарри Берлгарду в Штормграде и берите Бартлби Пьянь."}, [3]={npc="Гарри Берлгард", tgt="Гарри Берлгард", tag="Необязательно", desc="Вводное задание можно пропустить: сразу идите к Гарри Берлгарду в Штормграде и берите Бартлби Пьянь."}, [4]={npc="Гарри Берлгард", tgt="Гарри Берлгард"}, [5]={npc="Бартлби", tgt="Бартлби"}, [6]={npc="Бартлби", tgt="Бартлби", desc="Поговорите с Бартлби, и он нападет. Деритесь, пока он не сдастся."}, [7]={hint="Побейте Бартлби и снова поговорите с ним.", desc="Поговорите с Бартлби, и он нападет. Деритесь, пока он не сдастся."}, [8]={npc="Бартлби", tgt="Бартлби", desc="Поговорите с Бартлби, и он нападет. Деритесь, пока он не сдастся."}, [9]={npc="Бартлби", tgt="Бартлби"}, [10]={npc="Гарри Берлгард", tgt="Гарри Берлгард"}, [11]={npc="Гарри Берлгард", tgt="Гарри Берлгард"}, [12]={npc="Маршал Хаггард", tgt="Маршал Хаггард"}, [13]={npc="Маршал Хаггард", tgt="Маршал Хаггард", desc="Джек Мертвозуб в лагере к северу от Лесопилки Восточной долины в Элвиннском лесу."}, [14]={hint="Добыть знак маршала Хаггарда из лагеря Джека Мертвозуба и вернуться к маршалу Хаггарду.", desc="Джек Мертвозуб в лагере к северу от Лесопилки Восточной долины в Элвиннском лесу."}, [15]={npc="Маршал Хаггард", tgt="Маршал Хаггард", desc="Джек Мертвозуб в лагере к северу от Лесопилки Восточной долины в Элвиннском лесу."}, [16]={text="От Лесопилки Восточной долины идите по главной дороге Элвиннского леса на запад, через Златоземье и по мосту в Западный Край."}, [17]={npc="Гакин Темнопряд", tgt="Гакин Темнопряд"}, [18]={npc="Ремен Маркот", tgt="Ремен Маркот", tag="Необязательно", desc="Вводное задание людей из Златоземья. Можно сразу идти к Гакину Темнопряду и брать Сурена Каледон."}, [19]={npc="Гакин Темнопряд", tgt="Гакин Темнопряд", tag="Необязательно", desc="Вводное задание людей из Златоземья. Можно сразу идти к Гакину Темнопряду и брать Сурена Каледон."}, [20]={npc="Гакин Темнопряд", tgt="Гакин Темнопряд", desc="Сурена Каледон в доме у тыквенного поля Брэквеллов в Элвиннском лесу."}, [21]={hint="Верните колье Кровавого камня Гакину Темной Вязи в Штормград.", desc="Сурена Каледон в доме у тыквенного поля Брэквеллов в Элвиннском лесу."}, [22]={npc="Гакин Темнопряд", tgt="Гакин Темнопряд", desc="Сурена Каледон в доме у тыквенного поля Брэквеллов в Элвиннском лесу."}, [23]={npc="Гакин Темнопряд", tgt="Гакин Темнопряд", desc="Используйте предмет у круга призыва рядом с Гакином Темнопрядом и победите Призванного демона Бездны."}, [24]={hint="С помощью колье Кровавого камня призовите и подчините демона Бездны, затем верните колье Кровавого камня Гакину Темнопряду.", desc="Используйте предмет у круга призыва рядом с Гакином Темнопрядом и победите Призванного демона Бездны."}, [25]={npc="Гакин Темнопряд", tgt="Гакин Темнопряд", desc="Используйте предмет у круга призыва рядом с Гакином Темнопрядом и победите Призванного демона Бездны."}, [26]={npc="Залдимар Вефхеллт", tgt="Залдимар Вефхеллт", tag="Необязательно", desc="Вводное задание можно пропустить: сразу идите к Джиннии Пушке в квартале магов Штормграда и берите Зеркальное озеро."}, [27]={npc="Джинния Пушка", tgt="Джинния Пушка", tag="Необязательно", desc="Вводное задание можно пропустить: сразу идите к Джиннии Пушке в квартале магов Штормграда и берите Зеркальное озеро."}, [28]={npc="Джинния Пушка", tgt="Джинния Пушка"}, [29]={hint="Отнесите пробу воды из Зеркального озера Джиннии Пушке из Штормграда."}, [30]={npc="Джинния Пушка", tgt="Джинния Пушка"}, [31]={npc="Керин Сильвиус", tgt="Керин Сильвиус", desc="Задание «Держи-хватай!» можно взять только после сдачи этого вводного задания."}, [32]={npc="Мастер Матиас Шоу", tgt="Мастер Матиас Шоу", desc="Задание «Держи-хватай!» можно взять только после сдачи этого вводного задания."}, [33]={npc="Мастер Матиас Шоу", tgt="Мастер Матиас Шоу"}, [34]={hint="Найдите портового началь