    ["02-16"] = {steps={[1]={npc="Тандрис Ветропряд", tgt="Тандрис Ветропряд"}, [2]={npc="Тарнариун Исцелитель Деревьев", tgt="Тарнариун Исцелитель Деревьев"}, [3]={npc="Гершал Шепот Ночи", tgt="Гершал Шепот Ночи"}, [4]={npc="Гвеннид Блай'Леггонд", tgt="Гвеннид Блай'Леггонд"}, [5]={text="Из Аубердина летите в Деревню Рут'теран (если ее нет на карте полетов, плывите на корабле) и через портал в деревне пройдите в Дарнасс."}, [6]={npc="Матиль", tgt="Матиль"}, [7]={npc="Матиль", tgt="Матиль"}, [8]={hint="Принесите 20 кусков высохшей на солнце скорлупы Матилю из Дарнасса."}, [9]={npc="Матиль", tgt="Матиль"}, [10]={npc="Матиль", tgt="Матиль"}, [11]={npc="Матиль", tgt="Матиль"}, [12]={text="Вернитесь через портал в Деревню Рут'теран и летите в Аубердин, чтобы вернуться на маршрут."}, [13]={text="Из Аубердина летите в Деревню Рут'теран (если ее нет на карте полетов, плывите на корабле) и через портал в деревне пройдите в Дарнасс."}, [14]={npc="Жрица Алатея", tgt="Жрица Алатея", desc="Изучите «Милосердие Элуны»."}, [15]={npc="Жрица Алатея", tgt="Жрица Алатея", desc="Изучите «Милосердие Элуны»."}, [16]={text="Вернитесь через портал в Деревню Рут'теран и летите в Аубердин, чтобы вернуться на маршрут."}, [17]={text="Из Аубердина летите в Деревню Рут'теран (если ее нет на карте полетов, плывите на корабле) и через портал в деревне пройдите в Дарнасс."}, [18]={npc="Матренгил Медвежья Лапа", tgt="Матренгил Медвежья Лапа"}, [19]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [20]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [21]={npc="Аватара Сэйлинан", tgt="Аватара Сэйлинан", desc="Аватара Сэйлинан находится в южной части Лунной поляны."}, [22]={npc="Аватара Сэйлинан", tgt="Аватара Сэйлинан"}, [23]={hint="Добудьте реликвию клыка, реликвию когтя и реликвию тихой тени в кельях Малфуриона, а затем отнесите их аватаре Сэйлинана.", desc="У входа в Кельи Малфуриона используйте статую, дающую незаметность, и возьмите по одной реликвии каждого из трех видов."}, [24]={npc="Аватара Сэйлинан", tgt="Аватара Сэйлинан"}, [25]={npc="Аватара Сэйлинан", tgt="Аватара Сэйлинан"}, [26]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд", desc="Вернитесь в Ночную Гавань и сдайте задание Дендриту Блеску Звезд."}, [27]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [28]={npc="Дух Великой Кошки", tgt="Дух Великой Кошки"}, [29]={npc="Дух Великой Кошки", tgt="Дух Великой Кошки"}, [30]={hint="Добудьте реликвию клыка, реликвию когтя и реликвию тихой тени в кельях Малфуриона, а затем отнесите их духу Великой Кошки."}, [31]={npc="Дух Великой Кошки", tgt="Дух Великой Кошки"}, [32]={npc="Дух Великой Кошки", tgt="Дух Великой Кошки"}, [33]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [34]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [35]={npc="Матренгил Медвежья Лапа", tgt="Матренгил Медвежья Лапа", desc="Найдите в Ночной Гавани Сильву Фил'навет, слетайте на рейсе только для друидов в Деревню Рут'теран и войдите в Дарнас через портал в деревне."}, [36]={text="Вернитесь через портал в Деревню Рут'теран и летите в Аубердин, чтобы вернуться на маршрут."}, [37]={npc="Ону", tgt="Ону"}, [38]={npc="Арбал", tgt="Арбал"}, [39]={npc="Волкор", tgt="Волкор", desc="Задание на сопровождение: в группе берите, когда у всех одинаковый прогресс, и отключите автопринятие."}, [40]={npc="Волкор", tgt="Волкор"}, [41]={hint="Защищайте Волкора, пока не доберетесь до дороги, а затем поговорите с Терентисом в Аубердине."}, [42]={text="С юга Темных берегов идите по дороге на юг в Ясеневый лес и сначала дойдите до Заставы Маэстры.", tag="Маршрут полета еще не открыт. В первый раз доберитесь туда пешком."}, [43]={npc="Часовой Ойнея", tgt="Часовой Ойнея"}, [44]={npc="Делгрен Очиститель", tgt="Делгрен Очиститель"}, [45]={npc="Делгрен Очиститель", tgt="Делгрен Очиститель"}, [46]={npc="Орендил Широколист", tgt="Орендил Широколист"}, [47]={hint="Добудьте светящийся самоцвет Души и вернитесь к Делгрену Очистителю на заставу Мейстры."}, [48]={hint="Принесите 5 стеблей Батранова волоса Орендилу Широколисту в Ясеневый лес."}, [49]={npc="Орендил Широколист", tgt="Орендил Широколист"}, [50]={npc="Орендил Широколист", tgt="Орендил Широколист"}, [51]={npc="Делгрен Очиститель", tgt="Делгрен Очиститель"}, [52]={npc="Делгрен Очиститель", tgt="Делгрен Очиститель"}, [53]={npc="Тересиль", tgt="Тересиль"}, [54]={nodeA="{a:415}", node="Astranaar"}, [55]={npc="Шиндрелл Огненный Всполох", tgt="Шиндрелл Огненный Всполох"}, [56]={npc="Часовой Тенисил", tgt="Часовой Тенисил"}, [57]={npc="Раэна Волкопас", tgt="Раэна Волкопас"}, [58]={npc="Пельтур Белая Луна", tgt="Пельтур Белая Луна"}, [59]={npc="Пельтур Белая Луна", tgt="Пельтур Белая Луна"}, [60]={npc="Труп Терониса", tgt="Труп Терониса"}, [61]={npc="Труп Терониса", tgt="Труп Терониса"}, [62]={hint="Найдите светящийся самоцвет и вернитесь к Раэне Волкопас в Астранаар с дневником Терониса."}, [63]={npc="Тален", tgt="Тален"}, [64]={hint="Принесите древнюю статуэтку Талену в его лагерь близ Зорамского взморья."}, [65]={npc="Тален", tgt="Тален"}, [66]={npc="Тален", tgt="Тален"}, [67]={hint="Принесите кольцо Зорама Талену на Зорамское взморье.", tag="Необязательно", desc="На Руузеля идите только с группой. Маги, чернокнижники и охотники могут попробовать в одиночку."}, [68]={hint="Принесите 20 голов наг из клана Зловещего Хвоста Шиндрелл Огненный Всполох в Астранаар."}, [69]={npc="Тален", tgt="Тален"}, [70]={npc="Шиндрелл Огненный Всполох", tgt="Шиндрелл Огненный Всполох"}, [71]={npc="Раэна Волкопас", tgt="Раэна Волкопас"}, [72]={npc="Ллана", tgt="Ллана", desc="Просто доставка: плывите на корабле в Гавань Менетилов и сдайте Кейтлин Грассман; если еще нет 24-го уровня, не берите, возвращаться за ним не нужно."}, [73]={to="Аубердин"}, [74]={to="Menethil Harbor", toA="{a:150}", from="Аубердин", desc="В Аубердине сядьте на корабль до Гавани Менетилов и сойдите на следующей остановке."}}},
    ["05-d15"] = {name="Пещеры Стенаний", entrance="Степи 46.00, 36.30", tips={{k="取捨", text="Для заданий «Светящийся осколок», «Неприятности в порту» и «Умный напиток» нужно ехать в Кабестан. Альянс к этому моменту Кабестан еще не открыл, поэтому они не включены."}, {k="說明", text="Вход во внешнюю пещеру находится примерно на 47.70, 35.00. От Цветущего оазиса войдите в каменную пещеру и пройдите по туннелю: портал находится глубже. Налпак и Эбру ждут в небольшой пещере над внешним входом: сначала возьмите у них квесты, затем спускайтесь.", s={{"Вход во внешнюю пещеру находится примерно на 47.70, 35.00"}, {"От Цветущего оазиса войдите в каменную пещеру и пройдите по туннелю: портал находится глубже"}, {"Налпак и Эбру ждут в небольшой пещере над внешним входом: сначала возьмите у них квесты, затем спускайтесь"}}}}, steps={[1]={text="Необязательное и далекое подземелье: перед посадкой на корабль в Аубердине вернитесь полетом в Астранаар. Идите по дороге на восток, по восточной дороге Ясеневого леса спуститесь на юг мимо Стены Мор'шан в Степи и по северной дороге идите на юг до оазиса к юго-западу от Перекрестка, там вход в пещеру. Весь путь проходит по территории Орды. После подземелья, если камень возвращения готов, вернитесь в Штормград, сядьте на корабль до Аубердина в порту Штормграда, а там пересядьте на корабль до Гавани Менетилов. Только если камень возвращения на перезарядке, вернитесь пешком в Астранаар, летите в Аубердин и садитесь на корабль. Продолжайте с {s:02-21}.", tag="Необязательно"}, [2]={npc="Налпак", tgt="Налпак"}, [3]={npc="Эбру", tgt="Эбру"}, [4]={text="Вход: Пещеры Стенаний"}, [5]={hint="Принесите 20 искаженных шкур Налпаку в Пещерах Стенаний.", desc="Deviate Slayers находятся во внешней пещере перед входом в подземелье. Место: Зачистите мутировавших зверей на мелких развилках и обоих флангах, собирая шкуры по пути к боссам.", spot="Убивайте измененных зверей на мелководной развилке и в обоих крыльях, снимайте шкуры по пути к боссам."}, [6]={hint="Убейте для Эбру 7 загадочных опустошителей, 7 загадочных гадюк, 7 загадочных шаркунов и 7 загадочных страхозубов.", desc="Место: Сначала зачистите мелководную развилку, затем добейте все четыре вида мобов в западном и восточном крыльях.", spot="Сначала зачистите мелководную развилку, затем добейте все четыре вида мобов в западном и восточном крыльях."}, [7]={npc="Налпак", tgt="Налпак"}, [8]={npc="Эбру", tgt="Эбру"}}},
    ["02-21"] = {steps={[1]={npc="Джеймс Халлоран", tgt="Джеймс Халлоран"}, [2]={npc="Карл Боран", tgt="Карл Боран"}, [3]={nodeA="{a:150}", node="Menethil Harbor"}, [4]={npc="Первый помощник Фитсиммонс", tgt="Первый помощник Фитсиммонс"}, [5]={npc="Первый помощник Фитсиммонс", tgt="Первый помощник Фитсиммонс"}, [6]={text="Кружка дворфийской медовухи", npc="Хозяин таверны Хелбрек"}, [7]={npc="Археолог Бутылопуз", tgt="Археолог Бутылопуз"}, [8]={npc="Археолог Бутылопуз", tgt="Археолог Бутылопуз"}, [9]={npc="Первый помощник Фитсиммонс", tgt="Первый помощник Фитсиммонс"}, [10]={npc="Кейтлин Грассман", tgt="Кейтлин Грассман"}, [11]={npc="Кейтлин Грассман", tgt="Кейтлин Грассман"}, [12]={npc="Сида", tgt="Сида"}, [13]={npc="Валстаг Сталезуб", tgt="Валстаг Сталезуб"}, [14]={npc="Таррел Камнепряд", tgt="Таррел Камнепряд"}, [15]={npc="Таррел Камнепряд", tgt="Таррел Камнепряд"}, [16]={hint="Добудьте для Валстага Сталезуба 6 ед. каз-моданской древесины и 30 ед. каз-моданского железа в Гавани Менетилов."}, [17]={hint="Убейте 12 мурлоков из племени Синежабрых.", desc="Дальше по пути бейте молодых болотных кроколисков ради шкур."}, [18]={text="Сначала идите по главной дороге на восток, а у развилки к северу от раскопок спуститесь на юг."}, [19]={npc="Ормер Сталеплет", tgt="Ормер Сталеплет"}, [20]={npc="Меррин Камнепряд", tgt="Меррин Камнепряд"}, [21]={npc="Меррин Камнепряд", tgt="Меррин Камнепряд"}, [22]={hint="Археолог Бутылопуз в Гавани Менетилов хочет, чтобы вы принесли ему камень Релу и окаменелость Бутылопуза."}, [23]={hint="Убейте 10 крапчатых ящеров и 10 крапчатых крикунов."}, [24]={npc="Ормер Сталеплет", tgt="Ормер Сталеплет"}, [25]={hint="Принесите 6 |4шкуру:шкуры:шкур; молодых кроколисков Джеймсу Халлорану в Гавань Менетилов."}, [26]={npc="Ретиль Страж Природы", tgt="Ретиль Страж Природы"}, [27]={npc="Ретиль Страж Природы", tgt="Ретиль Страж Природы"}, [28]={hint="Добудьте нелопнувшую железу хищника в пещере Тельгена для Кейтлин Грассман в Гавани Менетилов."}, [29]={hint="Убейте 15 гноллов из стаи Мохошкуров и 10 полукровок из стаи Мохошкуров. Вернитесь к Ретилю Стражу Природы в Болотину."}, [30]={npc="Ретиль Страж Природы", tgt="Ретиль Страж Природы"}, [31]={npc="Ретиль Страж Природы", tgt="Ретиль Страж Природы"}, [32]={hint="Принесите Ретилю Стражу Природы 9 необработанных кремней."}, [33]={hint="Отнимите сумку Сиды у неизвестного слизнюка возле гробницы Железноборода и верните ее хозяйке в Гавань Менетилов."}, [34]={npc="Ретиль Страж Природы", tgt="Ретиль Страж Природы"}, [35]={npc="Ретиль Страж Природы", tgt="Ретиль Страж Природы"}, [36]={hint="Убейте 12 трясинных ползунов и вернитесь к Ретилю Стражу Природы в Болотину."}, [37]={npc="Ретиль Страж Природы", tgt="Ретиль Страж Природы"}, [38]={npc="Карл Боран", tgt="Карл Боран"}, [39]={npc="Карл Боран", tgt="Карл Боран"}, [40]={npc="Джеймс Халлоран", tgt="Джеймс Халлоран"}, [41]={npc="Джеймс Халлоран", tgt="Джеймс Халлоран"}, [42]={npc="Валстаг Сталезуб", tgt="Валстаг Сталезуб"}, [43]={npc="Сида", tgt="Сида"}, [44]={npc="Кейтлин Грассман", tgt="Кейтлин Грассман"}, [45]={npc="Археолог Бутылопуз", tgt="Археолог Бутылопуз"}, [46]={npc="Таррел Камнепряд", tgt="Таррел Камнепряд"}, [47]={npc="Поврежденный ящик", npcObj=true}, [48]={npc="Поврежденный ящик", npcObj=true}, [49]={npc="Запечатанная бочка", npcObj=true}, [50]={npc="Запечатанная бочка", npcObj=true}, [51]={npc="Полузакопанная бочка", npcObj=true}, [52]={npc="Полузакопанная бочка", npcObj=true}, [53]={hint="Принесите 6 шкур гигантских кроколисков Джеймсу Халлорану в Гавань Менетилов."}, [54]={npc="Джеймс Халлоран", tgt="Джеймс Халлоран"}, [55]={npc="Джеймс Халлоран", tgt="Джеймс Халлоран"}, [56]={npc="Карл Боран", tgt="Карл Боран"}, [57]={npc="Карл Боран", tgt="Карл Боран"}, [58]={npc="Капитан Крепкий Кулак", tgt="Капитан Крепкий Кулак"}, [59]={npc="Капитан Крепкий Кулак", tgt="Капитан Крепкий Кулак"}, [60]={npc="Элдрун Тучегон", tgt="Элдрун Тучегон"}, [61]={npc="Норрик Тан Лока", tgt="Норрик Тан Лока"}, [62]={npc="Норрик Тан Лока", tgt="Норрик Тан Лока"}, [63]={npc="Гервдана Саэгрунд", tgt="Гервдана Саэгрунд"}, [64]={npc="Гервдана Саэгрунд", tgt="Гервдана Саэгрунд"}, [65]={hint="Наполните пустой коричневый бурдюк для воды у подножия водопадов под пещерой Гервданы в Болотине и отнесите ей воду."}, [66]={npc="Гервдана Саэгрунд", tgt="Гервдана Саэгрунд"}, [67]={npc="Гервдана Саэгрунд", tgt="Гервдана Саэгрунд"}, [68]={hint="Наполните пустой красный бурдюк для воды из водопада Каменной Стражи неподалеку от мурлоков-следопытов и отнесите воду Гервдане Саэгрунд в Болотину."}, [69]={npc="Гервдана Саэгрунд", tgt="Гервдана Саэгрунд"}, [70]={npc="Гервдана Саэгрунд", tgt="Гервдана Саэгрунд"}, [71]={hint="Наполните пустой синий бурдюк для воды в водах Астранаара в Ясеневом лесу и отнесите воду Гервдане Саэгрунд в Болотину.", desc="Сядьте на северной пристани Гавани Менетилов на корабль до Аубердина (по пути он заходит в Южнобережье; выходить не нужно), затем летите в Астранаар за водой. На обратном пути летите в Аубердин, плывите на корабле в Гавань Менетилов и идите пешком обратно к пещере Гервданы."}, [72]={npc="Гервдана Саэгрунд", tgt="Гервдана Саэгрунд"}, [73]={npc="Гервдана Саэгрунд", tgt="Гервдана Саэгрунд"}, [74]={npc="Норрик Тан Лока", tgt="Норрик Тан Лока"}, [75]={npc="Норрик Тан Лока", tgt="Норрик Тан Лока"}, [76]={npc="Норрик Тан Лока", tgt="Норрик Тан Лока"}, [77]={npc="Норрик Тан Лока", tgt="Норрик Тан Лока"}, [78]={hint="Выпейте сапту воды и очистите пруд Стенделя от скверны в Западном Крае.", desc="Летите из Телсамара на Сторожевой холм (с пересадками в Стальгорне и Штормграде) и идите к пруду рядом с Забытым алтарем."}, [79]={npc="Забытое святилище", npcObj=true}, [80]={npc="Забытое святилище", npcObj=true}, [81]={npc="Низшее воплощение воды", tgt="Низшее воплощение воды", desc="Малые духи воды стоят у святилища рядом с прудом в Западном Крае."}, [82]={npc="Низшее воплощение воды", tgt="Низшее воплощение воды"}, [83]={npc="Норрик Тан Лока", tgt="Норрик Тан Лока", desc="Летите со Сторожевого холма в Телсамар."}, [84]={}}},
    ["05-d6"] = {name="Excavation Site: Wetlands", nameA="{a:16732}", entrance="Болотина 47.79, 56.16", pickup="Возьмите задание у Кейтлин в гавани Менетилов.", pickupS={{"Возьмите задание у Кейтлин в гавани Менетилов"}}, steps={[1]={npc="Ретиль Страж Природы", tgt="Ретиль Страж Природы", tag="Необязательно"}, [2]={npc="Ретиль Страж Природы", tgt="Ретиль Страж Природы", tag="Необязательно, Делайте с группой"}, [3]={npc="Джеймс Халлоран", tgt="Джеймс Халлоран", tag="Необязательно"}, [4]={npc="Джеймс Халлоран", tgt="Джеймс Халлоран", tag="Необязательно, Делайте с группой"}, [5]={npc="Кейтлин Грассман", tgt="Кейтлин Грассман"}, [6]={npc="Кейтлин Грассман", tgt="Кейтлин Грассман"}, [7]={text="Требуется: В поисках Поющего Клинка", tag="Необязательно, Делайте с группой"}, [8]={text="Если вы уже вернулись камнем возвращения в Штормград, сначала летите в Гавань Менетилов, а оттуда идите по главной дороге Болотины на восток до раскопок."}, [9]={text="Вход: Excavation Site: Wetlands"}, [10]={hint="Отнесите 4 |4шкуру:шкуры:шкур; чащобного ящера кожевнику Джеймсу Халлорану в Гавань Менетилов.", tag="Необязательно, Делайте с группой"}, [11]={hint="Убейте Ужас нагорья на раскопках и принесите его корень Ретилю Стражу Природы в Болотину.", tag="Необязательно, Делайте с группой"}, [12]={hint="Найдите Ардина Грассмана на раскопках."}, [13]={}, [14]={}, [15]={hint="Поищите брата Дорина Поющий Клинок, Дэвина, на раскопках Вельгара.", tag="Необязательно, Делайте с группой"}, [16]={npc="Daewyn Songblade", tag="Необязательно, Делайте с группой"}, [17]={npc="Daewyn Songblade", tag="Необязательно, Делайте с группой", desc="В следующий раз в Приозерье расскажите Дорину, что случилось с его братом."}, [18]={npc="Реликвия титанов", npcObj=true, tag="Необязательно, Берите, если выпал", desc="Если со Стража реликвии выпала реликвия титанов, щелкните по ней правой кнопкой мыши, чтобы начать задание."}, [19]={npc="Ретиль Страж Природы", tgt="Ретиль Страж Природы", tag="Необязательно, Делайте с гр