    ["02-17"] = {steps={[1]={to="Lakeshire", toA="{a:69}", tag="Маршрут полета еще не открыт. В первый раз доберитесь туда пешком.", desc="Если пункт полета в Темнолесье открыт, летите прямо в Темнолесье. Если нет, летите в Приозерье, оттуда по дороге на запад дойдите до развилки на западной окраине Красногорья и идите на юг через Сумеречный лес до Темнолесья."}, [2]={npc="Мадам Ева", tgt="Мадам Ева", desc="Проходя Сумеречный лес, бейте пауков ради липких паучьих лапок."}, [3]={npc="Мадам Ева", tgt="Мадам Ева"}, [4]={npc="Клерк Далтри", tgt="Клерк Далтри"}, [5]={npc="Клерк Далтри", tgt="Клерк Далтри"}, [6]={npc="Шира Фон-Инди", tgt="Шира Фон-Инди"}, [7]={npc="Командир Алтея Чернодрев", tgt="Командир Алтея Чернодрев"}, [8]={npc="Илана Карвин", tgt="Илана Карвин"}, [9]={npc="Илана Карвин", tgt="Илана Карвин"}, [10]={npc="Илана Карвин", tgt="Илана Карвин"}, [11]={nodeA="{a:42}", node="Darkshire"}, [12]={text="Бронзовая трубка", desc="Ограниченный товар. Покупайте, только если он есть и у вас его еще нет."}, [13]={npc="Виктор Призм'Антрас", tgt="Виктор Призм'Антрас", desc="Для цепочки заданий о звездах нужна бронзовая трубка. Если ее нет, сделайте сначала остальное, а трубку купите позже на аукционе."}, [14]={npc="Лук Меррика", npcObj=true, tag="Необязательно", desc="Щелкните правой кнопкой по предмету «Лук Меррика» в сумке, чтобы взять задание."}, [15]={npc="Бат'ра Ветростраж", tgt="Бат'ра Ветростраж", npcObj=true, tag="Необязательно", desc="Щелкните правой кнопкой по Кинжалу Иры в сумке, чтобы взять задание."}, [16]={npc="Виктор Призм'Антрас", tgt="Виктор Призм'Антрас"}, [17]={npc="Виктор Призм'Антрас", tgt="Виктор Призм'Антрас"}, [18]={npc="Слепая Мэри", tgt="Слепая Мэри"}, [19]={npc="Слепая Мэри", tgt="Слепая Мэри"}, [20]={hint="Заберите зеркало Слепой Мэри у Невменяемого Вурдалака и отдайте его Виктору в Темнолесье."}, [21]={hint="Убейте 8 скелетов-воинов и 6 магов-скелетов по просьбе командира Алтеи Чернодрев."}, [22]={npc="Дозорный Додс", tgt="Дозорный Додс"}, [2