    ["03-24"] = {name="Предгорья Хилсбрада", steps={[1]={to="Southshore", toA="{a:271}", from="Menethil Harbor", fromA="{a:150}", desc="Сядьте на корабль в Аубердин на северном причале Гавани Менетилов и сойдите по пути в Южнобережье."}, [2]={npc="Фин Оделик", tgt="Фин Оделик"}, [3]={npc="Лейтенант Фаррен Оринель", tgt="Лейтенант Фаррен Оринель"}, [4]={npc="Кабатчик Келли", tgt="Кабатчик Келли"}, [5]={npc="Мастер-пивовар Бочкопуз", tgt="Мастер-пивовар Бочкопуз"}, [6]={npc="Мировой судья Генри Малеб", tgt="Мировой судья Генри Малеб"}, [7]={npc="Даррен Малвей", tgt="Даррен Малвей", tag="Необязательно"}, [8]={hint="Убейте 10 волноловов из племени Порванного Плавника и 10 оракулов из племени Порванного Плавника по поручению лейтенанта Фаррена Оринеля из Южнобережья."}, [9]={npc="Лейтенант Фаррен Оринель", tgt="Лейтенант Фаррен Оринель"}, [10]={npc="Лейтенант Фаррен Оринель", tgt="Лейтенант Фаррен Оринель"}, [11]={hint="Соберите 10 голов мурлоков на Западном побережье по просьбе лейтенанта Фаррена Оринеля из Южнобережья."}, [12]={npc="Лейтенант Фаррен Оринель", tgt="Лейтенант Фаррен Оринель"}, [13]={npc="Лейтенант Фаррен Оринель", tgt="Лейтенант Фаррен Оринель"}, [14]={npc="Маршал Редпат", tgt="Маршал Редпат"}, [15]={npc="Маршал Редпат", tgt="Маршал Редпат"}, [16]={npc="Лейтенант Фаррен Оринель", tgt="Лейтенант Фаррен Оринель"}, [17]={npc="Лейтенант Фаррен Оринель", tgt="Лейтенант Фаррен Оринель"}, [18]={hint="Убейте 10 береговых охотников и 10 сирен из клана Пронзающего Гребня по просьбе лейтенанта Фаррена Оринеля из Южнобережья."}, [19]={hint="Отнесите бутылки с фолрукским сортовым вином в Дун Гарок в юго-восточной части предгорий Хилсбрада и принесите назад мешок их домашнего хмеля."}, [20]={npc="Лейтенант Фаррен Оринель", tgt="Лейтенант Фаррен Оринель"}, [21]={npc="Лейтенант Фаррен Оринель", tgt="Лейтенант Фаррен Оринель"}, [22]={npc="Мастер-пивовар Бочкопуз", tgt="Мастер-пивовар Бочкопуз"}, [23]={hint="Принесите главному каменотесу Стальгорна Мраморщику 5 кусков аль