    ["05-d16"] = {name="Даларан", entrance="Альтеракские горы 8.46, 59.21", pickup="При первом визите в Штормград возьмите «Зеленый образец» и «Переполняющая мощь». Когда в Предгорьях Хилсбрада достигнете 30 уровня, возьмите «Настораживающая просьба» у эмиссара Жака в Южнобережье.", pickupS={{"При первом визите в Штормград возьмите «Зеленый образец» и «Переполняющая мощь»"}, {"Когда в Предгорьях Хилсбрада достигнете 30 уровня, возьмите «Настораживающая просьба» у эмиссара Жака в Южнобережье"}}, tips={{k="說明", text="Изображение Модеры и настоящий портал находятся в разных местах: идите со стороны канализации озера Лордамер. Для внешних ворот Даларана и NPC в городе действуют ограничения по фракции.", s={{"Изображение Модеры и настоящий портал находятся в разных местах: идите со стороны канализации озера Лордамер"}, {"Для внешних ворот Даларана и NPC в городе действуют ограничения по фракции"}}}}, steps={[1]={npc="Шайламиир", tgt="Шайламиир"}, [2]={npc="Верховный колдун Андромат", tgt="Верховный колдун Андромат"}, [3]={npc="Эмиссар Жак", tgt="Эмиссар Жак"}, [4]={text="Необязательно: летите из Штормграда в Южнобережье, идите на север через Предгорья Хилсбрада в Альтеракские горы, по северному берегу озера Лордамер идите на запад и найдите проекцию верховного мага Модеры у стоков Даларана. После подземелья вернитесь камнем возвращения в Штормград и продолжайте с {s:03-25}.", tag="Необязательно"}, [5]={npc="Проекция верховного мага Модеры", tgt="Проекция верховного мага Модеры"}, [6]={npc="Проекция верховного мага Модеры", tgt="Проекция верховного мага Модеры"}, [7]={npc="Проекция верховного мага Модеры", tgt="Проекция верховного мага Модеры", desc="При получении квеста вы получите ключ от стоков Даларана."}, [8]={text="Вход: Даларан"}, [9]={hint="Убейте 8 |4ищущий осколок:ищущих осколка:ищущих осколков;, 8 |4насыщенный осколок:насыщенных осколка:насыщенных осколков; и 8 |4отголосок:отголоска:отголосков; маны в стенах Даларана по просьбе верховного мага Модеры, ждущей за пределами города.", desc="Место: Зачищайте стоки и улицы по пути, там встретятся все три вида.", spot="Зачищайте стоки и улицы по пути, там встретятся все три вида"}, [10]={hint="Убейте элементаля маны в Даларане по просьбе верховного колдуна Андромата из Штормграда."}, [11]={hint="Найдите в Даларане пропитанный Скверной цветок по просьбе Шайламиир из Штормграда."}, [12]={hint="Близ Даларана добудьте частицу чар проекции верховного мага Модеры.", desc="Место: Войдите в портал в Фиолетовую Цитадель и убейте Тень Архимага в гостиной.", spot="Войдите в портал в Фиолетовую Цитадель и убейте Тень Архимага в гостиной."}, [13]={npc="Проекция верховного мага Модеры", tgt="Проекция верховного мага Модеры"}, [14]={npc="Проекция верховного мага Модеры", tgt="Проекция верховного мага Модеры"}, [15]={npc="Проекция верховного мага Модеры", tgt="Проекция верховного мага Модеры"}, [16]={npc="Archmage Celindra", tgt="Archmage Celindra"}, [17]={}, [18]={npc="Шайламиир", tgt="Шайламиир"}, [19]={npc="Верховный колдун Андромат", tgt="Верховный колдун Андромат"}}},
    ["03-25"] = {steps={[1]={npc="Ву Шен", tgt="Ву Шен"}, [3]={npc="Клавий Кнавингем", tgt="Клавий Кнавингем", tag="Необязательно"}, [4]={npc="Клавий Кнавингем", tgt="Клавий Кнавингем", tag="Необязательно", desc="Сдавайте, только если уже есть 60 шелкового материала."}, [5]={npc="Зардет Черный Коготь", tgt="Зардет Черный Коготь"}, [6]={npc="Зардет Черный Коготь", tgt="Зардет Черный Коготь"}, [7]={npc="Верховный маг Малин", tgt="Верховный маг Малин"}, [8]={npc="Лорд Грейсон Тенелом", tgt="Лорд Грейсон Тенелом"}, [9]={npc="Архиепископ Бенедикт", tgt="Архиепископ Бенедикт"}, [10]={npc="Гриманд Элмор", tgt="Гриманд Элмор"}, [11]={npc="Гриманд Элмор", tgt="Гриманд Элмор"}, [12]={npc="Шони Молшунья", tgt="Шони Молшунья", tag="Делайте с группой, Необязательно", desc="Сдавайте, только если прошли Гномреган и собрали все Механические внутренности робота."}, [13]={npc="Лорд Борлс К. Вишлок", tgt="Лорд Борлс К. Вишлок"}, [14]={npc="Майор Самуэльсон", tgt="Майор Самуэльсон"}, [15]={to="Darkshire", toA="{a:42}"}, [16]={npc="Мадам Ева", tgt="Мадам Ева"}, [17]={npc="Дозорный Бакус", tgt="Дозорный Бакус"}, [18]={npc="Дозорный Бакус", tgt="Дозорный Бакус"}, [19]={npc="Командир Алтея Чернодрев", tgt="Командир Алтея Чернодрев"}, [20]={hint="Убейте Сталвана Мистмантла и принесите мадам Эве его фамильное кольцо."}, [21]={npc="Мадам Ева", tgt="Мадам Ева"}, [22]={hint="Калор просит вас убить 8 Ярых Клыков из стаи Ночной Погибели и 8 нечистых воргенов из стаи Ночной Погибели."}, [23]={hint="Отыщите Ззарк'Вула в кургане на юге Сумеречного леса и принесите его монокль Виктору в Темнолесье."}, [24]={hint="Вернуть ящик Аберкромби владельцу."}, [25]={hint="Найдите декларацию Братства Справедливости и верните ее дозорному Бакусу в Сумеречном лесу."}, [26]={npc="Калор", tgt="Калор"}, [27]={npc="Калор", tgt="Калор"}, [28]={npc="Джонотан Карвин", tgt="Джонотан Карвин"}, [29]={npc="Дозорный Бакус", tgt="Дозорный Бакус"}, [30]={npc="Дозорный Бакус", tgt="Дозорный Бакус"}, [31]={npc="Виктор Призм'Антр