    ["03-26"] = {name="Тернистая долина", steps={[1]={npc="Свен Йорген", tgt="Свен Йорген"}, [2]={npc="Свен Йорген", tgt="Свен Йорген", tag="Необязательно, Делайте с группой"}, [3]={hint="Примените Проклятье Морбента против Морбента Скверна, убейте его и верните Проклятье Морбента в лагерь Свена.", tag="Необязательно, Делайте с группой", desc="Продолжение — элитные задания. Только в группе."}, [4]={npc="Свен Йорген", tgt="Свен Йорген", tag="Необязательно, Делайте с группой"}, [5]={text="С запада Сумеречного леса идите по дороге на юг в Тернистую долину и сначала дойдите до Лагеря повстанцев."}, [6]={npc="Рядовой Торсен", tgt="Рядовой Торсен", tag="Необязательно, Если встретили", desc="Он патрулирует дорогу и дает задание, только если спасти его, когда он попадет в засаду; не встретили — пропустите."}, [7]={npc="Сержант Йохва", tgt="Сержант Йохва"}, [8]={npc="Сержант Йохва", tgt="Сержант Йохва"}, [9]={npc="Лейтенант Дорен", tgt="Лейтенант Дорен", tag="Необязательно"}, [10]={npc="Лейтенант Дорен", tgt="Лейтенант Дорен"}, [11]={npc="Барнил Каменный Кубок", tgt="Барнил Каменный Кубок"}, [12]={npc="Хеминг Эрнестуэй", tgt="Хеминг Эрнестуэй"}, [13]={npc="Хеминг Эрнестуэй", tgt="Хеминг Эрнестуэй"}, [14]={npc="Барнил Каменный Кубок", tgt="Барнил Каменный Кубок", tag="Необязательно", desc="Страницы случайно падают с мобов Тернистой долины. Недостающие можно купить на аукционе. Сдавайте, когда соберёте все четыре главы."}, [15]={npc="Барнил Каменный Кубок", tgt="Барнил Каменный Кубок", tag="Необязательно"}, [16]={npc="Барнил Каменный Кубок", tgt="Барнил Каменный Кубок", tag="Необязательно"}, [17]={npc="Барнил Каменный Кубок", tgt="Барнил Каменный Кубок", tag="Необязательно"}, [18]={npc="Барнил Каменный Кубок", tgt="Барнил Каменный Кубок", tag="Необязательно"}, [19]={npc="Ажек Руак", tgt="Ажек Руак"}, [20]={npc="Сэр С. Дж. Эрлгедин", tgt="Сэр С. Дж. Эрлгедин"}, [21]={hint="Ажек Руак из экспедиции Эрнестуэя попросила вас убить 10 молодых тигров Тернистой долины."}, [22]={npc="Ажек Руак", tgt="Ажек Руак"}, [23]={npc="Ажек Руак", tgt="Ажек Руак"}, [24]={hint="Сэр С. Дж. Эрлгедин из экспедиции Эрнестуэя попросил вас убить 10 молодых пантер."}, [25]={hint="Ажек Руак из экспедиции Эрнестуэя попросила вас убить 10 тигров Тернистой долины."}, [26]={hint="Убейте 15 партизан Курцена."}, [27]={hint="Принесите сержанту Йохве из Лагеря повстанцев 7 порций зелья из джунглей и 1 порцию экстракта ядовитого папоротника."}, [28]={npc="Записи букмекера Герода", npcObj=true, desc="Документы в Лагере Курцена; продолжение выполняется в том же лагере — берите, если будет время."}, [29]={npc="Ажек Руак", tgt="Ажек Руак"}, [30]={npc="Ажек Руак", tgt="Ажек Руак"}, [31]={npc="Сэр С. Дж. Эрлгедин", tgt="Сэр С. Дж. Эрлгедин"}, [32]={npc="Сэр С. Дж. Эрлгедин", tgt="Сэр С. Дж. Эрлгедин"}, [33]={hint="Сэр С. Дж. Эрлгедин из экспедиции Эрнестуэя попросил вас убить 10 пантер."}, [34]={hint="Хеминг Эрнестуэй просит вас убить 10 ящеров Тернистой долины."}, [35]={hint="Ажек Руак из экспедиции Эрнестуэя попросила вас убить 10 старых тигров Тернистой долины."}, [36]={npc="Сэр С. Дж. Эрлгедин", tgt="Сэр С. Дж. Эрлгедин"}, [37]={npc="Сэр С. Дж. Эрлгедин", tgt="Сэр С. Дж. Эрлгедин"}, [38]={npc="Ажек Руак", tgt="Ажек Руак"}, [39]={npc="Ажек Руак", tgt="Ажек Руак"}, [40]={npc="Хеминг Эрнестуэй", tgt="Хеминг Эрнестуэй"}, [41]={npc="Хеминг Эрнестуэй", tgt="Хеминг Эрнестуэй"}, [42]={npc="Сержант Йохва", tgt="Сержант Йохва"}, [43]={npc="Сержант Йохва", tgt="Сержант Йохва"}, [44]={npc="Капрал Калеб", tgt="Капрал Калеб"}, [45]={text="Идите по дороге через Тернистую долину на юг до Пиратской Бухты и держитесь подальше от лагеря Орды возле Гром'гола.", tag="Маршрут полета еще не открыт. В первый раз доберитесь туда пешком."}, [46]={npc="Кразек", tgt="Кразек"}, [47]={npc="Кразек", tgt="Кразек"}, [48]={npc="Барон Ревилгаз", tgt="Барон Ревилгаз"}, [49]={npc="Барон Ревилгаз", tgt="Барон Ревилгаз", tag="Необязательно"}, [50]={npc="Никсраз Наливайка", tgt="Никсраз Наливайка"}, [51]={npc="Дриззлик", tgt="Дриззлик"}, [52]={npc="Кебок", tgt="Кебок"}, [53]={npc="Скути", tgt="Скути", tag="Необязательно"}, [54]={nodeA="{a:35}", node="Booty Bay"}, [55]={to="Ratchet", toA="{a:392}", from="Booty Bay", fromA="{a:35}"}, [56]={nodeA="{a:392}", node="Ratchet"}, [57]={}}},
    ["03-27"] = {steps={[1]={npc="Джинния Пушка", tgt="Джинния Пушка", tag="Можно заранее купить на аукционе (или попросить альта прислать) 1 × «Нефрит» (позже для задания «Волшебные предметы» в Пылевых топях).", desc="Сдайте Табете в Пылевых топях."}, [3]={npc="Иллинг Триас", tgt="Иллинг Триас"}, [4]={npc="Иллинг Триас", tgt="Иллинг Триас"}, [5]={npc="Дашель Каменный Кулак", tgt="Дашель Каменный Кулак"}, [6]={npc="Дашель Каменный Кулак", tgt="Дашель Каменный Кулак"}, [7]={hint="Победите Дашеля Каменного Кулака в Штормграде."}, [8]={npc="Дашель Каменный Кулак", tgt="Дашель Каменный Кулак"}, [9]={npc="Дашель Каменный Кулак", tgt="Дашель Каменный Кулак"}, [10]={npc="Иллинг Триас", tgt="Иллинг Триас"}, [11]={npc="Иллинг Триас", tgt="Иллинг Триас"}, [12]={text="В Штормграде идите в Квартал Дворфов и сядьте на подземный поезд до Стальгорна."}, [13]={npc="Главный камнетес Мраморщик", tgt="Главный камнетес Мраморщик"}, [14]={npc="Главный камнетес Мраморщик", tgt="Главный камнетес Мраморщик"}, [15]={npc="Король Магни Бронзобород", tgt="Король Магни Бронзобород"}, [16]={npc="Геррик Костохват", tgt="Геррик Костохват", tag="Необязательно", desc="Сдавайте, только если подобрали на Темных берегах книгу «Подземные Силы»."}, [17]={npc="Ройттен Камнемолот", tgt="Ройттен Камнемолот", desc="Отнесите на Заставу Нижел в Пустошах."}, [18]={npc="Старший исследователь Магеллас", tgt="Старший исследователь Магеллас"}, [19]={npc="Геолог Грозовая Вершина", tgt="Геолог Грозовая Вершина"}, [20]={npc="Геолог Грозовая Вершина", tgt="Геолог Грозовая Вершина"}, [21]={npc="Геолог Грозовая Вершина", tgt="Геолог Грозовая Вершина"}, [22]={npc="Геолог Грозовая Вершина", tgt="Геолог Грозовая Вершина"}, [23]={npc="Лаго Злобноверт", tgt="Лаго Злобноверт"}, [24]={npc="Страхад Фарсан", tgt="Страхад Фарсан", desc="Летите из Стальгорна в Пиратскую Бухту (с пересадкой в Штормграде), затем плывите на корабле в Кабестан."}, [25]={npc="Страхад Фарсан", tgt="Страхад Фарсан"}, [26]={npc="Кром Крепкорук", tgt="Кром Крепкорук", desc="Плывите на корабле из Кабестана в Пиратскую Бухту, затем летите в Стальгорн."}, [27]={npc="Кром Крепкорук", tgt="Кром Крепкорук"}, [28]={hint="Добудьте заплесневелый фолиант и потрепанный манускрипт для Крома Крепкорука из Стальгорна.", desc="Летите из Стальгорна в Южнобережье, а на обратном пути - снова в Стальгорн."}, [29]={npc="Кром Крепкорук", tgt="Кром Крепкорук"}, [30]={npc="Кром Крепкорук", tgt="Кром Крепкорук"}, [31]={hint="Принесите восстановленный Фолиант Заговора и три жезла направления Страхаду Фарсану в Кабестан.", desc="Летите из Стальгорна в Гавань Менетилов для части в Болотине."}, [32]={npc="Страхад Фарсан", tgt="Страхад Фарсан", desc="Сядьте на южной пристани Гавани Менетилов на корабль до Терамора, откройте точку полета и летите в Кабестан. Или летите из Гавани Менетилов в Пиратскую Бухту (с пересадками в Стальгорне и Штормграде) и дальше плывите на корабле."}, [33]={npc="Страхад Фарсан", tgt="Страхад Фарсан", desc="Призовите и победите охотника Скверны у круга рядом со Страхадом Фарсаном."}, [34]={hint="Призовите и одолейте охотника скверны при помощи фолианта Заговора и верните фолиант Страхаду Фарсану из Кабестана.", desc="Призовите и победите охотника Скверны у круга рядом со Страхадом Фарсаном."}, [35]={npc="Страхад Фарсан", tgt="Страхад Фарсан", desc="Призовите и победите охотника Скверны у круга рядом со Страхадом Фарсаном."}, [36]={text="Если камень возвращения готов, вернитесь в Штормград, сядьте на корабль до Аубердина в порту Штормграда и летите в Астранаар (34.41, 47.99). Только если камень возвращения на перезарядке, идите из Кабестана по главной дороге Степей на север, за Перекрестком продолжайте путь на север в Ясеневый лес, затем по главной дороге Ясеневого леса на запад до Астранаара.", desc="Если идете пешком, обходите стороной Перекресток и Заставу Расщепленного Дерева — это базы Орды. Если на карте полетов есть Терамор, можно сразу лететь в Астранаар (с пересадками в Тераморе и Аубердине)."}, [37]={npc="Клацморт Гайкокрут", tgt="Клацморт Гайкокрут"}, [38]={npc="Элдрун Тучегон", tgt="Элдрун Тучегон", desc="Зов воздуха: найдите Вейрика Громоцепа в Нагорье Арати."}, [39]={to="Menethil Harbor", toA="{a:150}"}, [40]={npc="Михаил", tgt="Михаил"}, [41]={npc="Михаил", tgt="Михаил"}, [42]={hint="Перехватите Яна Проныру до его ухода и вернитесь к Михаилу."}, [43]={npc="Михаил", tgt="Михаил"}, [44]={npc="Tapoke Slim Jahn", tgt="Tapoke Slim Jahn"}, [45]={npc="Михаил", tgt="Михаил"}, [46]={npc="Михаил", tgt="Михаил"}, [47]={npc="Винсент Хьял", tgt="Винсент Хьял", desc="В той же таверне; доставьте письмо в Терамор."}, [48]={to="Аубердин", from="Menethil Harbor", fromA="{a:150}", desc="Этот корабль по пути заходит в Южнобережье. Сойдите в Аубердине."}}},
    ["03-28"] = {steps={[1]={to="Astranaar", toA="{a:415}"}, [2]={npc="Часовой Мелирия Ледяная Тень", tgt="Часовой Мелирия Ледяная Тень"}, [3]={npc="Иллиана", tgt="Иллиана"}, [4]={npc="Пельтур Белая Луна", tgt="Пельтур Белая Луна"}, [5]={text="Обойдите с севера и войдите в долину отсюда."}, [6]={hint="Отправляйтесь в Воющую Долину, изучите фолиант Мел'Тандрис, затем возвращайтесь к часовому Мелирии Ледяной Тени святилище Эссины.", desc="За книгой идите через пещеру. Легко сагрить лишних, а если там редкий монстр — еще сложнее."}, [7]={hint="Отнимите лунный камень Упавшего Неба у Чащобного Оракула и принесите его Пельтуру в Астранаар."}, [8]={text="Вернитесь на главную дорогу к северу и у этой развилки сверните в долину."}, [9]={hint="Освободите заточенные души высокорожденных на Ночной поляне и Сатирнааре, затем вернитесь к Делгрену Очистителю на заставу Мейстры."}, [10]={npc="Анилия", tgt="Анилия"}, [11]={npc="Анилия", tgt="Анилия"}, [12]={hint="Убейте Гелтариса и верните Ветвь Кенария Иллиане в святилище Эссины."}, [13]={npc="Кайнет Штиль", tgt="Кайнет Штиль"}, [14]={npc="Масейра Осенняя Луна", tgt="Масейра Осенняя Луна"}, [15]={hint="Масейра Осенняя Луна просит вас осмотреть местность к западу от Лесной Песни, где водятся демоны Сатирнаара. Принесите ей любые сведения о ее муже Куротеле."}, [16]={npc="Масейра Осенняя Луна", tgt="Масейра Осенняя Луна"}, [17]={nodeA="{a:3137}", node="Talrendis Point", desc="От Лесной Песни идите по дороге на восток в Азшару; лагерь находится прямо у входа."}, [18]={to="Astranaar", toA="{a:415}"}, [19]={npc="Пельтур Белая Луна", tgt="Пельтур Белая Луна"}, [20]={npc="Часовой Мелирия Ледяная Тень", tgt="Часовой Мелирия Ледяная Тень"}, [21]={npc="Часовой Мелирия Ледяная Тень", tgt="Часовой Мелирия Ледяная Тень", tag="Необязательно"}, [22]={npc="Иллиана", tgt="Иллиана"}, [23]={npc="Делгрен Очиститель", tgt="Делгрен Очиститель"}}},
    ["03-29"] = {grind={[1]={mob="Просоленный взорень", note="Южный край Мерцающей равнины; обычные мобы, там же, где василиски для задания «Помехи на трассе»."}, [2]={mob="Просоленный хрусталиск", note="Встречаются вперемешку со взорнями; их больше, уровень немного ниже."}}, steps={[1]={to="Rut'theran Village", toA="{a:702}", tag="Необязательно", desc="В Дарнасе мало опыта. Если спешите, пропустите."}, [2]={text="Пройдите через портал в Деревне Рут'теран в Дарнас.", tag="Необязательно"}, [3]={npc="Тин'тель Танец Клинка", tgt="Тин'тель Танец Клинка", tag="Необязательно"}, [4]={npc="Тин'тель Танец Клинка", tgt="Тин'тель Танец Клинка", tag="Необязательно"}, [5]={hint="Поищите в сундуке Велинды ее дневник, затем принесите его вместе с ключом Тинтэль Танцующий Клинок в Дарнасс.", tag="Необязательно"}, [6]={npc="Тин'тель Танец Клинка", tgt="Тин'тель Танец Клинка", tag="Необязательно"}, [7]={npc="Тин'тель Танец Клинка", tgt="Тин'тель Танец Клинка", tag="Необязательно"}, [8]={text="Пройдите через портал в Дарнасе обратно в Деревню Рут'теран.", tag="Необязательно"}, [9]={text="Если вы делали необязательные задания в Дарнасе, летите из Деревни Рут'теран в Кабестан (с пересадками в Аубердине и на Заставе Талрендис); если пропускали, летите из Астранаара (с пересадкой на Заставе Талрендис). Идите по главной дороге на юг, обойдите Лагерь Таурахо и спуститесь в Тысячу Игл на Большом подъемнике. Через Бастион Мор'шан идите, только если ни одна из двух точек не открыта."}, [10]={text="Спуститесь на Большом лифте до самого низа."}, [11]={nodeA="{a:489}", node="Thalanaar"}, [12]={npc="Виззл Медноштиф", tgt="Виззл Медноштиф"}, [13]={npc="Виззл Медноштиф", tgt="Виззл Медноштиф"}, [14]={npc="Пшикс Медноштиф", tgt="Пшикс Медноштиф"}, [15]={npc="Крейвел Углебрад", tgt="Крейвел Углебрад"}, [16]={npc="Крейвел Углебрад", tgt="Крейвел Углебрад"}, [17]={npc="Крейвел Углебрад", tgt="Крейвел Углебрад"}, [18]={npc="Поззик", tgt="Поззик"}, [19]={npc="Начальник трассы Зерин", tgt="Начальник трассы Зерин"}, [20]={hint="Добудьте 10 полых костей падальщика для Поззика с Мерцающей равнины."}, [21]={hint="Убейте 10 просоленных василисков, 10 просоленных хрусталисков и 6 просоленных взорней, после чего вернитесь к директору трассы Зерину на Мерцающую равнину."}, [22]={hint="Принесите 9 крепких черепашьих панцирей Виззлу Медноштифу на Мерцающую равнину."}, [23]={hint="Принестие 30 деталей болида Крейвелу Углебраду на Мерцающую равнину."}, [24]={hint="Принесите 6 порций соленого яда скорпида Пшиксу Медноштифу на Мерцающую равнину."}, [25]={npc="Поззик", tgt="Поззик"}, [26]={npc="Начальник трассы Зерин", tgt="Начальник трассы Зерин"}, [27]={npc="Виззл Медноштиф", tgt="Виззл Медноштиф"}, [28]={npc="Пшикс Медноштиф", tgt="Пшикс Медноштиф"}, [29]={npc="Крейвел Углебрад", tgt="Крейвел Углебрад"}, [30]={desc="Если перед уходом с Мерцающей равнины у вас еще нет 35-го уровня, бейте просоленных взорней и просоленных хрусталисков к югу от гоночной трассы до 35-го."}, [31]={text="С Мерцающих равнин идите по дороге на юг в Танарис и откройте пункт полета в Прибамбасске.", tag="Маршрут полета еще не открыт. В первый раз доберитесь туда пешком."}, [32]={nodeA="{a:976}", node="Gadgetzan"}}},
    ["05-d17"] = {name="Лабиринты Иглошкурых", entrance="Степи 42.30, 89.90 (около портала подземелья на терновой дороге)", pickup="Когда при первом визите в Тысячу Игл полетите в Кабестан, возьмите «Корни Синелиста» у Мебока Миззрикса и заберите ящик, жезл и руководство рядом с ним. У подножия Большого лифта подберите Дневник Хенрига Хмурня, отнесите его хранителю дорог Фалфинделу в Таланаар и возьмите «Хозяйка Лабиринтов».", pickupS={{"Когда при первом визите в Тысячу Игл полетите в Кабестан, возьмите «Корни Синелиста» у Мебока Миззрикса и заберите ящик, жезл и руководство рядом с ним"}, {"У подножия Большого лифта подберите Дневник Хенрига Хмурня, отнесите его хранителю дорог Фалфинделу в Таланаар и возьмите «Хозяйка Лабиринтов»"}}, tips={{k="取捨", text="«Последнее желание» сдается в Дарнасе. Если не хотите ехать специально, сдайте при следующем визите в Дарнас."}, {k="說明", text="Лабиринты Иглошкурых находятся к западу от Великого подъемника, Курганы Иглошкурых к востоку. 42.30, 89.90 - отметка входа в клиенте Forever. От главной дороги идите по западному терновому туннелю к порталу.", s={{"Лабиринты Иглошкурых находятся к западу от Великого подъемника, Курганы Иглошкурых к востоку"}, {"42.30, 89.90 - отметка входа в клиенте Forever"}, {"От главной дороги идите по западному терновому туннелю к порталу"}}}}, steps={[1]={npc="Мебок Миззрикс", tgt="Мебок Миззрикс", desc="Рядом с тем же NPC в Кабестане возьмите ящик, дирижерскую палочку и пояснительные предметы: они нужны в подземелье."}, [2]={npc="Дневник Хенрига Хмурня", npcObj=true, desc="Подберите Дневник Хенрига Хмурня у подножия Большого лифта и щелкните по нему правой кнопкой, чтобы взять задание."}, [3]={npc="Хранитель дорог Фалфиндел", tgt="Хранитель дорог Фалфиндел"}, [4]={npc="Хранитель дорог Фалфиндел", tgt="Хранитель дорог Фалфиндел"}, [5]={text="Необязательно: удобнее всего на {s:03-29}, когда после открытия точки полета в Таланааре вы возвращаетесь на восток к Мерцающим равнинам: поднимитесь на Большом лифте в Степи, по западному терновому туннелю дойдите до портала подземелья, а после подземелья спуститесь на лифте обратно и продолжайте с {s:03-29}. «Корни Синелиста» сдайте позже в Кабестане, а «Хозяйка Лабиринтов» — в следующий раз в Таланааре. Если идете туда, уже добравшись до Прибамбасска, сначала летите в Таланаар, идите на восток к Большому лифту, а после подземелья продолжайте с {s:03-38}.", tag="Необязательно"}, [6]={text="Вход: Лабиринты Иглошкурых"}, [7]={hint="Возьмите ящик с дырками.", desc="Место: Копайте клубни вдоль терновой дороги; их можно копать и на обратном пути с Уилликсом.", spot="Копайте клубни вдоль терновой дороги; их можно копать и на обратном пути с Уилликсом."}, [8]={npc="Гералат Бурый Ручей", tgt="Гералат Бурый Ручей", spot="За последним боссом, рядом с Уилликсом"}, [9]={hint="Найдите подвеску Трешалы и верните ее Трешале Бурый Ручей в Дарнасс.", desc="После получения задания подвеску могут уронить как иглошкурые, так и боссы подземелья."}, [10]={hint="Принесите медальон Чарлги Остробок Фалфиндеру Хранителю Путей в Таланааре.", desc="Место: Выйдите из пещеры летучих мышей, поднимитесь на платформу и убейте Чарлгу в последней хижине.", spot="Выйдите из пещеры летучих мышей, поднимитесь на платформу и убейте Чарлгу в последней хижине."}, [11]={npc="Импортер Вилликс", tgt="Импортер Вилликс", desc="Сопровождение начинается у палатки возле последнего босса. Сначала расчистите дорогу назад ко входу, затем берите квест."}, [12]={hint="Сопроводите Вилликса из Лабиринтов Иглошкурых.", desc="Сначала расчистите дорогу назад ко входу, затем берите сопровождение Уилликса. Защитите его на пути обратно ко входу. Место: начните у палатки возле последнего босса и идите с Уилликсом обратно ко входу.", spot="Найдите Уилликса в палатке у последнего босса и проводите его обратно ко входу."}, [13]={npc="Импортер Вилликс", tgt="Импортер Вилликс", desc="Сопровождение начинается у NPC внутри подземелья.", spot="У входа в подземелье, где кончается сопровождение"}, [14]={npc="Мебок Миззрикс", tgt="Мебок Миззрикс"}, [15]={npc="Хранитель дорог Фалфиндел", tgt="Хранитель дорог Фалфиндел"}, [16]={npc="Трешала Бурый Ручей", tgt="Трешала Бурый Ручей"}}},
    ["03-38"] = {tips={{k="取捨", text="Для 1440 нужно провести Далинду через засаду у ворот крепости, а для Книга Древних и Реактивы для Поисковой корпорации — элитные противники или группы демонов; в одиночку их не берите."}}, grind={[1]={mob="Кентавр из племени Колкар", note="Восточная долина; добирайте опыт, пока выполняете награду за головы."}, [2]={mob="Разоритель из клана Пылающего Клинка", note="У Крепости Громового Топора; обычные противники."}}, steps={[1]={text="Первый раз в Прибамбасске и до Пика Каменного Когтя ещё не долететь: если камень возвращения готов, вернитесь в Штормград, сядьте на корабль до Аубердина в порту Штормграда и летите на Пик Каменного Когтя; только если камень возвращения на перезарядке, идите из Прибамбасска на север к Мерцающей равнине, поднимитесь на Великом подъёмнике в Степи, обойдите лагерь Таурахо до Кабестана и летите оттуда."}, [2]={to="Stonetalon Peak", toA="{a:467}", desc="Если Высота Найджела открыта, летите прямо туда (с пересадкой в Тераморе) и пропустите следующий шаг. Если Пик Каменного Когтя не открыт, летите в Астранаар и войдите в Когтистые горы через пещеру к югу от Ясеневого леса."}, [3]={text="От Пика Каменного Когтя идите по дороге на юг вниз с горы, обойдите лагерь Орды у Приюта у Солнечного Камня и войдите в Пустоши с юго-запада Когтистых гор. Высота Найджела находится на севере Пустошей.", tag="Маршрут полета еще не открыт. В первый раз доберитесь туда пешком."}, [4]={to="Nijel's Point", toA="{a:608}"}, [5]={nodeA="{a:608}", node="Nijel's Point"}, [6]={npc="Крелдиг Унгор", tgt="Крелдиг Унгор"}, [7]={npc="Крелдиг Унгор", tgt="Крелдиг Унгор"}, [8]={npc="Крелдиг Унгор", tgt="Крелдиг Унгор"}, [9]={npc="Валлариель Истребитель Демонов", tgt="Валлариель Истребитель Демонов"}, [10]={hint="Принесите 10 когтей и 10 рогов сатиров Ярой Ненависти в Пустоши Крелдигу Унгору."}, [11]={npc="Сундук Малема", npcObj=true, desc="Идите по северной дороге на запад; сундук стоит рядом с опрокинутой повозкой у дороги."}, [12]={npc="Сундук Малема", npcObj=true}, [13]={npc="Валлариель Истребитель Демонов", tgt="Валлариель Истребитель Демонов"}, [14]={npc="Валлариель Истребитель Демонов", tgt="Валлариель Истребитель Демонов"}, [15]={npc="Валлариель Истребитель Демонов", tgt="Валлариель Истребитель Демонов"}, [16]={npc="Крелдиг Унгор", tgt="Крелдиг Унгор"}, [17]={npc="Крелдиг Унгор", tgt="Крелдиг Унгор"}, [18]={text="Идите по северной дороге на запад до Этель-Ретора, спуститесь к кораблекрушению на западном берегу, затем возвращайтесь на восток к Крепости Громового Топора."}, [19]={npc="Азор Альдаморт", tgt="Азор Альдаморт"}, [20]={npc="Сундук Карнитола", npcObj=true}, [21]={npc="Сундук Карнитола", npcObj=true}, [22]={npc="Далинда Малем", tgt="Далинда Малем"}, [23]={npc="Далинда Малем", tgt="Далинда Малем"}, [24]={hint="Разыщите в безлюдье Тираниса Малема."}, [25]={hint="Отыщите Скипетр Света и принесите его Азору Альдаморту в башню Этель-Ретор."}, [26]={hint="Убейте орков из племени Пылающего Клинка в крепости Громового Топора в Пустошах, а затем вернитесь к Валлариелю Истребителю Демонов на Высоту Найджела."}, [27]={npc="Далинда Малем", tgt="Далинда Малем"}, [28]={npc="Крелдиг Унгор", tgt="Крелдиг Унгор"}, [29]={npc="Крелдиг Унгор", tgt="Крелдиг Унгор"}, [30]={npc="Валлариель Истребитель Демонов", tgt="Валлариель Истребитель Демонов"}, [31]={npc="Капрал Мелкис", tgt="Капрал Мелкис"}, [32]={npc="Капитан Пентигаст", tgt="Капитан Пентигаст"}, [33]={npc="Брат Антон", tgt="Брат Антон"}, [34]={text="От Заставы Нижел идите по восточной дороге на юг в долину кентавров Колкар."}, [35]={hint="Принесите в город Высота Найджела 15 ушей кентавров и отдайте их капралу Мелкису."}, [36]={hint="Добудьте 5 |4резной тотем:резных тотема:резных тотемов; кентавров, убивая кентавров из любого клана в Пустошах, а затем принесите добычу капитану Пентигасту на Высоту Найджела."}, [37]={npc="Биббли Скобкофуз", tgt="Биббли Скобкофуз"}, [38]={hint="Принесите 7 фиалов скорпионьего яда и 3 шкуры старого кодо в Пустоши Крелдигу Унгору."}, [39]={npc="Смид Заржавень", tgt="Смид Заржавень"}, [40]={hint="Приведите пять прирученных кодо Смиду Заржавеню в Лагерь Заржавня. Не забудьте вернуть ему энергетический инкапсулятор.", desc="Ведите каждого кодо к Смиду, подождите, пока он попросит проверить, затем щелкните правой кнопкой по прирученному кодо; за следующим идите, только когда вырастет счетчик. По пути собирайте кости кодо для Собиратель костей и остерегайтесь призраков кодо, которых могут привлечь кости."}, [41]={hint="Принесите 10 костей с Кладбища кодо в хижину Кормека и отдайте Биббли Скобкофузу."}, [42]={npc="Смид Заржавень", tgt="Смид Заржавень"}, [43]={npc="Хормиц Жужжалит", tgt="Хормиц Жужжалит"}, [44]={text="От Кладбища кодо идите по дороге на юг в Долину Костей. Лагерь демонов к востоку от дороги — Ковен Маннорока, держитесь от него подальше."}, [45]={hint="Убейте 30 опустошителей-отрекшихся и вернитесь к брату Антону на Высоте Найджела."}, [46]={hint="Принесите 8 единиц эктоплазмы и ящик призрачных магнитов Хормицу Жужжалиту в Пустоши.", desc="Поставьте ящик с призрачными магнитами между двумя гигантскими скелетами в Долине Костей, отойдите и убивайте притянутых духов кентавров по одному, пока не наберете 8 призрачной плазмы. Расчистите или обойдите монстров 38-40-го уровня рядом; если не выходит, пропустите Сбор эктоплазмы."}, [47]={npc="Хормиц Жужжалит", tgt="Хормиц Жужжалит"}, [48]={npc="Биббли Скобкофуз", tgt="Биббли Скобкофуз"}, [49]={text="От хижины Библи идите на северо-запад к Этель-Ретору сдать Скипетр Света, затем на север к побережью за нагами Скользящего Плавника и по северной дороге вернитесь на Заставу Нижел, чтобы сдать все сразу."}, [50]={npc="Азор Альдаморт", tgt="Азор Альдаморт"}, [51]={hint="Найдите сумку для книг, принадлежащую Карнитолу, и отнесите ее в Пустоши Крелдигу Унгору."}, [52]={npc="Капрал Мелкис", tgt="Капрал Мелкис"}, [53]={npc="Капитан Пентигаст", tgt="Капитан Пентигаст"}, [54]={npc="Крелдиг Унгор", tgt="Крелдиг Унгор"}, [55]={npc="Брат Антон", tgt="Брат Антон"}, [56]={npc="Брат Антон", tgt="Брат Антон", tag="Необязательно, Делайте с группой"}, [57]={npc="Крелдиг Унгор", tgt="Крелдиг Унгор"}, [58]={npc="Крелдиг Унгор", tgt="Крелдиг Унгор", desc="Оставьте сумку и сдайте ее в Стальгорне после Бесплодных земель."}, [59]={}}},
    ["03-30"] = {name="Нагорье Арати", grind={[1]={mob="Кобольд из племени Сухоусов", note="Район входа в Теснину Сухоусов; обычные мобы, прямо рядом с местом, где вы завершаете «Пойманную принцессу»."}, [2]={mob="Землекоп из племени Сухоусов", note="У кристалла в глубине теснины; лучше подходят по уровню."}, [3]={mob="Громила из клана Тяжелого Кулака", note="Огры вокруг Крепости Тяжелого Кулака; по пути, когда идете за жезлом."}, [4]={mob="Темная охотница из племени Сухокожих", note="Деревня Сухокожих на юго-востоке; те же тролли, что и для задания «На вес золота»."}}, steps={[1]={to="Refuge Pointe", toA="{a:320}", desc="Если Опорный пункт не открыт, летите в Гавань Менетилов, идите по дороге на северо-восток через Болотину, пересеките Мост Тандола в Нагорье Арати и дойдите по дороге до Опорного пункта."}, [2]={npc="Капитан Ниалс", tgt="Капитан Ниалс"}, [3]={npc="Щит с надписью РОЗЫСК", npcObj=true, tag="Делайте с группой, Необязательно"}, [4]={npc="Щит с надписью РОЗЫСК", npcObj=true, tag="Делайте с группой, Необязательно", desc="Отто и Фалконкрест — элитные противники 38 и 40 уровня."}, [5]={npc="Скуэрто", tgt="Скуэрто"}, [6]={npc="Ученик Кретьен", tgt="Ученик Кретьен"}, [7]={npc="Кристаллы Мизраэли", npcObj=true}, [8]={hint="Соберите 12 крупиц Мощи Мизраэли и принесите их к радужным осколкам в Теснине Сухоусов."}, [9]={npc="Радужные осколки", npcObj=true}, [10]={desc="Прокачайтесь примерно до трех четвертей 36-го уровня; бейте кобольдов и землекопов из племени Сухоусов прямо здесь, в Теснине Сухоусов."}, [11]={npc="Радужные осколки", npcObj=true, desc="Восточный связывающий камень по пути на запад, возьмите его первым; внешний связывающий камень берите по дороге к Опорному пункту."}, [12]={npc="Кви", tgt="Кви"}, [13]={npc="Кви", tgt="Кви"}, [14]={hint="Найдите Отрекшегося-курьера и принесите обнаруженную у него запечатанную папку Кви близ фермы Го'Шека.", desc="Отрекшийся-курьер патрулирует дорогу в районе Фермы Го'Шека; увидев его, убейте и заберите Запечатанную папку."}, [15]={hint="Найдите 10 клыков троллей клана Сухокожих, 4 лекарских сумки клана Сухокожих и нож Темного охотника и принесите их ученику Кретьену в Опорном пункте.", desc="Остерегайтесь патрулирующего Отрекшегося-курьера."}, [16]={npc="Ученик Кретьен", tgt="Ученик Кретьен"}, [17]={npc="Капитан Ниалс", tgt="Капитан Ниалс", desc="Сдайте Демару Бранту в крепости Фархолд в Лесоречье; на следующем этапе вы туда придете."}, [18]={npc="Скуэрто", tgt="Скуэрто"}, [19]={desc="Если перед боем с Кор'грешем Холодной Яростью (39-й уровень) у вас еще нет 37-го уровня, бейте громил из клана Тяжелого Кулака возле Крепости Тяжелого Кулака или идите на восток в Деревню Сухокожих и бейте троллей из племени Сухокожих до 37-го."}, [20]={hint="Найдите заклинательный жезл Трелана и верните его Скуэрто в Опорный пункт."}, [21]={npc="Кви", tgt="Кви"}, [22]={npc="Кви", tgt="Кви"}, [23]={npc="Кинелори", tgt="Кинелори"}, [24]={npc="Кинелори", tgt="Кинелори"}, [25]={hint="Защищайте Кинелори, пока она не вернется к Кви.", desc="Задание на сопровождение: идите за Кинелори, по пути будут засады."}, [26]={npc="Кви", tgt="Кви"}, [27]={npc="Кви", tgt="Кви"}, [28]={npc="Скуэрто", tgt="Скуэрто"}, [29]={npc="Скуэрто", tgt="Скуэрто", tag="Делайте с группой, Необязательно"}, [30]={hint="Добудьте огненный ключ, резной ключ и громовой ключ с западного связывающего камня, восточного связывающего камня и внешнего связывающего камня."}, [31]={hint="Убейте 10 проходимцев из Синдиката и 6 наемников Синдиката."}, [32]={npc="Капитан Ниалс", tgt="Капитан Ниалс"}, [33]={npc="Капитан Ниалс", tgt="Капитан Ниалс", tag="Делайте с группой, Необязательно"}, [34]={npc="Внутренний связывающий камень", npcObj=true}, [35]={hint="Принесите капитану Ниалс в Опорный пункт голову Марез.", tag="Делайте с группой, Необязательно"}, [36]={hint="Принесите головы Отто и лорда Фалконкреста капитану Ниалс в Опорный пункт.", tag="Делайте с группой, Необязательно"}, [37]={hint="Принесите знаки Стромгарда Капитану Ниалс в Опорный пункт.", tag="Делайте с группой, Необязательно"}, [38]={hint="Найдите лазурный агат и принесите его ученику Кретьену в Опорный пункт.", tag="Делайте с группой, Необязательно"}, [39]={npc="Капитан Ниалс", tgt="Капитан Ниалс", tag="Делайте с группой, Необязательно"}, [40]={npc="Капитан Ниалс", tgt="Капитан Ниалс", tag="Делайте с группой, Необязательно"}, [41]={npc="Капитан Ниалс", tgt="Капитан Ниалс", tag="Делайте с группой, Необязательно"}, [42]={npc="Ученик Кретьен", tgt="Ученик Кретьен", tag="Делайте с группой, Необязательно"}, [43]={npc="Ученик Кретьен", tgt="Ученик Кретьен"}, [44]={npc="Скуэрто", tgt="Скуэрто"}, [45]={npc="Скуэрто", tgt="Скуэрто"}, [46]={hint="Найдите талисман, сферу и угольный агат Трелана и принесите их Скуэрто в Опорный пункт.", tag="Позже, по пути"}, [47]={npc="Скуэрто", tgt="Скуэрто"}, [48]={npc="Скуэрто", tgt="Скуэрто"}, [49]={hint="Украдите форму Синдиката в Северном поместье, чтобы проникнуть в крепость Стромгард.", desc="Украдите форму Синдиката в Северном поместье в Нагорье Арати."}, [50]={npc="Ларь Синдиката", npcObj=true}, [51]={npc="Ларь Синдиката", npcObj=true}, [52]={hint="Переодевшись в члена Синдиката, найдите кого-нибудь в крепости Стромгард, кто знает о тайной встрече."}, [53]={npc="Анастасия Миллер", tgt="Анастасия Миллер"}, [54]={npc="Анастасия Миллер", tgt="Анастасия Миллер"}, [55]={hint="Найдите в крепости Стромгард что-нибудь, что заставит Анастасию поделиться подробностями о тайной встрече."}, [56]={npc="Анастасия Миллер", tgt="Анастасия Миллер"}, [57]={npc="Анастасия Миллер", tgt="Анастасия Миллер"}, [58]={hint="Помешайте тайной встрече и заберите предмет, который на ней должны передать Синдикату. Затем вернитесь к Мирокосу Тихоступу."}, [59]={npc="Мирокос Тихоступ", tgt="Мирокос Тихоступ"}, [60]={npc="Вейрик Громоцеп", tgt="Вейрик Громоцеп"}, [61]={npc="Вейрик Громоцеп", tgt="Вейрик Громоцеп", tag="Делайте с группой, Необязательно", desc="Нужно пройти Лабиринты Иглошкурых (подземелье на юге Степей); делайте, когда соберете группу; продолжение «Буря, земля и огонь» тоже пропустите."}, [62]={hint="Победите Чарглу Остробок в лабиринтах Иглошкурых и выясните, что замышляют свинобразы.", tag="Делайте с группой, Необязательно"}, [63]={npc="Вейрик Громоцеп", tgt="Вейрик Громоцеп", tag="Делайте с группой, Необязательно", desc="Вейрика Громоцепа можно найти и в Стальгорне (47.10, 13.79)."}, [64]={npc="Вейрик Громоцеп", tgt="Вейрик Громоцеп", tag="Необязательно", desc="Четыре вида Искаженных тотемов падают с мобов в Пылевых топях, Бесплодных землях, Болоте Печали и Пустошах; собирайте их по пути на следующих этапах; в конце сдайте задание Вейрику Громоцепу в Стальгорне."}, [65]={to="Southshore", toA="{a:271}"}, [66]={npc="Фин Оделик", tgt="Фин Оделик"}, [67]={npc="Мировой судья Генри Малеб", tgt="Мировой судья Генри Малеб"}, [68]={npc="Ролей Благочестивый", tgt="Ролей Благочестивый", tag="Необязательно"}, [69]={desc="Если камень возвращения на перезарядке, слетайте из Южнобережья в Стальгорн и вернитесь в Штормград на подземном поезде."}}},
    ["05-d8"] = {name="Монастырь Алого Ордена", entrance="Тирисфальские леса 82.60, 33.80", pickup="Возьмите задания для подземелья заранее, по пути: Болотина (2-й заход). Возвращаться перед походом не придется.", pickupS={{"Возьмите задания для подземелья заранее, по пути: Болотина (2-й заход)"}, {"Возвращаться перед походом не придется"}}, steps={[1]={npc="Библиотекарь Мая Белокожка", tgt="Библиотекарь Мая Белокожка"}, [2]={to="Southshore", toA="{a:271}", desc="Вы сделаете пересадку в Стальгорне."}, [3]={npc="Ролей Благочестивый", tgt="Ролей Благочестивый", tag="Необязательно"}, [4]={npc="Ролей Благочестивый", tgt="Ролей Благочестивый", tag="Необязательно, Делайте с группой"}, [5]={npc="Волхв Ольвек", tgt="Волхв Ольвек", tag="Необязательно"}, [6]={text="Из Хилсбрада идите на запад в Серебряный бор, а затем по главной дороге на север в Тирисфаль. Обойдите стражу Гробницы, Подгорода и Брилла и двигайтесь к Монастырю Алого ордена на северо-востоке."}, [7]={text="Вход: Монастырь Алого Ордена"}, [8]={hint="Добудьте \"Мифологию Титанов\" из монастыря и принесите ее библиотекарю Мае Белокожке в Стальгорн.", desc="Место: Книжная полка в дальних залах библиотеки.", spot="Книжная полка в дальних залах библиотеки."}, [9]={hint="Принесите книгу \"Утерянная магия мастеров рун\" из монастыря Алого ордена.", tag="Необязательно"}, [10]={hint="Убейте Верховного инквизитора Вайтмейн, командира Могрейна из Алого ордена, воителя Герода из Алого ордена и псаря Локси, после этого вернитесь с докладом к Ролею Благочестивому в Южнобережье.", tag="Необязательно", desc="Победите Локси в библиотеке, Герода в оружейной, Могрейна и Вайтмейн в соборе. Крылья можно пройти за несколько походов."}, [11]={npc="Волхв Ольвек", tgt="Волхв Ольвек", tag="Необязательно"}, [12]={npc="Ролей Благочестивый", tgt="Ролей Благочестивый", tag="Необязательно, Требуются материалы"}, [13]={npc="Библиотекарь Мая Белокожка", tgt="Библиотекарь Мая Белокожка", tag="Необязательно", desc="Возвращайтесь через Тирисфаль и Серебряный бор в Южнобережье. Если маршрут открыт, летите в Стальгорн. Иначе сядьте на корабль до Гавани Менетилов, пройдите по горной дороге на юге Болотины в Лок Модан и через туннель в Дун Морог, а оттуда идите в Стальгорн. Если камень возвращения привязан к Штормграду и готов, можно вернуться туда и сесть на Подземный поезд."}}},
    ["03-31"] = {tips={{k="提醒", text="Рог'мар в центре карты — город Орды, не подходите.", s={{"Рог'мар в центре карты — город Орды, не подходите"}}}}, steps={[1]={to="Lakeshire", toA="{a:69}", tag="Перед поездкой в Лесоречье можно купить на аукционе (или попросить альта прислать) 8 × «Твердое точило» (для задания «Самый острый клинок»).", desc="В крепости Фархолд еще нет точки полета, поэтому при первом визите идите от Приозерья по большой дороге на восток к западному входу в Лесоречье."}, [2]={npc="Дорин Поющий Клинок", tgt="Дорин Поющий Клинок", tag="Необязательно, Делайте с группой"}, [3]={text="За входом к востоку от Красногорья начинаются Щетинистые холмы; гноллы 36-38 уровней у входа бьют больно.", tag="Маршрут полета еще не открыт. В первый раз доберитесь туда пешком."}, [4]={npc="Разведчик Болайн", tgt="Разведчик Болайн"}, [5]={npc="Седрик Далтон", tgt="Седрик Далтон"}, [6]={npc="Седрик Далтон", tgt="Седрик Далтон"}, [7]={npc="Седрик Далтон", tgt="Седрик Далтон"}, [8]={npc="Седрик Далтон", tgt="Седрик Далтон", tag="Необязательно, Делайте с группой", desc="Снаргл - элита 40-го уровня; если не справляетесь, пропустите его."}, [9]={npc="Кудряш", tgt="Кудряш"}, [10]={npc="Халлиган Тернер", tgt="Халлиган Тернер"}, [11]={npc="Халлиган Тернер", tgt="Халлиган Тернер"}, [12]={npc="Швыряш", tgt="Швыряш"}, [13]={npc="Швыряш", tgt="Швыряш"}, [14]={hint="Отправляйтесь со Швыряшем на помощь Кудряшу.", desc="Идите за Швыряшем, чтобы спасти Кудряша."}, [15]={hint="Убейте 8 |4мистика:мистиков:мистиков;, 8 |4зверолова:звероловов:звероловов; и 6 |4громилу:громил:громил; из стаи Красногорья по просьбе Седрика Далтона в Южном дозоре."}, [16]={hint="Раздобудьте 8 |4пилу:пилы:пил; в лагерях гноллов на Щетинистых холмах для Халлигана Тернера с лесопилки.", desc="Зазубренные лезвия разбросаны по земле в лагере гноллов."}, [17]={hint="Найдите и убейте Снаргла в Щетинистых холмах, после чего принесите его рыло Седрику Далтону в Южный дозор.", tag="Необязательно, Делайте с группой", d