    ["03-36"] = {steps={[1]={to="Darkshire", toA="{a:42}"}, [2]={npc="Начальник стражи Соригел", tgt="Начальник стражи Соригел"}, [3]={text="Из Темнолесья идите на восток через Перевал Мертвого Ветра в Болото Печали."}, [4]={npc="Дозорный Биггс", tgt="Дозорный Биггс"}, [5]={hint="Принесите 10 щепоток сонной пыли Кразеку в Пиратскую бухту. Сонную пыль можно собрать с дракончиков на Болоте Печали."}, [6]={hint="Убейте 8 |4молодого острозубого кроколиска:молодых острозубых кроколисков:молодых острозубых кроколисков;, 10 |4ткача:ткачей:ткачей; скорби и 10 |4болотного ягуара:болотных ягуаров:болотных ягуаров; и потом вернитесь к дозорному Биггсу на Болоте Печали."}, [7]={npc="Дозорный Биггс", tgt="Дозорный Биггс"}, [8]={npc="Дозорный Биггс", tgt="Дозорный Биггс"}, [9]={npc="Палка Нобору", npcObj=true, tag="Необязательно", desc="Щелкните правой кнопкой по предмету «Палка Нобору» в сумке, чтобы взять задание. Убейте Нобору Дубину, получите серую палку и щелкните по ней правой кнопкой, чтобы начать задание."}, [10]={npc="Магтур", tgt="Магтур", tag="Необязательно"}, [11]={npc="Магтур", tgt="Магтур"}, [12]={hint="Принесите 6 кристаллов дренейского аметиста Магтуру в Убежище в Болоте Печали."}, [13]={hint="Найдите похищенный из каравана сундук в Болотном пристанище, добудьте реактивы магов и принесите их дозорному Биггсу."}, [14]={npc="Гален Добростраж", tgt="Гален Добростраж"}, [15]={hint="Выведите Галена из опасного места, затем найдите его лагерь на Болоте Печали и откройте его сейф.", tag="Эскорт", desc="Идите за Галеном, пока он выбирается из Болотного пристанища (лагеря Заблудших); по пути на него нападают мобы — защищайте его; после сопровождения идите в его лагерь и откройте сейф."}, [16]={npc="Сейф Галена", npcObj=true}, [17]={npc="Магтур", tgt="Магтур"}, [18]={npc="Дозорный Биггс", tgt="Дозорный Биггс"}, [19]={npc="Дозорный Биггс", tgt="Дозорный Биггс"}, [20]={hint="Принести 8 кусков сухого плавника дозорному Биггсу на Болоте Печали."}, [21]={hint="Найдите Храм Атал'Хаккара и сообщите о его местонахождении Брохану Бочкопузу из Штормграда.", desc="Выполняется, когда вы подходите к Затонувшему храму."}, [22]={npc="Дозорный Биггс", tgt="Дозорный Биггс"}, [23]={npc="Дозорный Биггс", tgt="Дозорный Биггс"}, [24]={npc="Дозорный Биггс", tgt="Дозорный Биггс", desc="Задание на доставку; сдайте его Дайме Брант в Дальнем Дозоре на следующей остановке."}, [25]={text="С юга Болота Печали войдите в Выжженные земли и идите по дороге на юг до Крепости Стражей Пустоты.", tag="Маршрут полета еще не открыт. В первый раз доберитесь туда пешком."}, [26]={npc="Интендант Лунгерц", tgt="Интендант Лунгерц"}, [27]={nodeA="{a:1438}", node="Nethergarde Keep"}, [28]={hint="Соберите 5 |4изуродованный тотем:изуродованных тотема:изуродованных тотемов; огня, 5 |4изуродованный тотем:изуродованных тотема:изуродованных тотемов; земли, 5 |4изуродованный тотем:изуродованных тотема:изуродованных тотемов; воздуха и 5 |4изуродованный тотем:изуродованных тотема:изуродованных тотемов; воды для Вейрика Громоцепа на нагорье Арати.", tag="Необязательно", desc="Тотем ветра падает с кентавров из племени Мародин в Пустошах; Пустоши уже пройдены, так что придется съездить отдельно. Тотем воды — с мурлоков из племени Болотного Плавника на севере Пылевых топей, Тотем огня — с троггов из племени Каменного Свода в Бесплодных землях, Тотем земли — с Заблудших в Болоте Печали; собирайте их попутно, когда будете проходить мимо."}}},
    ["03-37"] = {tips={{k="提醒", text="Рог'мар в центре карты — город Орды, не подходите.", s={{"Рог'мар в центре карты — город Орды, не подходите"}}}}, steps={[1]={to="Farholde Keep", toA="{a:16724}", tag="Перед поездкой в Лесоречье можно купить на аукционе (или попросить альта прислать) 20 × «Магическая ткань» (для задания «Перевязка»).", desc="Пересадка будет в Темнолесье и Приозерье."}, [2]={npc="Демар Брант", tgt="Демар Брант"}, [3]={npc="Демар Брант", tgt="Демар Брант"}, [4]={npc="Демар Брант", tgt="Демар Брант"}, [5]={npc="Демар Брант", tgt="Демар Брант", desc="Сначала нужно сдать Журнал фельдмаршала, которое запускается выпавшим предметом, иначе задание не взять."}, [6]={npc="Эш Амберхолл", tgt="Эш Амберхолл"}, [7]={npc="Бертранд Сталелоб", tgt="Бертранд Сталелоб"}, [8]={npc="Брат Лоули", tgt="Брат Лоули", tag="Необязательно, Требуются материалы", desc="Нужно 20 × «Магическая ткань». Можно купить на аукционе. Пропустите, если их нет с собой."}, [9]={npc="Брат Лоули", tgt="Брат Лоули", tag="Необязательно"}, [10]={npc="Брат Лоули", tgt="Брат Лоули"}, [11]={hint="Перевяжите 3 израненных солдат по просьбе брата Лоули.", desc="Израненные солдаты лежат рядом с Братом Лоули."}, [12]={npc="Брат Лоули", tgt="Брат Лоули"}, [13]={npc="Брат Лоули", tgt="Брат Лоули"}, [14]={npc="Сестра Роуланд", tgt="Сестра Роуланд"}, [15]={npc="Тесса Донбрайт", tgt="Тесса Донбрайт"}, [16]={hint="Соберите 6 |4свежее яблоко:свежих яблока:свежих яблок; для Тессы Донбрайт в крепости Фархолд.", desc="Свежие яблоки лежат под плодовыми деревьями возле Фархолда."}, [17]={npc="Тесса Донбрайт", tgt="Тесса Донбрайт"}, [18]={npc="Тесса Донбрайт", tgt="Тесса Донбрайт"}, [19]={hint="Добудьте 3 |4шкуру койота:шкуры койота:шкур койота; для Тессы Донбрайт в крепости Фархолд."}, [20]={npc="Тесса Донбрайт", tgt="Тесса Донбрайт"}, [21]={npc="Тесса Донбрайт", tgt="Тесса Донбрайт"}, [22]={npc="Дозорный Корнелий", tgt="Дозорный Корнелий"}, [23]={text="От Дозора Террала идите на запад, мимо Светогляди с юга, к сержанту Мракану перед Сумеречным покровом. Проходя мимо лесопилки Тернера, подберите древесину."}, [24]={hint="Заберите 10 |4вязанку дров:вязанки дров:вязанок дров; с лесопилки Тернера для Бертранда Сталелба, который находится в крепости Фархолд.", desc="Штабель досок на лесопилке Тернера."}, [25]={npc="Сержант Мракан", tgt="Сержант Мракан"}, [26]={npc="Сержант Мракан", tgt="Сержант Мракан"}, [27]={npc="Сержант Мракан", tgt="Сержант Мракан"}, [28]={npc="Сержант Мракан", tgt="Сержант Мракан"}, [29]={hint="Призовите сумеречного раба с помощью проводника в Сумеречном покрове и плените его при содействии камня души Амберхолл.", desc="У проводника в Сумеречном покрове призовите сумеречного раба и поймайте его камнем души."}, [30]={npc="Маршал Райан", tgt="Маршал Райан"}, [31]={npc="Маршал Райан", tgt="Маршал Райан"}, [32]={hint="Освободите 5 |4фархолдского разведчика:фархолдских разведчиков:фархолдских разведчиков; в Сумеречном покрове по просьбе сержанта Мракана.", desc="Разведчики заперты в разных местах Сумеречного покрова."}, [33]={hint="Убейте 8 |4сумеречного фанатика:сумеречных фанатиков:сумеречных фанатиков;, 8 |4сумеречного осквернителя:сумеречных осквернителей:сумеречных осквернителей; и 8 |4сумеречного воителя:сумеречных воителей:сумеречных воителей; в Сумеречном покрове по указанию сержанта Мракана."}, [34]={hint="Убейте 5 |4огра-шахтера:огров-шахтеров:огров-шахтеров; и 5 сумеречных поработителей в Сумеречном покрове по просьбе сержанта Мракана."}, [35]={npc="Сержант Мракан", tgt="Сержант Мракан"}, [36]={npc="Сержант Мракан", tgt="Сержант Мракан"}, [37]={npc="Сержант Мракан", tgt="Сержант Мракан"}, [38]={npc="Сержант Мракан", tgt="Сержант Мракан", tag="Необязательно, Делайте с группой", desc="Властитель Килгар - элита 46-го уровня."}, [39]={hint="Сразите властителя Килгара в Сумеречном покрове и принесите его голову сержанту Мракану.", tag="Необязательно, Делайте с группой", desc="Властитель Килгар - элита 46-го уровня."}, [40]={npc="Сержант Мракан", tgt="Сержант Мракан", tag="Необязательно, Делайте с группой", desc="Властитель Килгар - элита 46-го уровня."}, [41]={npc="Сержант Мракан", tgt="Сержант Мракан", desc="Сначала нужно победить Властителя Килгара."}, [42]={text="Идите на восток через Светогладь и к югу от Дозора Террала в Пороховой порт, обходя Рог'мар, город Орды. В Пороховом порту нет точки полета Альянса."}, [43]={npc="Слибо Пшибрызг", tgt="Слибо Пшибрызг", desc="Слибо находится немного севернее дороги в Пороховой порт."}, [44]={hint="Наберите восемь фиалов болотного газа для Слибо Пшибрызга.", desc="Болотный газ собирайте у отдушин возле Сли'бо."}, [45]={npc="Слибо Пшибрызг", tgt="Слибо Пшибрызг"}, [46]={npc="Слибо Пшибрызг", tgt="Слибо Пшибрызг"}, [47]={hint="Помогите Слибо испытать его новое творение."}, [48]={npc="Слибо Пшибрызг", tgt="Слибо Пшибрызг"}, [49]={npc="Раскрашенная шкура", npcObj=true, desc="Перед тем как войти в Пороховой порт, сверните на юг и подберите здесь (около 12 единиц карты от главной дороги), а в порту сразу сдайте Арго Солесвисту."}, [50]={npc="Грей Донбрайт", tgt="Грей Донбрайт"}, [51]={npc="Фриз Искродох", tgt="Фриз Искродох"}, [52]={npc="Фриз Искродох", tgt="Фриз Искродох"}, [53]={npc="Фриз Искродох", tgt="Фриз Искродох"}, [54]={npc="Управляющий пристанью Просвистун", tgt="Управляющий пристанью Просвистун"}, [55]={npc="Управляющий пристанью Просвистун", tgt="Управляющий пристанью Просвистун"}, [56]={npc="Управляющий пристанью Просвистун", tgt="Управляющий пристанью Просвистун"}, [57]={npc="Фимбо Смазляп", tgt="Фимбо Смазляп"}, [58]={npc="В РОЗЫСКЕ!", npcObj=true, desc="Тискач находится на берегу к востоку от Порохового порта."}, [59]={npc="В РОЗЫСКЕ!", npcObj=true, tag="Делайте с группой, Необязательно", desc="Старый Гниложев — элитный мурлок 42-го уровня, он бродит в районе мурлочьих островов к югу от Порохового порта."}, [60]={npc="Тискач", tgt="Арго Солесвист"}, [61]={npc="Тискач", tgt="Арго Солесвист"}, [62]={hint="Принесите клешню Тискача Фимбо Смазляпу."}, [63]={hint="Убейте 10 пиратов и 10 мушкетеров из братства Восточных Морей к северу от Порохового порта."}, [64]={hint="Доставьте 8 |4ящик:ящика:ящиков; контрабандных товаров Фриз Искродох в Пороховой порт.", desc="Убивайте буканьеров и мушкетеров из братства Восточных Морей вместе с «Недружеским соперничеством»."}, [65]={npc="Фимбо Смазляп", tgt="Фимбо Смазляп"}, [66]={npc="Управляющий пристанью Просвистун", tgt="Управляющий пристанью Просвистун"}, [67]={npc="Управляющий пристанью Просвистун", tgt="Управляющий пристанью Просвистун"}, [68]={npc="Управляющий пристанью Просвистун", tgt="Управляющий пристанью Просвистун"}, [69]={npc="Фриз Искродох", tgt="Фриз Искродох"}, [70]={npc="Фриз Искродох", tgt="Фриз Искродох"}, [71]={hint="Украдите 5 |4пороховой бочонок:пороховых бочонка:пороховых бочонков; братства Восточных Морей по просьбе управляющего пристанью Просвистуна.", desc="Пороховые бочонки лежат внутри зданий в руинах Windbreak."}, [72]={hint="Убейте 8 буканьеров и 8 бомбардиров из братства Восточных Морей по просьбе управляющего пристанью Просвистуна."}, [73]={hint="Добудьте 15 |4внутренности зверя:внутренности зверей:внутренностей зверей; и 8 |4гнилогриб:гнилогриба:гнилогрибов; для Арго Солесвиста.", desc="Внутренности собирайте со зверей по дороге; гнилогрибы растут в пещере рядом с Windbreak, внутри пещеры есть огры."}, [74]={npc="Управляющий пристанью Просвистун", tgt="Управляющий пристанью Просвистун"}, [75]={npc="Управляющий пристанью Просвистун", tgt="Управляющий пристанью Просвистун"}, [76]={npc="Тискач", tgt="Арго Солесвист"}, [77]={npc="Тискач", tgt="Арго Солесвист"}, [78]={hint="Убейте 8 мурлоков-оракулов и мурлоков-воинов на побережье Восточного Ветра."}, [79]={hint="Добудьте 12 глаз мурлоков и 6 кусков мяса песчаного краба для Фимбо Смазляпа."}, [80]={hint="Принесите победный трофей Старого Гниложева управляющему пристанью Просвистуну.", tag="Делайте с группой, Необязательно"}, [81]={hint="Выманите морское чудовище с помощью большого шмата наживки. Затем принесите его голову Арго Солесвисту.", desc="Используйте наживку рядом с затонувшим кораблем под водой у мурлочьего острова, чтобы вызвать морское чудовище, победите его и подберите голову. Делайте за тот же заход, что и мурлоков с крабами на южном берегу."}, [82]={npc="Фимбо Смазляп", tgt="Фимбо Смазляп"}, [83]={npc="Тискач", tgt="Арго Солесвист"}, [84]={npc="Управляющий пристанью Просвистун", tgt="Управляющий пристанью Просвистун"}, [85]={npc="Управляющий пристанью Просвистун", tgt="Управляющий пристанью Просвистун", tag="Делайте с группой, Необязательно"}, [86]={npc="Управляющий пристанью Просвистун", tgt="Управляющий пристанью Просвистун"}, [87]={npc="Управляющий пристанью Просвистун", tgt="Управляющий пристанью Просвистун", tag="Необязательно", desc="Квест 45 уровня. Если он выше вас на 3 или больше уровней, можно пока пропустить."}, [88]={hint="Установите дистанционные взрывные заряды на всех трех кораблях братства Восточных Морей.", desc="Заложите по заряду на каждый из трех кораблей буканьеров из братства Восточных Морей."}, [89]={hint="Доставьте \"Нечто особенное от Фриз\" капитану Бенткойну на побережье Восточного Ветра.", desc="Взорвав корабли, несите это вдоль берега на северо-восток, чтобы сдать."}, [90]={npc="Капитан Хейнес", tgt="Капитан Бенткойн"}, [91]={npc="Капитан Хейнес", tgt="Капитан Хейнес"}, [92]={hint="Убейте адмирала Ламору и отыщите его добычу, а затем доставьте ее управляющему пристанью Просвистуну.", tag="Необязательно", desc="Квест 45 уровня. Если он выше вас на 3 или больше уровней, можно пока пропустить."}, [93]={npc="Управляющий пристанью Просвистун", tgt="Управляющий пристанью Просвистун"}, [94]={npc="Управляющий пристанью Просвистун", tgt="Управляющий пристанью Просвистун", tag="Необязательно"}, [95]={npc="Фриз Искродох", tgt="Фриз Искродох"}, [96]={npc="Фриз Искродох", tgt="Фриз Искродох", desc="Сдайте караванщику Раззготу в Пиратской бухте; это по пути, когда в следующий раз отправитесь в Тернистую долину."}, [97]={npc="Фриз Искродох", tgt="Фриз Искродох", desc="Сдайте управляющему пристанью Паропшику в Порту Картеля в Танарисе; это по пути, когда позже отправитесь в Танарис."}, [98]={npc="Фриз Искродох", tgt="Фриз Искродох", desc="Сдаётся в Крепости Оперенной Луны в Фераласе. Это по пути, когда позже отправитесь в Фералас."}, [99]={text="Из Порохового порта идите на юго-запад, обратно в крепость Фархолд."}, [100]={npc="Бертранд Сталелоб", tgt="Бертранд Сталелоб"}, [101]={npc="Эш Амберхолл", tgt="Эш Амберхолл"}, [102]={npc="Эш Амберхолл", tgt="Эш Амберхолл", desc="Сначала нужно победить Властителя Килгара."}, [103]={npc="Демар Брант", tgt="Демар Брант"}, [104]={npc="Демар Брант", tgt="Демар Брант"}, [105]={npc="Демар Брант", tgt="Демар Брант"}, [106]={npc="Демар Брант", tgt="Демар Брант", desc="Сначала нужно победить Властителя Килгара."}, [107]={to="Stormwind", desc="Пересадка будет в Приозерье. Если у вас нет «Передать слова прощания» и «Сумеречная угроза», в Штормград заходить не нужно: если камень возвращения готов, сразу возвращайтесь в Пиратскую Бухту; если камень возвращения перезаряжается, летите из Крепости Фархолд в Пиратскую Бухту через Приозерье и Штормград."}, [108]={npc="Эбигейл Лоусон", tgt="Эбигейл Лоусон"}, [109]={npc="Верховный лорд Болвар Фордрагон", tgt="Верховный лорд Болвар Фордрагон", desc="Сначала нужно победить Властителя Килгара."}, [110]={bindA="{a:35}", desc="Если камень возвращения не привязан к Пиратской Бухте или еще перезаряжается: из Штормграда летите прямо в Пиратскую Бухту; если вы еще в Крепости Фархолд, летите с пересадками в Приозерье и Штормграде."}, [111]={npc="Кразек", tgt="Кразек"}, [112]={npc="Кразек", tgt="Кразек"}}},
    ["05-d20"] = {name="Krol'dok Stronghold", nameA="{a:17780}", entrance="Лесоречье 37.50, 37.90", pickup="При втором визите в Крепость Фархолд возьмите «Глаз Магга» у Демара Бранта, а сдав «Небольшая услуга», возьмите «Фолиант Сумерек» у Эш Амберхолл.", pickupS={{"При втором визите в Крепость Фархолд возьмите «Глаз Магга» у Демара Бранта, а сдав «Небольшая услуга», возьмите «Фолиант Сумерек» у Эш Амберхолл"}}, tips={{k="取捨", text="Для «Сумеречные реликвии» нужно сначала убить элитного властителя Килгара 46 уровня (на основном маршруте необязательно), поэтому задание не включено."}, {k="說明", text="Портал в 37.50, 37.90, камень встреч рядом, в 39.10, 38.80. Внешние ворота крепости — не вход.", s={{"Портал в 37.50, 37.90, камень встреч рядом, в 39.10, 38.80"}, {"Внешние ворота крепости — не вход"}}}}, steps={[1]={npc="Демар Брант", tgt="Демар Брант"}, [2]={npc="Эш Амберхолл", tgt="Эш Амберхолл", tag="Подготовка к подземелью"}, [3]={hint="Добудьте 25 |4сумеречный амулет:сумеречных амулета:сумеречных амулетов; у сумеречных тенемантов и сумеречных неофитов в Светоглади для Эш Амберхолл из крепости Фархолд.", tag="Подготовка к подземелью"}, [4]={npc="Эш Амберхолл", tgt="Эш Амберхолл", tag="Подготовка к подземелью"}, [5]={npc="Эш Амберхолл", tgt="Эш Амберхолл", tag="Подготовка к подземелью"}, [6]={hint="Призовите сумеречного раба с помощью проводника в Сумеречном покрове и плените его при содействии камня души Амберхолл.", tag="Подготовка к подземелью"}, [7]={npc="Эш Амберхолл", tgt="Эш Амберхолл", tag="Подготовка к подземелью"}, [8]={npc="Эш Амберхолл", tgt="Эш Амберхолл"}, [9]={text="Необязательно: удобнее всего до полета в Штормград на {s:03-37}. Если вы уже ушли, сначала летите в Крепость Фархолд (через Приозерье); портал в 37.50, 37.90. После подземелья сдайте задания в Крепости Фархолд и продолжайте с {s:03-39}.", tag="Необязательно"}, [10]={text="Вход: Krol'dok Stronghold"}, [11]={npc="Крол'докская форма", npcObj=true, tag="Необязательно", desc="Tunk роняет форму для отливки. Щелкните правой кнопкой, чтобы начать квест. Tunk находится в кузнице рядом с военным управляющим Ashka. Щелкните правой кнопкой по форме после того, как возьмете ее."}, [12]={hint="Убейте Нар'гурка в крепости Крол'док и соберите всю ценную информацию.", desc="Место: Пройдя Ашку, зачистите зону сумеречных чернокнижников и найдите Нар'гурка.", spot="Пройдя Ашку, зачистите зону сумеречных чернокнижников и найдите Нар'гурка."}, [13]={hint="Проникните в крепость Крол'док, а затем вернитесь к командиру Бранту с доказательствами смерти вражеского лидера.", desc="Место: Пересеките мост, охраняемый Боссманом Туфом, и в самой дальней комнате убейте Оверлорда Магга.", spot="Пересеките мост, охраняемый Боссманом Туфом, и в самой дальней комнате убейте Оверлорда Магга."}, [14]={npc="Демар Брант", tgt="Демар Брант"}, [15]={npc="Эш Амберхолл", tgt="Эш Амберхолл"}, [16]={npc="Альфонсо Дюма", tgt="Альфонсо Дюма", tag="Необязательно"}, [17]={npc="Альфонсо Дюма", tgt="Альфонсо Дюма", tag="Необязательно", desc="Материалы можно заранее купить на аукционе."}, [18]={hint="Принесите 4 |4кусок:куска:кусков; плотной кожи и 12 |4железный слиток:железных слитка:железных слитков; Альфонсо Дюма.", tag="Необязательно", desc="Материалы можно заранее купить на аукционе."}, [19]={npc="Альфонсо Дюма", tgt="Альфонсо Дюма", tag="Необязательно", desc="Материалы можно заранее купить на аукционе."}}},
    ["03-39"] = {grind={[1]={mob="Нага-исследователь", note="Побережье к северу от Пиратской бухты; обычные мобы, стоят кучно."}, [2]={mob="Матрос из шайки Кровавого Паруса", note="Лагерь Кровавого Паруса на южном пляже; те же мобы, что и для заданий на пиратов Кровавого Паруса."}}, steps={[1]={bindA="{a:35}", desc="Если камень возвращения на перезарядке, слетайте с Высоты Найджела в Кабестан (с пересадкой в Тераморе), а затем плывите на корабле в Пиратскую Бухту."}, [2]={text="Если вы еще в Когтистых горах: камень возвращения готов — возвращайтесь в Пиратскую бухту; иначе летите с Пика Каменного Когтя в Кабестан (через Астранаар и Мыс Талрендис) и плывите на корабле в Пиратскую бухту."}, [3]={to="Booty Bay", toA="{a:35}", from="Ratchet", fromA="{a:392}"}, [4]={npc="Шиззи Пуззырикс", tgt="Шиззи Пуззырикс"}, [5]={npc="Шиззи Пуззырикс", tgt="Шиззи Пуззырикс"}, [6]={npc="Диг", tgt="Диг"}, [7]={npc="Кебок", tgt="Кебок"}, [8]={npc="Командир флота Морской Рог", tgt="Командир флота Морской Рог"}, [9]={npc="Капер Блоудс", tgt="Капер Блоудс"}, [10]={npc="Морской волк Маккинли", tgt="Морской волк Маккинли"}, [11]={npc="Одноглазый Диззи", tgt="Одноглазый Диззи"}, [12]={npc="Караванщик Раззгот", tgt="Караванщик Раззгот"}, [13]={hint="Командир флота Морской Рог попросил вас убить 10 висельников из шайки Кровавого Паруса и принести ему карты и приказы Кровавого Паруса.", desc="Ищите бутылки на пляже — подобранная бутылка начинает задание."}, [14]={hint="Диг из Пиратской бухты попросил принести ему 15 понюшек табаку."}, [15]={hint="Диззи Одноглазый из Пиратской бухты попросил вас отобрать его глаз у пиратов Кровавого Паруса."}, [16]={hint="Принесите каперу Блоудсу из Пиратской бухты 10 свертков со стеблями акириса."}, [17]={hint="Принесите барону Ревилгазу в Пиратскую бухту 6 браслетов элементалей воды.", tag="Необязательно"}, [18]={npc="Капер Блоудс", tgt="Капер Блоудс"}, [19]={npc="Капер Блоудс", tgt="Капер Блоудс"}, [20]={npc="Алкач Виски", tgt="Алкач Виски"}, [21]={npc="Диг", 