    ["03-40"] = {grind={[1]={mob="Разбойник из шайки Скитальцев Пустыни", note="Лагерь Скитальцев Пустыни к юго-востоку от Прибамбасска; те же мобы, что и для задания «Расправа над Скитальцами Пустыни»."}, [2]={mob="Темный маг из шайки Скитальцев Пустыни", note="Тот же лагерь; заклинатели, тяните по одному."}}, steps={[1]={to="Gadgetzan", toA="{a:976}"}, [2]={npc="Крейвел Углебрад", tgt="Крейвел Углебрад"}, [3]={npc="Крейвел Углебрад", tgt="Крейвел Углебрад"}, [4]={npc="Пшикс Медноштиф", tgt="Пшикс Медноштиф"}, [5]={npc="Поззик", tgt="Поззик"}, [6]={npc="Замек", tgt="Замек"}, [7]={npc="Замек", tgt="Замек"}, [8]={npc="Неохраняемые чертежи Риззла", npcObj=true, desc="Дождитесь, пока Риззл Медноштиф выйдет из здания, и только потом действуйте."}, [9]={npc="Неохраняемые чертежи Риззла", npcObj=true}, [10]={npc="Поззик", tgt="Поззик"}, [11]={npc="Плакат Разыскивается", npcObj=true}, [12]={npc="Плакат Разыскивается", npcObj=true}, [13]={npc="Оператор крана Тормозиллер", tgt="Оператор крана Тормозиллер"}, [14]={npc="Главный инженер Чепухастер", tgt="Главный инженер Чепухастер"}, [15]={npc="Джорди Пепелатс", tgt="Джорди Пепелатс"}, [16]={hint="Джорди Пепелатс хочет, чтобы вы опустошили контейнер радиоактивных отходов в пустыне Танарис на безопасном расстоянии от Прибамбасска и другого мусора, а затем вернулись к нему.", desc="Найдите свободное место по пути к лагерю Скитальцев Пустыни и используйте там предмет для задания."}, [17]={hint="Убейте 10 бандитов и 10 воров из шайки Скитальцев Пустыни на востоке от Прибамбасска и возвращайтесь к главному инженеру Чепухастеру."}, [18]={desc="Если у вас еще нет 44-го уровня, останьтесь в лагере Скитальцев Пустыни и бейте разбойников и темных магов из шайки Скитальцев Пустыни до 44-го."}, [19]={npc="Отти Кутюри", tgt="Отти Кутюри"}, [20]={npc="Йе'кинья", tgt="Йе'кинья"}, [21]={npc="Столи", tgt="Столи"}, [22]={npc="Столи", tgt="Столи"}, [23]={npc="Начальник отдела безопасности Чепухастер", tgt="Начальник отдела безопасности Чепухастер", desc="Отложите до второго визита в Танарис, когда будете бить огров из клана Песчаного Молота."}, [24]={npc="Начальник отдела безопасности Чепухастер", tgt="Начальник отдела безопасности Чепухастер"}, [25]={npc="Управляющий пристанью Паропшик", tgt="Управляющий пристанью Паропшик", desc="Доступно только после того, как вы взяли в Пороховом порту."}, [26]={hint="Принесите голову Андре Огнебородого начальнику отдела безопасности Чепухастеру в Порт Картеля."}, [27]={hint="Добудьте 20 шляп пиратов Южных Морей и отнесите их Отти Кутюри в Порт Картеля в Танарисе."}, [28]={hint="Начальник отдела безопасности Чепухастер из Порта Картеля в Танарисе просит убить 10 пиратов, 10 флибустьеров, 10 рабочих и 10 висельников Южных морей."}, [29]={hint="Отыщите партию товара Столи и возвратите ее хозяину в Порт Картеля."}, [30]={npc="Джорди Пепелатс", tgt="Джорди Пепелатс"}, [31]={npc="Главный инженер Чепухастер", tgt="Главный инженер Чепухастер"}, [32]={npc="Главный инженер Чепухастер", tgt="Главный инженер Чепухастер"}, [33]={npc="Оператор крана Тормозиллер", tgt="Оператор крана Тормозиллер"}, [34]={hint="Убейте 10 темных магов, 8 разбойников и 6 убийц из шайки Скитальцев Пустыни по поручению главного инженера Чепухастера из Прибамбасска."}, [35]={hint="Принесите голову Калифа Жало Скорпида главному инженеру Чепухастеру в Прибамбасск."}, [36]={npc="Столи", tgt="Столи"}, [37]={npc="Столи", tgt="Столи"}, [38]={npc="Начальник отдела безопасности Чепухастер", tgt="Начальник отдела безопасности Чепухастер"}, [39]={npc="Начальник отдела безопасности Чепухастер", tgt="Начальник отдела безопасности Чепухастер"}, [40]={npc="Отти Кутюри", tgt="Отти Кутюри"}, [41]={npc="Главный инженер Чепухастер", tgt="Главный инженер Чепухастер"}, [42]={npc="Главный инженер Чепухастер", tgt="Главный инженер Чепухастер"}, [43]={npc="Кургль Поскакушка", tgt="Кургль Поскакушка"}}},
    ["05-d10"] = {name="Зул'Фаррак", entrance="Танарис 38.70, 20.10", pickup="Возьмите задания для подземелья заранее, по пути: Тернистая долина (3-й заход). Возвращаться перед походом не придется.", pickupS={{"Возьмите задания для подземелья заранее, по пути: Тернистая долина (3-й заход)"}, {"Возвращаться перед походом не придется"}}, steps={[1]={npc="Виззл Медноштиф", tgt="Виззл Медноштиф", tag="Необязательно, Делайте с группой"}, [2]={npc="Табета", tgt="Табета", tag="Необязательно, Делайте с группой"}, [3]={npc="Кразек", tgt="Кразек"}, [4]={npc="Йе'кинья", tgt="Йе'кинья", tag="Подготовка к подземелью"}, [5]={hint="Поймайте души трех крикунов из Фераласа и возвращайтесь к Йе'кинье в Порт Картеля.", tag="Подготовка к подземелью", desc="Убивайте дольных визгунов на побережье Острова Ужаса в Фераласе. Используйте колючку Йе'кинья на каждом трупе и поговорите с появившимся духом. Повторяйте, пока в журнале не будет трёх духов."}, [6]={npc="Йе'кинья", tgt="Йе'кинья", tag="Подготовка к подземелью"}, [7]={npc="Йе'кинья", tgt="Йе'кинья", tag="Необязательно"}, [8]={npc="Тран'рек", tgt="Тран'рек", tag="Необязательно"}, [9]={npc="Главный инженер Чепухастер", tgt="Главный инженер Чепухастер", tag="Необязательно"}, [10]={npc="Трентон Молот Света", tgt="Трентон Молот Света", tag="Необязательно"}, [11]={text="Вход: Зул'Фаррак"}, [12]={hint="Принесите Тиару Глубин Табете в Пыльную Трясину.", tag="Необязательно, Делайте с группой", spot="Победите гидроманта Велрату у бассейна и заберите её тиару."}, [13]={hint="Принесите искрящую чешую Газ'риллы Виззлу Медноштифу на Мерцающую равнину.", tag="Необязательно, Делайте с группой", spot="У одного из участников группы должен быть Молот Зул'Фаррака, чтобы ударить в гонг у водоёма и призвать Газ'риллу. Если босс уже появился, победите его и заберите чешую."}, [14]={hint="Отнесите медальон Некрума Тадиусу Мрачной Тени в Выжженные земли.", tag="Необязательно, Делайте с группой", spot="Победите Некрума на ступенях пирамиды и подберите его мед