    ["03-41"] = {steps={[1]={to="Thalanaar", toA="{a:489}"}, [2]={text="Из Таланаара идите на запад через Фералас к причалу на побережье и плывите на корабле в Крепость Оперенной Луны."}, [3]={nodeA="{a:1116}", node="Feathermoon Stronghold"}, [4]={npc="Пратт Макгруббен", tgt="Пратт Макгруббен"}, [5]={npc="Мардрак Зеленый Источник", tgt="Мардрак Зеленый Источник"}, [6]={text="Привяжите камень возвращения в таверне: Крепость Оперенной Луны (31.00, 43.20).", bindA="{a:1116}"}, [7]={npc="Шандриса Оперенная Луна", tgt="Шандриса Оперенная Луна"}, [8]={npc="Латроникус Лунное Копье", tgt="Латроникус Лунное Копье"}, [9]={npc="Трояс Лунный Бриз", tgt="Трояс Лунный Бриз"}, [10]={npc="Ангелас Лунный Бриз", tgt="Ангелас Лунный Бриз"}, [11]={npc="Гинро Пылающий Очаг", tgt="Гинро Пылающий Очаг"}, [12]={npc="Гинро Пылающий Очаг", tgt="Гинро Пылающий Очаг"}, [13]={npc="Соларсальская Беседка", npcObj=true}, [14]={npc="Соларсальская Беседка", npcObj=true}, [15]={npc="Шандриса Оперенная Луна", tgt="Шандриса Оперенная Луна"}, [16]={npc="Шандриса Оперенная Луна", tgt="Шандриса Оперенная Луна"}, [17]={npc="Латроникус Лунное Копье", tgt="Латроникус Лунное Копье"}, [18]={npc="Латроникус Лунное Копье", tgt="Латроникус Лунное Копье"}, [19]={hint="Принесите 10 штук чешуи наг из клана Гребня Ненависти Латроникусу Лунному Копью в Крепость Оперенной Луны.", desc="Все наги на побережье к югу от Крепости Оперенной Луны роняют чешую; соберите ее и вернитесь в крепость."}, [20]={npc="Латроникус Лунное Копье", tgt="Латроникус Лунное Копье"}, [21]={npc="Латроникус Лунное Копье", tgt="Латроникус Лунное Копье", tag="Если справляетесь с высокоуровневыми, Необязательно"}, [22]={hint="Убейте лорда Шалзару и принесите обнаруженную им таинственную реликвию Латроникусу Лунному Копью в Крепость Оперенной Луны.", tag="Если справляетесь с высокоуровневыми, Необязательно"}, [23]={text="Побережье Острова Ужаса: используйте колючку на трупе и поговорите с духом."}, [24]={hint="Поймайте души трех крикунов из Фераласа и возвращайтесь к Йе'кинье в Порт Картеля.", desc="Убивайте дольных визгунов на побережье Острова Ужаса в Фераласе. Используйте колючку Йе'кинья на каждом трупе и поговорите с появившимся духом. Повторяйте, пока в журнале не будет трёх духов."}, [25]={npc="Разбитая гребная лодка", npcObj=true}, [26]={npc="Разбитая гребная лодка", npcObj=true}, [27]={bindA="{a:1116}"}, [28]={npc="Гинро Пылающий Очаг", tgt="Гинро Пылающий Очаг"}, [29]={npc="Гинро Пылающий Очаг", tgt="Гинро Пылающий Очаг"}, [30]={npc="Квинтис Ночной Костер", tgt="Квинтис Ночной Костер"}, [31]={npc="Квинтис Ночной Костер", tgt="Квинтис Ночной Костер"}, [32]={npc="Гинро Пылающий Очаг", tgt="Гинро Пылающий Очаг"}, [33]={npc="Гинро Пылающий Очаг", tgt="Гинро Пылающий Очаг"}, [34]={hint="Принесите 10 толстых шкур йети Пратту Макгруббену в Крепость Оперенной Луны."}, [35]={hint="Убейте 8 чернокнижников из клана Гордунни, 8 шаманов из клана Гордунни и 8 громил из клана Гордунни по просьбе Ангелас Лунный Бриз."}, [36]={npc="Кайдел Лунный Ткач", tgt="Кайдел Лунный Ткач"}, [37]={hint="Освободите летучих хамелеонов из вольера в лагере Зловещего Тотема с помощью ключа от бамбуковой клетки. Необходимо, чтобы Кайдел Лунный Ткач и как минимум 6 хамелеонов остались живы.", desc="Лимит времени — 6 минут; перед тем как взять задание, восстановите здоровье и зачистите монстров у загона."}, [38]={npc="Кайдел Лунный Ткач", tgt="Кайдел Лунный Ткач"}, [39]={npc="Джер'кай Лунный Ткач", tgt="Джер'кай Лунный Ткач"}, [40]={hint="Убейте 12 натуралистов из племени Зловещего Тотема, 10 налетчиков из племени Зловещего Тотема и 6 шаманов из племени Зловещего Тотема, а затем вернитесь к Джер'Кай Лунный Ткач в Фераласе."}, [41]={npc="Джер'кай Лунный Ткач", tgt="Джер'кай Лунный Ткач"}, [42]={npc="Джер'кай Лунный Ткач", tgt="Джер'кай Лунный Ткач"}, [43]={npc="Большие кожаные рюкзаки", npcObj=true}, [44]={npc="Большие кожаные рюкзаки", npcObj=true}, [45]={text="Кокон в пещере: заходите внутрь от входа (73.20, 63.90 → 72.30, 64.20)."}, [46]={npc="Кокон Цуккаша", npcObj=true}, [47]={npc="Кокон Цуккаша", npcObj=true}, [48]={hint="Освободите Раскала из улья Цуккаш."}, [49]={npc="Аварийный маяк OOX-22/FE", npcObj=true, tag="Берите, если выпал, Необязательно", desc="Щелкните правой кнопкой по предмету «Аварийный маяк OOX-22/FE» в сумке, чтобы взять задание."}, [50]={npc="Самонаводящийся робот КПX-22/FE", tgt="Самонаводящийся робот КПX-22/FE", tag="Необязательно"}, [51]={npc="Самонаводящийся робот КПX-22/FE", tgt="Самонаводящийся робот КПX-22/FE", tag="Необязательно"}, [52]={hint="Проводите OOX-22/FE в порт на Забытом Берегу, затем сообщите об этом Карлсу Пропеллерзу в Пиратской бухте.", tag="Необязательно", desc="Проводите робокурицу до причала на Забытом берегу на северо-западе, по пути будут засады; задание сдается в Пиратской бухте."}, [53]={hint="Проводите OOX-22/FE в порт на Забытом Берегу, затем сообщите об этом Карлсу Пропеллерзу в Пиратской бухте.", tag="Необязательно", desc="Сопровождение провалено: отмените задание в журнале и снова возьмите его у робота."}, [54]={npc="Ангелас Лунный Бриз", tgt="Ангелас Лунный Бриз"}, [55]={npc="Гинро Пылающий Очаг", tgt="Гинро Пылающий Очаг"}, [56]={npc="Гинро Пылающий Очаг", tgt="Гинро Пылающий Очаг"}, [57]={npc="Шандриса Оперенная Луна", tgt="Шандриса Оперенная Луна"}, [58]={npc="Шандриса Оперенная Луна", tgt="Шандриса Оперенная Луна"}, [59]={npc="Латроникус Лунное Копье", tgt="Латроникус Лунное Копье"}, [60]={npc="Латроникус Лунное Копье", tgt="Латроникус Лунное Копье"}, [61]={npc="Вестия Лунное Копье", tgt="Вестия Лунное Копье"}, [62]={npc="Пратт Макгруббен", tgt="Пратт Макгруббен"}, [63]={to="Rut'theran Village", toA="{a:702}"}}},
    ["05-d21"] = {name="Марадон", entrance="Пустоши 29.10, 62.50", pickup="Если в Пылевых топях вы уже 39 уровня, возьмите задание на осколки тени у верховного мага Тервоша в Тераморе. Остальное берется в Пустошах: Талендрия и хранитель Марандис на Высоте Найджела, Ива, кентавр-пария и, наконец, Кавиндра у входа в пещеру.", pickupS={{"Если в Пылевых топях вы уже 39 уровня, возьмите задание на осколки тени у верховного мага Тервоша в Тераморе"}, {"Остальное берется в Пустошах: Талендрия и хранитель Марандис на Высоте Найджела, Ива, кентавр-пария и, наконец, Кавиндра у входа в пещеру"}}, tips={{k="取捨", text="Чтобы получить скипетр с первого раза, пройдите оранжевую и фиолетовую ветки. Если вам нужны только принцесса и крокодил, а скипетр есть у кого-то из группы, можно сразу идти во внутреннюю часть. Не пропускайте обход, если нужны теневые мобы снаружи или цели в другой ветке."}, {k="說明", text="29.10, 62.50 — вход в пещеру в открытом мире; оранжевый и фиолетовый порталы подземелья ищите, идя по туннелю соответствующего цвета. Фиолетовый и оранжевый пути сходятся у ядовитого водопада.", s={{"29.10, 62.50 — вход в пещеру в открытом мире; оранжевый и фиолетовый порталы подземелья ищите, идя по туннелю соответствующего цвета"}, {"Фиолетовый и оранжевый пути сходятся у ядовитого водопада"}}}}, steps={[1]={npc="Верховный маг Тервош", tgt="Верховный маг Тервош"}, [2]={text="Необязательно: летите из Крепости Оперенной Луны на Высоту Найджела за заданиями, затем идите на юг к Иве и кентавру-парии и, наконец, к пещере Мародона на юго-западе. После подземелья летите в Деревню Рут'теран и продолжайте с {s:04-42}.", tag="Необязательно"}, [3]={npc="Талендрия", tgt="Талендрия"}, [4]={npc="Хранитель Марандис", tgt="Хранитель Марандис"}, [5]={npc="Ива", tgt="Ива"}, [6]={npc="Кентавр-пария", tgt="Кентавр-пария", desc="Кентавр-пария патрулирует южную часть Пустоши."}, [7]={npc="Шен'драларский столп", npcObj=true, tag="Необязательно"}, [8]={hint="Осмотрите Шен'дралас и поищите другие такие же столпы.", tag="Необязательно"}, [9]={npc="Мордент Вечерняя Тень", tgt="Мордент Вечерняя Тень", tag="Необязательно"}, [10]={npc="Мордент Вечерняя Тень", tgt="Мордент Вечерняя Тень", tag="Необязательно", preText="Странные столпы"}, [11]={hint="Добудьте осколки и фрагменты столпов, которые кентавры хранят в деревнях кланов Маграм и Гелкис. Верните их Морденту Вечерней Тени.", tag="Необязательно", desc="Координаты по порядку указывают два предмета в деревнях кентавров Маграм и Гелкис."}, [12]={npc="Мордент Вечерняя Тень", tgt="Мордент Вечерняя Тень", tag="Необязательно"}, [13]={npc="Мордент Вечерняя Тень", tgt="Мордент Вечерняя Тень", tag="Необязательно", desc="Проверьте журнал заданий, чтобы узнать необходимое вам количество маны.", preText="Обломки столпов"}, [14]={hint="Добудьте фильтр маны в храме Шен'драласа и соберите кристаллы древней маны. Затем усильте маной столпы и вернитесь к Морденту Вечерней Тени.", tag="Необязательно", desc="Количество маны зависит от вашего журнала заданий. Возьмите сито на самом верхнем ярусе храма, всего соберите 8 маны, по 4 с каждой башни. Западной и восточной башней можно пользоваться в незаметности."}, [15]={npc="Мордент Вечерняя Тень", tgt="Мордент Вечерняя Тень", tag="Необязательно", desc="Проверьте журнал заданий, чтобы узнать необходимое вам количество маны."}, [16]={npc="Мордент Вечерняя Тень", tgt="Мордент Вечерняя Тень", tag="Необязательно", preText="Насыщение столпов силой"}, [17]={hint="Поговорите с Мордентом Вечерней Тенью в Шен'драласе и узнайте, что за кристаллы вы починили.", tag="Необязательно"}, [18]={npc="Мордент Вечерняя Тень", tgt="Мордент Вечерняя Тень", tag="Необязательно"}, [19]={npc="Мордент Вечерняя Тень", tgt="Мордент Вечерняя Тень", tag="Необязательно", preText="Краткий урок истории"}, [20]={hint="Найдите магистра Кирандиса в храме Шен'драласа.", tag="Необязательно"}, [21]={npc="Магистр Кирандис", tgt="Магистр Кирандис", tag="Необязательно"}, [22]={npc="Митера", tgt="Митера", tag="Необязательно", preText="Встреча с магистром"}, [23]={hint="Обыщите Опустевшие сады около Шен'драласа и вернитесь к Митере в ближайший храм.", tag="Необязательно"}, [24]={npc="Митера", tgt="Митера", tag="Необязательно"}, [25]={npc="Митера", tgt="Митера", tag="Необязательно", preText="Опустевшие сады"}, [26]={npc="Вещедрев", tgt="Вещедрев", tag="Необязательно"}, [27]={npc="Вещедрев", tgt="Вещедрев", tag="Необязательно", desc="Сначала сдайте Слово леса. Возьмите квест во внутреннюю часть Марадона.", preText="Слово леса"}, [28]={npc="Кавиндра", tgt="Кавиндра", desc="Кавиндра стоит снаружи оранжевого портала. С босса на каждой стороне выпадает по одному предмету."}, [29]={hint="Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их верховному магу Тервошу в Терамор на побережье Пылевых топей."}, [30]={text="Вход: Марадон"}, [31]={text="Оранжевая ветка (Foulspore Cavern, 45-53). В глубине пещеры найдите оранжевые кристаллы и пруд, наберите воды и только потом входите в оранжевый портал."}, [32]={hint="Наполните церуленовый фиал с покрытием в оранжевом пруду Мародона.", desc="Место: Наберите воды в пруду у оранжевого портала, затем внутри ищите лозы по пути.", spot="Наберите воды в пруду у оранжевого портала, затем внутри ищите лозы по пути."}, [33]={text="Фиолетовая ветка (Wicked Grotto, 45-53). На развилке из трех ходов идите по проходу с фиолетовыми кристаллами. Заберите алмаз, выпадающий из Лорда Злоязыкого."}, [34]={hint="Соберите 25 терадрических хрустальных орнаментов для Ивы из Пустошей.", desc="Ориентируйтесь на количество в журнале заданий. Место: Сначала убейте кентавров во внешних оранжевой и фиолетовой пещерах, затем после входа собирайте статуи по всему пути.", spot="Сначала убивайте кентавров снаружи у оранжевого и фиолетового порталов, а внутри собирайте статуи по пути."}, [35]={hint="Прочтите инструкции кентавра-парии, добудьте из Мародона амулет Соединения и верните его кентавру-парии из южной части Пустошей.", desc="Первый находится между оранжевой и фиолетовой линиями. Второй и третий находятся в проходах за пределами дверей. Четвертый и пятый находятся за оранжевой и фиолетовой дверями, каждый патрулирует. Место: Первых троих ищите на развилке оранжевой и фиолетовой линий и в двух внешних пещерах, и по одному за каждой дверью.", spot="Найдите трех ханов на развилке и во внешних пещерах, а затем по одному внутри каждого портала."}, [36]={hint="Добудьте две части скипетра Келебраса - жезл Келебраса и бриллиант Келебраса.", desc="Место: Возьмите жезл на оранжевой линии и алмаз на фиолетовой, затем сразитесь с Селебрасом в месте встречи. Порядок: Нужно пройти обе линии — оранжевую и фиолетовую. Сдавайте, только когда соберете все материалы.", spot="Возьмите жезл на оранжевом и алмаз на фиолетовом. Убейте Селебраса там, где они встречаются."}, [37]={npc="Селебрас Искупленный", tgt="Селебрас Искупленный", desc="Победив босса, поговорите с Селебрасом Искупленным. После победы отдайте Искупленному в комнате.", spot="В зале босса Селебраса Проклятого: Селебрас Искупленный"}, [38]={npc="Селебрас Искупленный", tgt="Селебрас Искупленный", desc="Искупленный находится в комнате босса; следуйте за ним во время ритуала.", preText="Легенды Мародона"}, [39]={hint="Помогите Селебрасу Искупленному воссоздать скипетр Селебраса.", desc="Искупленный находится в комнате босса. Следуйте за ним во время ритуала. Место: Комната босса Селебраса: следуйте за Искупленным через весь ритуал.", spot="Следуйте за Селебрасом Искупленным через ритуал в комнате босса."}, [40]={npc="Селебрас Искупленный", tgt="Селебрас Искупленный", desc="Искупленный находится в комнате босса; следуйте за ним во время ритуала.", spot="В зале босса Селебраса Проклятого: Селебрас Искупленный"}, [41]={text="Внутренняя часть, Earth Song Falls (48-57). Спуститесь от места слияния оранжевой и фиолетовой веток или пусть игрок, у которого уже есть скипетр, откроет короткий путь."}, [42]={hint="Отправляйтесь в Мародон и добудьте флакон с водой Поющих водопадов, а затем принесите его Вещедреву в Опустевшие сады посреди Пустошей.", tag="Необязательно", desc="Гнилопасть патрулирует водоем; маленький источник находится на поверхности воды. Прыгните в пруд Гнилопасть под пещерой Принцессы и найдите фонтан на поверхности воды. Сначала используйте фонтан на поверхности, затем ныряйте.", spot="Прыгните в пруд Гнилопасть под пещерой Принцессы и найдите фонтан на поверхности воды."}, [43]={hint="Убейте принцессу Терадрас и вернитесь к хранителю Марандису на Высоту Найджела в Пустоши.", desc="Место: Идите по Earth Song Falls в пещеру Зейтара до платформы Принцессы.", spot="Идите по Earth Song Falls в пещеру Зейтара до платформы Принцессы."}, [44]={npc="Дух Зейтара", tgt="Дух Зейтара", desc="После смерти принцессы Терадрас появляется дух Зейтара. Возьмите квест сейчас, а сдайте после выхода из подземелья."}, [45]={npc="Хранитель Марандис", tgt="Хранитель Марандис"}, [46]={npc="Талендрия", tgt="Талендрия"}, [47]={npc="Ива", tgt="Ива"}, [48]={npc="Кентавр-пария", tgt="Кентавр-пария"}, [49]={npc="Верховный маг Тервош", tgt="Верховный маг Тервош"}, [50]={hint="Отправляйтесь в Мародон и добудьте флакон с водой Поющих водопадов, а затем принесите его Вещедреву в Опустевшие сады посреди Пустошей.", tag="Необязательно"}, [51]={npc="Вещедрев", tgt="Вещедрев", tag="Необязательно"}, [52]={hint="Найдите в Лунной поляне Ремулоса и отдайте ему Семя Жизни.", desc="Можно отложить до Лунной поляны по пути."}, [53]={npc="Хранитель Ремул", tgt="Хранитель Ремул", desc="Можно отложить до Лунной поляны."}}},
    ["04-42"] = {grind={[1]={mob="Береговой клешнехват", note="Пляж напротив Крепости Оперенной Луны, прямо у схода с корабля."}, [2]={mob="Воин из клана Гребень Ненависти", note="Наги на южной оконечности Острова Сардор; рядом с крепостью, уровень немного ниже."}}, steps={[1]={npc="Эрелас Янтарное Небо", tgt="Эрелас Янтарное Небо"}, [2]={npc="Эрелас Янтарное Небо", tgt="Эрелас Янтарное Небо"}, [3]={npc="Дарин Добрый Ветер", tgt="Дарин Добрый Ветер"}, [4]={npc="Фералас: История", npcObj=true}, [5]={npc="Дарин Добрый Ветер", tgt="Дарин Добрый Ветер"}, [6]={npc="Дарин Добрый Ветер", tgt="Дарин Добрый Ветер"}, [7]={text="Пройдите через портал в Деревне Рут'теран в Дарнас.", tag="Можно заранее купить на аукционе (или попросить альта прислать) 15 × «Шелковый материал» (позже для задания «Попался!» в Тлеющем ущелье)."}, [8]={npc="Грацина Сила Духа", tgt="Грацина Сила Духа"}, [9]={npc="Тиранда Шелест Ветра", tgt="Тиранда Шелест Ветра"}, [10]={bindA="{a:1116}"}, [11]={desc="«Затонувший храм» можно взять только с 46-го уровня; если немного не хватает, бейте мобов возле Крепости Оперенной Луны до 46-го; идущий далее «Круглый камень» открывается после него."}, [12]={npc="Ангелас Лунный Бриз", tgt="Ангелас Лунный Бриз"}, [13]={to="Gadgetzan", toA="{a:976}"}, [14]={npc="Кургль Поскакушка", tgt="Кургль Поскакушка"}, [15]={npc="Кургль Поскакушка", tgt="Кургль Поскакушка"}, [16]={npc="Старший геодезист Рудознатец", tgt="Старший геодезист Рудознатец"}, [17]={hint="Воспользуйтесь нетронутым устройством для поиска воды возле пруда на Заставе Скорбных Песков. Забрав пробу, отнесите устройство старшему геодезисту Рудознатцу в Прибамбасск."}, [18]={npc="Старший геодезист Рудознатец", tgt="Старший геодезист Рудознатец"}, [19]={npc="Старший геодезист Рудознатец", tgt="Старший геодезист Рудознатец"}}},
    ["04-43"] = {steps={[1]={npc="Синь Гогельмогель", tgt="Синь Гогельмогель"}, [2]={npc="Анди Линн", tgt="Анди Линн", tag="Необязательно"}, [3]={npc="Тран'рек", tgt="Тран'рек", tag="Если справляетесь с высокоуровневыми, Необязательно"}, [4]={npc="Марвон Клепальщик", tgt="Марвон Клепальщик"}, [5]={npc="Марвон Клепальщик", tgt="Марвон Клепальщик"}, [6]={npc="Марвон Клепальщик", tgt="Марвон Клепальщик"}, [7]={hint="Анди Линн из Прибамбасска просит уничтожить поселение Песчаного Молота, убив 10 громил и 10 мародеров из клана Песчаного Молота и Гор'марока Опустошителя.", tag="Необязательно", desc="Отдельный крюк, других целей рядом нет. Если торопитесь, пропустите."}, [8]={hint="Начальник отдела безопасности Чепухастер из порта Картеля в Танарисе просит найти особенно блестящий браслет, потерянный возле поселения Песчаного Молота."}, [9]={hint="Принесите 5 частей тел насекомых Сентипаар из Ядовитого улья алхимику Пестычинсу в Прибамбасск."}, [10]={hint="Марвон Клепальщик из Танариса поручил собрать 30 газ'рилловых украшений."}, [11]={hint="Добудьте насыщенную влагой железу и принесите ее Синю Гогельмогелю в Прибамбасск."}, [12]={hint="Тран'рек из Прибамбасска просит вас убить 8 бугристых шипошкуров и 8 корнеплетов из долины Кактусов.", tag="Если справляетесь с высокоуровневыми, Необязательно"}, [13]={npc="Аварийный маяк КПХ-17/TN", npcObj=true, tag="Берите, если выпал, Необязательно", desc="Щелкните правой кнопкой по предмету «Аварийный маяк OOX-17/TN» в сумке, чтобы взять задание."}, [14]={npc="Тоога", tgt="Тоога", tag="Необязательно, Эскорт, Если встретили", desc="Берите задание, только если встретили Тугу и готовы сопровождать его пешком."}, [15]={hint="Сопроводите Тоогу к его жене, Торте.", tag="Необязательно, Эскорт", desc="Проводите Тугу пешком к Торте к юго-западу от порта Картеля. Остерегайтесь засад по пути."}, [16]={npc="Самонаводящийся робот КПХ-17/TN", tgt="Самонаводящийся робот КПХ-17/TN", tag="Необязательно", desc="Задание на сопровождение: в группе берите, когда у всех одинаковый прогресс, и отключите автопринятие."}, [17]={npc="Самонаводящийся робот КПХ-17/TN", tgt="Самонаводящийся робот КПХ-17/TN", tag="Необязательно"}, [18]={hint="Сопроводите КПХ-17/TN в Порт Картеля, затем сообщить об этом Карлсу Пропеллерзу в Пиратской бухте.", tag="Необязательно"}, [19]={hint="Сопроводите КПХ-17/TN в Порт Картеля, затем сообщить об этом Карлсу Пропеллерзу в Пиратской бухте.", tag="Необязательно", desc="Сопровождение провалено: отмените задание в журнале и снова возьмите его у робота."}, [20]={npc="Йе'кинья", tgt="Йе'кинья"}, [21]={npc="Торта", tgt="Торта", tag="Необязательно, Эскорт"}, [22]={text="Сопровождение Туги провалено. Можно продолжить основной маршрут. Чтобы повторить попытку, отмените задание и снова найдите Тугу."}, [23]={npc="Начальник отдела безопасности Чепухастер", tgt="Начальник отдела безопасности Чепухастер"}, [24]={npc="Анди Линн", tgt="Анди Линн", tag="Необязательно"}, [25]={npc="Синь Гогельмогель", tgt="Синь Гогельмогель"}, [26]={npc="Синь Гогельмогель", tgt="Синь Гогельмогель"}, [27]={npc="Поливалка", tgt="Поливалка"}, [28]={npc="Поливалка", tgt="Поливалка"}, [29]={npc="Алхимик Пестычинс", tgt="Алхимик Пестычинс"}, [30]={npc="Старший геодезист Рудознатец", tgt="Старший геодезист Рудознатец"}, [31]={npc="Тран'рек", tgt="Тран'рек"}, [32]={npc="Марвон Клепальщик", tgt="Марвон Клепальщик"}, [33]={text="Снаряжение внизу в пещере: спускайтесь по склону от входа (55.00, 70.00 → 54.20, 72.90 → 56.30, 72.20)."}, [34]={hint="Узнайте, что стало с младшим геодезистом Холстомером и приведите его или верните его оборудование старшему геодезисту Рудознатцу в Прибамбасск."}, [35]={npc="Старший геодезист Рудознатец", tgt="Старший геодезист Рудознатец"}, [36]={npc="Старший геодезист Рудознатец", tgt="Старший геодезист Рудознатец"}, [37]={npc="Алхимик Пестычинс", tgt="Алхимик Пестычинс"}, [38]={npc="Алхимик Пестычинс", tgt="Алхимик Пестычинс"}, [39]={npc="Старший геодезист Рудознатец", tgt="Старший геодезист Рудознатец"}, [40]={npc="Старший геодезист Рудознатец", tgt="Старший геодезист Рудознатец"}, [41]={to="Theramore"}, [42]={to="Menethil Harbor", toA="{a:150}", from="Theramore", desc="Корабль из порта Терамора идет прямо в Гавань Менетилов."}, [43]={to="Stormwind", desc="Если вы не брали задание «В поисках Храма», в Штормград идти не нужно: летите прямо из Гавани Менетилов в Южнобережье."}, [44]={npc="Брохан Бочкопуз", tgt="Брохан Бочкопуз"}, [45]={npc="Брохан Бочкопуз", tgt="Брохан Бочкопуз"}}},
    ["04-44"] = {grind={[1]={mob="Дикий совух", note="Лес в центральной части Внутренних земель; мобов много, те же, что и для Перьев дикого совуха."}, [2]={mob="Среброгривый бродяга", note="Волчьи стаи дальше на востоке; стоят разрозненно, можно бить по одному."}}, steps={[1]={to="Southshore", toA="{a:271}", desc="Если Южнобережье не открыто, летите в Гавань Менетилов, сядьте на северном причале на корабль в Аубердин и сойдите в Южнобережье."}, [2]={npc="Ролей Благочестивый", tgt="Ролей Благочестивый", tag="Необязательно"}, [3]={npc="Ролей Благочестивый", tgt="Ролей Благочестивый", tag="Необязательно, Делайте с группой", desc="Победите Локси в библиотеке, Герода в оружейной, Могрейна и Вайтмейн в соборе. Крылья можно пройти за несколько походов."}, [4]={npc="Ролей Благочестивый", tgt="Ролей Благочестивый", tag="Необязательно, Требуются материалы"}, [5]={text="Идите горной тропой на северо-восток во Внутренние земли."}, [6]={npc="Фалстад Громовой Молот", tgt="Фалстад Громовой Молот"}, [7]={nodeA="{a:348}", node="Aerie Peak"}, [8]={npc="Фалстад Громовой Молот", tgt="Фалстад Громовой Молот"}, [9]={npc="Укротитель грифонов Разящий Коготь", tgt="Укротитель грифонов Разящий Коготь"}, [10]={npc="Укротитель грифонов Разящий Коготь", tgt="Укротитель грифонов Разящий Коготь"}, [11]={npc="Укротитель грифонов Разящий Коготь", tgt="Укротитель грифонов Разящий Коготь"}, [12]={npc="Фраггар Громовая Мантия", tgt="Фраггар Громовая Мантия"}, [13]={npc="Фраггар Громовая Мантия", tgt="Фраггар Громовая Мантия"}, [14]={text="Привяжите камень возвращения в таверне: Заоблачный пик (13.80, 41.60).", bindA="{a:348}"}, [15]={npc="Рапсод Землекоп", tgt="Рапсод Землекоп", desc="По пути к совухам; для продолжения нужно принести выпивку — не берите."}, [16]={hint="Собрерите во Внутренних землях 15 перьев диких совухов и отнесите их Эреласу Янтарному Небу в деревню Рут'теран."}, [17]={hint="Проверьте клетки в двух деревнях Сухокожих и возвращайтесь к дрессировщику грифонов Разящему Когтю."}, [18]={desc="Если у вас еще нет 47-го уровня, идите на восток и бейте диких совухов и среброгривых бродяг до 47-го, заодно собирая Перья дикого совуха."}, [19]={hint="Принесите 5 тролльих ожерелий Фраггару Громовой Мантии на Заоблачный пик."}, [20]={hint="Найдите фиалковый траган и вернитесь к Поливалке в Прибамбасск."}, [21]={hint="Убейте 10 зеленых слякочей и 10 нефритовых слизнюков, после чего доложитесь Фраггару Громовой Мантии на Заоблачном Пике."}, [22]={npc="Фраггар Громовая Мантия", tgt="Фраггар Громовая Мантия"}, [23]={npc="Фраггар Громовая Мантия", tgt="Фраггар Громовая Мантия"}, [24]={npc="Укротитель грифонов Разящий Коготь", tgt="Укротитель грифонов Разящий Коготь"}, [25]={npc="Укротитель грифонов Разящий Коготь", tgt="Укротитель грифонов Разящий Коготь"}, [26]={hint="Осмотрите вершину Алтаря Зула и возвращайтесь к укротителю грифонов Разящему Когтю."}, [27]={npc="Аварийный маяк OOX-09/HL", npcObj=true, tag="Берите, если выпал, Необязательно", desc="Щелкните правой кнопкой по предмету «Аварийный маяк OOX-09/HL» в сумке, чтобы взять задание."}, [28]={npc="Самонаводящийся робот КПХ-9/HL", tgt="Самонаводящийся робот КПХ-9/HL", tag="Необязательно"}, [29]={npc="Самонаводящийся робот КПХ-9/HL", tgt="Самонаводящийся робот КПХ-9/HL", tag="Необязательно"}, [30]={hint="Сопроводите OOX-09/HL на побережье за Обзорными скалами, а потом доложитесь Карлсу Пропеллерзу в Пиратской бухте.", tag="Необязательно"}, [31]={hint="Сопроводите OOX-09/HL на побережье за Обзорными скалами, а потом доложитесь Карлсу Пропеллерзу в Пиратской бухте.", tag="Необязательно", desc="Сопровождение провалено: отмените задание в журнале и снова возьмите его у робота."}, [32]={hint="Сделайте снимок Гаммериты с помощью супер-хватателя ФХ и вернитесь к Дарин Добрый Ветер в деревне Рут'теран."}, [33]={hint="Алкач Виски из Пиратской бухты попросил вас принести ему потерянные бутылки портвейна \"Пупелливербос\"."}, [34]={bindA="{a:348}"}, [35]={npc="Укротитель грифонов Разящий Коготь", tgt="Укротитель грифонов Разящий Коготь"}, [36]={npc="Укротитель грифонов Разящий Коготь", tgt="Укротитель грифонов Разящий Коготь"}, [37]={to="Thelsamar", toA="{a:144}"}, [38]={text="Привяжите камень возвращения в таверне Телсамара (35.40, 48.40).", bindA="{a:144}"}, [39]={text="Покиньте Лок Модан на юг и идите отсюда горной тропой в Бесплодные земли."}, [40]={npc="Вейрик Громоцеп", tgt="Вейрик Громоцеп", tag="Делайте с группой, Необязательно", desc="Можно взять только после выполнения заданий «Стихийная помощь» (Лабиринты Иглошкурых) и «Буря, земля и огонь»."}, [41]={hint="Положите конец ритуалу иглогривов с помощью изуродованных тотемов.", tag="Делайте с группой, Необязательно", desc="Летите с Опорного пункта в Гавань Менетилов, сядьте на южной пристани на корабль до Терамора, летите в Таланаар и идите пешком на восток в Тысячу Игл."}, [42]={npc="Вейрик Громоцеп", tgt="Вейрик Громоцеп", tag="Делайте с группой, Необязательно", desc="Летите из Таланаара в Терамор, плывите на корабле в Гавань Менетилов и летите на Опорный пункт."}, [43]={npc="Вейрик Громоцеп", tgt="Вейрик Громоцеп", tag="Необязательно"}, [44]={npc="Бат'ра Ветростраж", tgt="Бат'ра Ветростраж", tag="Необязательно"}, [45]={npc="Бат'ра Ветростраж", tgt="Бат'ра Ветростраж"}, [46]={npc="Бат'ра Ветростраж", tgt="Бат'ра Ветростраж", desc="Нужно: «Клык тролля из клана Кровавый Скальп» ×30, «Жизнекорень» ×8 и «Субстанция Изгнанников» ×1. Чтобы получить «Субстанция Изгнанников», отнесите по 8 × «Пылающий оберег», «Громовой оберег» и «Оберег Гребня» к котлу рядом. «Жизнекорень» и три оберега можно купить на аукционе."}, [47]={hint="Принесите Бат'ра Ветростражу все предметы из его списка."}, [48]={npc="Бат'ра Ветростраж", tgt="Бат'ра Ветростраж"}, [49]={npc="Бат'ра Ветростраж", tgt="Бат'ра Ветростраж"}, [50]={hint="Отнести сердце Вихря Бат-ра Ветростражу."}, [51]={npc="Бат'ра Ветростраж", tgt="Бат'ра Ветростраж"}, [52]={npc="Бат'ра Ветростраж", tgt="Бат'ра Ветростраж", desc="Награда: оружие Смерча."}, [53]={npc="Бат'ра Ветростраж", tgt="Бат'ра Ветростраж", desc="Награда: оружие Смерча."}}},
    ["04-45"] = {tips={{k="取捨", text="Пять сборов делайте вместе. Для сдачи всех нужно в сумме: челюстей ×5, легких кабана ×6, жал скорпионов ×6, мозгов ящеров ×11, зобов стервятников ×14. Каждая сдача списывает материалы."}, {k="取捨", text="Если за стервятников или василисков идет сильная конкуренция, оставьте Укус василиска или Стойкость стервятника невыполненным и, как и планировалось, идите на север в Болото Печали."}}, grind={[1]={mob="Надсмотрщик из клана Черного Железа", note="Дворфы из клана Черного Железа по краям Котлована; подходят по уровню."}, [2]={mob="Поработитель из клана Черного Железа", note="Южная сторона Котлована; уровень немного ниже, мобы стоят разрозненно."}}, steps={[1]={npc="Сигрун Рудотес", tgt="Сигрун Рудотес", tag="Необязательно", desc="По пути обычно выпадают «Чары яркого пламени». Если не выпали, бросьте задание."}, [2]={npc="Гарек", tgt="Гарек", tag="Делайте с группой, Необязательно", desc="Нужно убить двух черных драконов 50 уровня (элиты); без группы пропустите."}, [3]={hint="С помощью знака Земли активируйте алмазный, опаловый и аметистовый столпы и извлеките рунные камни.", tag="Позже, по пути, Делайте с группой, Необязательно"}, [4]={npc="Печать Земли", npcObj=true, tag="Делайте с группой, Необязательно"}, [5]={npc="Печать Земли", npcObj=true, tag="Делайте с группой, Необязательно"}, [6]={npc="Гарек", tgt="Гарек", tag="Делайте с группой, Необязательно"}, [7]={npc="Сигрун Рудотес", tgt="Сигрун Рудотес", tag="Необязательно"}, [8]={hint="Убейте посла Инфернуса в Крепости Ангор и принесите доказательство его смерти советнику Белграму в Стальгорн.", tag="Делайте с группой, Необязательно"}, [9]={text="Из Бесплодных земель идите на запад и по горной тропе рядом с лагерем Орды Каргат войдите в Тлеющее ущелье. Обходите Каргат стороной.", tag="Маршрут полета еще не открыт. В первый раз доберитесь туда пешком."}, [10]={npc="Деревянная уборная", npcObj=true, desc="«Шелковый материал» можно купить на аукционе. Нужно 15 штук."}, [11]={hint="Убейте 8 геологов из клана Черного Железа и принесите 15 отрезов шелка тому, кто заперт в отхожем месте в Тлеющем ущелье."}, [12]={text="Убейте Маргола Яростеня — за него много опыта.", tag="Необязательно", desc="Рог Маргола начинает цепочку заданий на Ключ от Тлеющего ущелья; если не хотите драться, пропустите — связанные с ним дальнейшие шаги пропустятся автоматически, а в конце вы полетите из Стальгорна обратно в Лагерь Братства Тория."}, [13]={npc="Рог Маргола", npcObj=true, tag="Необязательно, Делайте с группой", desc="Щелкните правой кнопкой по предмету «Рог Маргола» в сумке, чтобы взять задание."}, [14]={npc="Деревянная уборная", npcObj=true}, [15]={npc="Деревянная уборная", npcObj=true, tag="Необязательно", desc="Для сдачи нужны четыре вещи: учетная книга у нужника, лапы хрустальных пауков ×20, просроченная посылка из Пылевых топей и меч Жарквии из Болота Печали. За недостающим специально не ходите."}, [16]={hint="Возьмите учетную книгу Кринкеля Сталлинна и найдите все перечисленные в ней вещи. Затем отнесите их и книгу Кринкелю Сталлинну в Танарис.", tag="Требуются материалы"}, [17]={npc="Дориус Камнестраж", tgt="Дориус Камнестраж"}, [18]={hint="Помогите Дориусу вернуться в Стальгорн.", tag="Эскорт", desc="Следуйте за Дориусом на север; после засады, когда журнал покажет задание выполненным, подберите на месте обгоревшее письмо и сдайте его."}, [19]={npc="Опаленное письмо", npcObj=true}, [20]={npc="Опаленное письмо", npcObj=true}, [21]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез"}, [22]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез"}, [23]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез"}, [24]={nodeA="{a:1446}", node="Thorium Point"}, [25]={npc="Розыск/Пропал без вести/Найден", npcObj=true, tag="Делайте с группой, Необязательно", desc="Надсмотрщик Мальтор — элита 50 уровня; без группы пропустите."}, [26]={npc="Розыск/Пропал без вести/Найден", npcObj=true}, [27]={npc="Розыск/Пропал без вести/Найден", npcObj=true}, [28]={npc="Хансел Большерук", tgt="Хансел Большерук"}, [29]={npc="Хансел Большерук", tgt="Хансел Большерук", tag="Необязательно"}, [30]={npc="Хансел Большерук", tgt="Хансел Большерук"}, [31]={npc="Мастер-кузнец Гориврат", tgt="Мастер-кузнец Гориврат"}, [32]={bindA="{a:144}"}, [33]={npc="Горный пехотинец Щебеночка", tgt="Горный пехотинец Щебеночка", tag="Необязательно"}, [34]={npc="Горный пехотинец Щебеночка", tgt="Горный пехотинец Щебеночка"}, [35]={to="Стальгорн"}, [36]={npc="Вейрик Громоцеп", tgt="Вейрик Громоцеп", tag="Необязательно"}, [38]={npc="Куратор Ториус", tgt="Куратор Ториус"}, [39]={npc="Куратор Ториус", tgt="Куратор Ториус"}, [40]={npc="Куратор Ториус", tgt="Куратор Ториус", tag="Необязательно"}, [41]={npc="Куратор Ториус", tgt="Куратор Ториус"}, [42]={npc="Советник Белграм", tgt="Советник Белграм", tag="Делайте с группой, Необязательно"}, [43]={npc="Советник Белграм", tgt="Советник Белграм", tag="Необязательно, Делайте с группой"}, [44]={to="Thelsamar", toA="{a:144}", tag="Необязательно", desc="Возвращайтесь к Щебеночке за ключом, только если у вас есть «Наконец-то!»; если нет, пропустите и летите из Стальгорна прямо в Лагерь Братства Тория."}, [45]={npc="Горный пехотинец Щебеночка", tgt="Горный пехотинец Щебеночка", tag="Необязательно"}, [46]={text="Откройте только что полученным ключом от Тлеющего ущелья ворота рядом с горцем Пебблбитти и пройдите через туннель в Тлеющее ущелье.", tag="Необязательно"}, [47]={to="Thorium Point", toA="{a:1446}", desc="Если у вас нет ключа от Тлеющего ущелья, летите из Стальгорна прямо в Тлеющее ущелье. Если вы уже прошли через туннель, пропустите это."}, [48]={hint="Принесите 4 сердца пламени и 4 меры масла големов Велароку Ветрорезу."}, [49]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез"}, [50]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез"}, [51]={hint="Найдите и верните фурму и подзорную трубу наблюдателя надсмотрщику Скренджу в Тлеющем ущелье. Единственная известная информация: вещи были украдены дворфами Черного Железа. Подзорная труба является бесценным прибором для наблюдения, а фурма - незаменимым кузнечным инструментом."}, [52]={hint="Убейте 15 надсмотрщиков и 15 поработителей из клана Черного Железа. По выполнении задания вернитесь к десятнику Скренджу в Тлеющее ущелье."}, [53]={hint="По поручению Хансела Большерука убейте 20 тяжелых боевых големов, которых можно найти в землях, окружающих Котел в Тлеющем ущелье. По выполнении задания вернитесь к Ханселу."}, [54]={hint="По указанию Хансела Большерука убейте 20 |4опаляющего лавового паука:опаляющих лавовых пауков:опаляющих лавовых пауков; в Тлеющем ущелье. Пауки водятся на вулканических плато и в озерах лавы в Тлеющем ущелье.", tag="Необязательно", desc="Отдельный крюк, других целей рядом нет. Если торопитесь, пропустите."}, [55]={text="От восточного входа с шахтёрами поверните направо и идите по нижнему проходу вдоль лавы к пещере инцендозавров."}, [56]={hint="По поручению Хансела Большерука убейте 20 пламезавров, обитающих в озерах лавы в Шлаковой Яме - это часть Котла в Тлеющем ущелье."}, [57]={desc="Если до 48-го уровня ещё не хватает опыта, оставайтесь в шахте и выманивайте обычных инсендозавров по одному в расчищенный проход. Если безопасных целей нет, вернитесь тем же путём наружу и доберите опыт на надсмотрщиках или работорговцах из клана Чёрного Железа у Котлована."}, [58]={hint="Дворф Черного Железа, вероломный надзиратель Мальториус, скрывается в глубине Шлаковой Ямы в Котле, что в Тлеющем ущелье.", tag="Позже, по пути, Делайте с группой, Необязательно"}, [59]={text="Если идёте за чертежами с востока, перейдите мост и в большом зале поверните налево. Чертежи лежат на столе за надзирателем на верхней площадке. Если там элита, пропустите шаг и вернитесь, когда путь освободится или найдётся группа."}, [60]={hint="Верните секретные документы по изготовлению огненного плавня, украденные надзирателем Мальториусом. Инспектор скорее всего находится в Шлаковой Яме в Котле. Документы верните мастеру-кузнецу Гориврату в Тлеющем ущелье.", desc="Верхнюю площадку может охранять надзиратель Мальториус или элитный часовой. Играя в одиночку, проверьте подход к столу. Убить надзирателя требуется лишь для награды за его голову."}, [61]={hint="Принесите 8 окованных торием кинжалов Велароку Ветрорезу."}, [62]={npc="Умирающий археолог", tgt="Умирающий археолог"}, [63]={npc="Умирающий археолог", tgt="Умирающий археолог"}, [64]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез"}, [65]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез", tag="Необязательно"}, [66]={hint="Найдите таинственный артефакт, охраняемый идолослужителями Сумеречного Молота в северо-западной области Тлеющего ущелья.", tag="Позже, по пути", desc="Артефакт лежит в лагере Сумеречного Молота у северного лавового озера, его охраняют элитные идолопоклонники 49-51-го уровня. Дождитесь, пока элита отойдет, заберите его и уходите. Если не выходит, пропустите этот шаг и сдачу Отпусти их."}, [67]={hint="Найдите знак Рагнароса и принесите его Велароку Ветрорезу.", tag="Делайте с группой, Необязательно, Позже, по пути", desc="Знак Рагнароса падает только с элитных противников."}, [68]={npc="Зимаель Лунный Репей", tgt="Зимаель Лунный Репей"}, [69]={npc="Зимаель Лунный Репей", tgt="Зимаель Лунный Репей"}, [70]={npc="Зимаель Лунный Репей", tgt="Зимаель Лунный Репей", tag="Делайте с группой, Необязательно"}, [71]={npc="Капитан дозорных Лоло Долгобой", tgt="Капитан дозорных Лоло Долгобой", tag="Делайте с группой, Необязательно"}, [72]={npc="Хансел Большерук", tgt="Хансел Большерук"}, [73]={npc="Хансел Большерук", tgt="Хансел Большерук", tag="Необязательно"}, [74]={npc="Хансел Большерук", tgt="Хансел Большерук"}, [75]={npc="Надсмотрщик Скрендж", tgt="Надсмотрщик Скрендж"}, [76]={npc="Надсмотрщик Скрендж", tgt="Надсмотрщик Скрендж"}, [77]={npc="Мастер-кузнец Гориврат", tgt="Мастер-кузнец Гориврат"}, [78]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез", tag="Необязательно"}, [79]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез"}, [80]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез"}, [81]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез"}, [82]={npc="Факел воздаяния", npcObj=true}, [83]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез"}, [84]={npc="Оруженосец Малтрейк", tgt="Оруженосец Малтрейк"}, [85]={npc="Оруженосец Малтрейк", tgt="Оруженосец Малтрейк"}, [86]={hint="Подожгите северную, южную, восточную и западную сторожевые башни с помощью факела воздаяния."}, [87]={npc="Алтарь Сунтары", npcObj=true}, [88]={npc="Умирающий археолог", tgt="Умирающий археолог", tag="Делайте с группой, Необязательно", desc="Латорик Черный и Обсидион — элитные противники 52 уровня; найдите группу."}, [89]={hint="Убейте Латорика Черного и Обсидиона и принесите голову Латорика и сердце Обсидиона Ториусу в Стальгорн.", tag="Делайте с группой, Необязательно"}, [90]={npc="Оруженосец Малтрейк", tgt="Оруженосец Малтрейк"}, [91]={npc="Сокровищница черных драконов", npcObj=true}, [92]={npc="Сокровищница черных драконов", npcObj=true, desc="Сохраните Сброшенную кожу черного дракона и сдайте Цирусу Раскаивателю в Пылающих степях."}, [93]={tag="Необязательно, Делайте с группой", desc="Качайтесь здесь до 52 только с группой в Глубины Черной горы. В одиночку пропустите."}, [94]={to="Стальгорн", desc="Если камень возвращения готов, вернитесь им в Телсамар и летите оттуда; если нет, вернитесь на Ториевую заставу (37.90, 30.40) и найдите распорядителя полетов."}, [95]={npc="Куратор Ториус", tgt="Куратор Ториус", tag="Делайте с группой, Необязательно"}, [96]={npc="Старший исследователь Магеллас", tgt="Старший исследователь Магеллас"}, [97]={npc="Старший исследователь Магеллас", tgt="Старший исследователь Магеллас", desc="Можно взять только после выполнения задания «Платиновые диски» в Ульдамане."}, [98]={npc="Историк Карник", tgt="Историк Карник"}, [99]={npc="Историк Карник", tgt="Историк Карник"}, [100]={text="Привяжите камень возвращения в таверне Стальгорна (18.60, 51.60).", bind="Стальгорн"}, [101]={to="Nethergarde Keep", toA="{a:1438}", desc="Если Крепость Стражей Пустоты не открыта, летите в Темнолесье, идите на восток через Перевал Мертвого Ветра в Болото Печали, а затем на юг через Выжженные земли до Крепости Стражей Пустоты."}, [102]={npc="Тадиус Мрачная Тень", tgt="Тадиус Мрачная Тень"}, [103]={npc="Тадиус Мрачная Тень", tgt="Тадиус Мрачная Тень", tag="Необязательно, Делайте с группой"}, [104]={npc="Волшебник крови Дразиал", tgt="Волшебник крови Дразиал"}, [105]={npc="Волшебник крови Дразиал", tgt="Волшебник крови Дразиал"}, [106]={npc="Волшебник крови Дразиал", tgt="Волшебник крови Дразиал"}, [107]={npc="Волшебница крови Линора", tgt="Волшебница крови Линора"}, [108]={npc="Волшебница крови Линора", tgt="Волшебница крови Линора"}, [109]={hint="Принесите три челюсти гиены, два обожженных легких вепря и одну клешню скорпока магу Крови Дразиалу."}, [110]={hint="Принесите три обожженных легких вепря, две клешни скорпока и один мозг василиска волшебнице крови Дразиале."}, [111]={hint="Принесите три клешни скорпока, две единицы потрохов стервятника и одно обожженное легкое вепря волшебнице крови Дразиале."}, [112]={hint="Принесите десять мозгов василиска и потроха двух стервятников волшебнице крови Линоре."}, [113]={hint="Принесите потроха десяти стервятников и две челюсти гиены волшебнице крови Линоре."}, [114]={npc="Волшебник крови Дразиал", tgt="Волшебник крови Дразиал"}, [115]={npc="Волшебник крови Дразиал", tgt="Волшебник крови Дразиал"}, [116]={npc="Волшебник крови Дразиал", tgt="Волшебник крови Дразиал"}, [117]={npc="Волшебница крови Линора", tgt="Волшебница крови Линора"}, [118]={npc="Волшебница крови Линора", tgt="Волшебница крови Линора"}, [119]={npc="Загадка Кортелло", npcObj=true, tag="Берите, если выпал, Необязательно", desc="Щелкните правой кнопкой по предмету «Загадка Кортелло» в сумке, чтобы взять задание."}, [120]={text="От лагеря магов крови вернитесь на северную дорогу, уйдите из Выжженных земель на север в Болото Печали, затем идите по дороге на запад к западной части болота."}, [121]={npc="Промокший свиток", npcObj=true}, [122]={npc="Промокший свиток", npcObj=true}}},
    ["04-46"] = {grind={[1]={mob="Небогривая горилла", note="Островок, на котором обитает Король Мукла; обычные мобы, зачистите их заодно после убийства короля."}, [2]={mob="Жагуар", note="Западная сторона того же острова."}}, steps={[1]={to="Booty Bay", toA="{a:35}", desc="В Болоте Печали нет пункта полета Альянса: идите на запад через Перевал Мертвого Ветра обратно в Темнолесье и летите оттуда."}, [2]={npc="Шиззи Пуззырикс", tgt="Шиззи Пуззырикс"}, [3]={npc="Шиззи Пуззырикс", tgt="Шиззи Пуззырикс"}, [4]={npc="Алкач Виски", tgt="Алкач Виски"}, [5]={npc="Морской волк Маккинли", tgt="Морской волк Маккинли"}, [6]={npc="Фин Горемык", tgt="Фин Горемык"}, [7]={npc="Карлс Пропеллерз", tgt="Карлс Пропеллерз", tag="Необязательно"}, [8]={npc="Карлс Пропеллерз", tgt="Карлс Пропеллерз", tag="Необязательно"}, [9]={npc="Карлс Пропеллерз", tgt="Карлс Пропеллерз", tag="Необязательно"}, [10]={npc="Карлс Пропеллерз", tgt="Карлс Пропеллерз", tag="Необязательно"}, [11]={npc="Карлс Пропеллерз", tgt="Карлс Пропеллерз", tag="Необязательно"}, [12]={npc="Бережно свернутая записка", npcObj=true, desc="Щелкните правой кнопкой по предмету «Бережно свернутая записка» в сумке, чтобы взять задание. Щелкните правой кнопкой по сложенной записке, полученной ранее, чтобы начать задание."}, [13]={npc="Принцесса Пуба", tgt="Принцесса Пуба"}, [14]={npc="Принцесса Пуба", tgt="Принцесса Пуба", tag="Делайте с группой, Необязательно"}, [15]={hint="Убейте Короля Муклу, возвращайтесь с ключом к принцессе Пубе и освободите ее.", tag="Делайте с группой, Необязательно"}, [16]={npc="Принцесса Пуба", tgt="Принцесса Пуба", tag="Делайте с группой, Необязательно"}, [17]={npc="Знахарь Унбагва", tgt="Знахарь Унбагва", desc="Сначала возьмите Лихорадка Тернистой долины, затем выполните событие со сдачей бивней."}, [18]={hint="Добыча с: Горилла из Мглистой долины, Джунглевый рокотун, Разъяренная седоспиная горилла", desc="Сначала возьмите Лихорадка Тернистой долины, затем выполните событие со сдачей бивней."}, [19]={npc="Знахарь Унбагва", tgt="Знахарь Унбагва", desc="Сначала возьмите Лихорадка Тернистой долины, затем выполните событие со сдачей бивней."}, [20]={hint="Найдите знахаря Унбагва и попросите его вызвать Мокка Дикаря. Принесите сердце Мокка Фину Горемыку.", desc="Сдача Лихорадка Тернистой долины призывает Мокка. Если не хватает клыков горилл или не удается сдержать волны горилл, пропустите этот шаг и сдачу Лихорадка Тернистой долины ниже; дальше от этого ничего не зависит."}, [21]={desc="Если у вас еще нет 49-го уровня, продолжайте бить горилл в Туманной долине до 49-го."}, [22]={npc="Фин Горемык", tgt="Фин Горемык"}, [23]={to="Ratchet", toA="{a:392}", from="Booty Bay", fromA="{a:35}"}, [24]={hint="Заберите круглый камень из мастерской Марвона Клепальщика в Кабестане."}, [25]={to="Theramore"}, [26]={npc="Заплесневелый свиток", npcObj=true}, [27]={npc="Заплесневелый свиток", npcObj=true, tag="Необязательно"}}},
    ["05-d22"] = {name="Alcaz Prison", entrance="Пылевые топи 75.30, 14.10", pickup="На {s:04-46}, перед полетом из Темнолесья в Пиратскую Бухту, если вы 48 уровня, сначала летите в Штормград и возьмите «Контакт в Тераморе» у мастера Матиаса Шоу. Когда {s:04-46} закончится полетом в Терамор, найдите Салли Маклири для продолжения.", pickupS={{"На {s:04-46}, перед полетом из Темнолесья в Пиратскую Бухту, если вы 48 уровня, сначала летите в Штормград и возьмите «Контакт в Тераморе» у мастера Матиаса Шоу"}, {"Когда {s:04-46} закончится полетом в Терамор, найдите Салли Маклири для продолжения"}}, tips={{k="提醒", text="Дополнительно с 48-го уровня: до входа договоритесь оставить Дознавателя в живых. После победы над последним боссом поговорите с закованным пленником. Примите задание, вернитесь за ключом к Дознавателю и отдайте его пленнику.", s={{"Дополнительно с 48-го уровня: до входа договоритесь оставить Дознавателя в живых"}, {"После победы над последним боссом поговорите с закованным пленником"}, {"Примите задание, вернитесь за ключом к Дознавателю и отдайте его пленнику"}}}}, steps={[1]={npc="Мастер Матиас Шоу", tgt="Мастер Матиас Шоу"}, [2]={npc="Салли Маклири", tgt="Салли Маклири"}, [3]={npc="Салли Маклири", tgt="Салли Маклири"}, [4]={npc="Салли Маклири", tgt="Салли Маклири"}, [5]={npc="Салли Маклири", tgt="Салли Маклири"}, [6]={hint="Используйте маскировочный комплект ШРУ, чтобы подслушать разговор Джайны с советниками в башне магов Терамора."}, [7]={npc="Салли Маклири", tgt="Салли Маклири"}, [8]={npc="Салли Маклири", tgt="Салли Маклири"}, [9]={npc="Салли Маклири", tgt="Салли Маклири", tag="Необязательно"}, [10]={text="Необязательно: из Терамора идите вдоль восточного берега на север к северо-восточному берегу Пылевых топей и плывите на остров Алказ; портал в коридоре под башней острова. После подземелья сдайте задания в Тераморе и продолжайте с {s:04-47}.", tag="Необязательно"}, [11]={text="Вход: Alcaz Prison"}, [12]={hint="Проникните в тюрьму Алькац и убейте 15 |4солдата:солдат:солдат; и 8 |4зачаровательницу:зачаровательниц:зачаровательниц; из клана Страшаз, а также принесите Салли Маклири голову Повелительницы приливов Ка'засс.", tag="Необязательно", desc="Место: Повелительницу приливов Ка'засс найдите у камер верхнего яруса; по коридору зачищайте наг.", spot="Повелительницу приливов Ка'засс найдите у камер верхнего яруса; по коридору зачищайте наг."}, [13]={hint="Проникните в тюрьму Алькац и выясните, что произошло с королем Штормграда.", desc="Место: Откройте нижнюю дверь и убейте последнего босса; затем войдите в заднюю комнату и найдите записку на полу. Порядок: Сначала возьмите ключ у надзирателя.", spot="Откройте двери нижнего яруса, убейте последнего босса и найдите записку на полу в тайной комнате позади него."}, [14]={npcObj=true, spot="Записка на полу тайной комнаты за Blazeroar"}, [15]={npcObj=true}, [16]={tag="Необязательно", desc="После последнего босса поговорите с закованным пленником рядом. Дознаватель должен быть еще жив, чтобы вы получили ключ."}, [17]={hint="Заберите ключ от кандалов Алькаца у Дознавателя в тюрьме Алькац.", tag="Необязательно"}, [18]={tag="Необязательно", spot="Рядом с последним боссом, закованный пленник"}, [19]={npc="Салли Маклири", tgt="Салли Маклири", tag="Необязательно"}, [20]={npc="Салли Маклири", tgt="Салли Маклири"}, [21]={npc="Салли Маклири", tgt="Салли Маклири"}, [22]={npc="Мастер Матиас Шоу", tgt="Мастер Матиас Шоу", desc="Сдайте при следующем визите в Штормград."}}},
    ["04-47"] = {steps={[1]={to="Gadgetzan", toA="{a:976}", desc="Свиток лежит в пещере ящеров к юго-западу от Пылевых топей. Сначала идите на восток обратно в Терамор (67.48, 51.30), а потом летите."}, [2]={npc="Кринкель Сталлер", tgt="Кринкель Сталлер", tag="Требуются материалы"}, [3]={npc="Поливалка", tgt="Поливалка"}, [4]={npc="Поливалка", tgt="Поливалка"}, [5]={npc="Синь Гогельмогель", tgt="Синь Гогельмогель"}, [6]={npc="Синь Гогельмогель", tgt="Синь Гогельмогель"}, [7]={npc="Синь Гогельмогель", tgt="Синь Гогельмогель"}, [8]={text="От Прибамбасска идите по дороге на север на Мерцающую равнину в Тысячу Игл."}, [9]={npc="Крейвел Углебрад", tgt="Крейвел Углебрад"}, [10]={npc="Крейвел Углебрад", tgt="Крейвел Углебрад"}, [11]={npc="Начальник гномского гаража", tgt="Начальник гномского гаража"}, [12]={npc="Виззл Медноштиф", tgt="Виззл Медноштиф", tag="Необязательно"}, [13]={npc="Виззл Медноштиф", tgt="Виззл Медноштиф", tag="Необязательно, Делайте с группой"}, [14]={npc="Марвон Клепальщик", tgt="Марвон Клепальщик"}, [15]={npc="Пьедестал Ульдума", npcObj=true}, [16]={npc="Каменный дозорный Нограннона", tgt="Каменный дозорный Нограннона"}, [17]={npc="Пьедестал Ульдума", npcObj=true}, [18]={npc="Пьедестал Ульдума", npcObj=true}, [19]={text="Идите на северо-запад к началу тропы в кратер Ун'Горо."}}},
    ["04-48"] = {grind={[1]={mob="Кровоцвет-хлыстун", note="Растения на восточной стороне; бейте их сразу, как войдете в кратер."}, [2]={mob="Ун'горская горилла", note="У пещеры горилл на северо-востоке; те же мобы, что и для шкур горилл."}, [3]={mob="Жутедактиль", note="Скалы к востоку от Укрытия Маршалла."}, [4]={mob="Смоляной скрытень", note="Смоляные ямы к югу от лагеря; уровень высоковат, тяните по одному."}}, steps={[1]={text="По горной дороге к западу от Танариса спуститесь по спуску в Кратер Ун'Горо. Землепроходец Торва стоит прямо у входа внизу спуска.", tag="Маршрут полета еще не открыт. В первый раз доберитесь туда пешком."}, [2]={npc="Землепроходец Торва", tgt="Землепроходец Торва", tag="Если справляетесь с высокоуровневыми, Необязательно"}, [3]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [4]={npc="Разбитый плот", npcObj=true, desc="Соберите по 7 красных, синих, зеленых и желтых кристаллов и добудьте у ящеров «Изорванный дневник»."}, [5]={npc="Небольшая сумка", npcObj=true}, [6]={npc="Небольшая сумка", npcObj=true}, [7]={hint="Найдите последнюю добычу Лар'корви, украдите кусок трупа жесткозуба и вернитесь к землепроходцу Торве в Кратер Ун'Горо."}, [8]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [9]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [10]={hint="Принесите 2 феромонные железы равазавра землепроходцу Торве в преддверие Кратера Ун'Горо."}, [11]={npc="Пронизанная кристаллами чешуя", npcObj=true, tag="Необязательно"}, [12]={npc="Землепроходец Торва", tgt="Землепроходец Торва", tag="Необязательно, Требуются материалы"}, [13]={text="Используйте пронизанную кристаллами чешую из сумки, чтобы начать задание «Загрязнение микрокристаллами». Затем сдайте оба задания Торве."}, [14]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [15]={npc="Землепроходец Торва", tgt="Землепроходец Торва", tag="Необязательно"}, [16]={hint="С помощью предметов из мешочка Торвы выманите Лар'корви и сразите его. Принесите голову Лар'корви землепроходцу Торве ко входу в Кратер Ун'Горо.", tag="Делайте с группой, Необязательно", desc="Это задание сложнее. Можно оставить до возвращения в Ун'Горо."}, [17]={npc="Карна Сомнамбулер", tgt="Карна Сомнамбулер"}, [18]={npc="Линкен", tgt="Линкен"}, [19]={npc="Линкен", tgt="Линкен"}, [20]={nodeA="{a:541}", node="Marshal's Refuge"}, [21]={npc="Виллиден Маршал", tgt="Виллиден Маршал"}, [22]={npc="Холания Маршал", tgt="Холания Маршал"}, [23]={npc="Искр Пустокоп", tgt="Искр Пустокоп"}, [24]={npc="Джей Ди Колли", tgt="Джей Ди Колли", desc="Собирайте кристаллы силы по пути. Если при первой встрече с Джей Ди Колли у вас есть по семь кристаллов каждого цвета, отдайте их сразу. Если каких-то не хватает, завершите задание в следующий раз."}, [25]={npc="Опасайся жутедактиля", npcObj=true}, [26]={npc="Майджин", tgt="Майджин"}, [27]={npc="Шиззл", tgt="Шиззл"}, [28]={hint="Принесите 8 костей динозавра Искру Пустокопу в Кратер Ун'Горо."}, [29]={hint="Принесите 2 шкуры Ун'Горской гориллы, 2 шкуры Ун'Горского топтуна и 2 шкуры Ун'Горского рокотуна землепроходцу Торве к входу в Кратер Ун'Горо.", tag="Если справляетесь с высокоуровневыми, Необязательно"}, [30]={desc="Если у вас еще нет 50-го уровня, останьтесь у пещеры горилл и бейте ун'горских горилл до 50-го."}, [31]={hint="Соберите 15 кровоцветов и принесите их Майджину."}, [32]={text="Заберите ящик с провизией в восточном лагере."}, [33]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [34]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [35]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [36]={text="За образцом — в улей: идите на юго-запад ко входу в пещеру и заходите внутрь (50.40, 78.80 → 48.70, 85.20)."}, [37]={hint="Воспользуйтесь фиалом для образцов, чтобы взять образец материала стены улья из одного из инкубаторов Гориши в Кратере Ун'Горо. Ищите в ульях комнаты со свисающими гроздьями личинок."}, [38]={text="Завершите взятые задания на убийство и сбор."}, [39]={hint="Принесите ящик с провизией и исследовательское оборудование Виллидену Маршалу в Кратер Ун'Горо.", desc="Ящик с провизией на востоке (по пути к пещере горилл и Торве), Исследовательское оборудование на юго-западе (по пути от улья к птеродаксам), подберите по одному по дороге."}, [40]={hint="Принесите 8 чешуй перепончатого деметродона 8 чешуй перепончатого жутедактиля Шиззлу в Укрытие Маршалла."}, [41]={hint="Убейте 10 жутедактилей и 15 бесноватых жутедактилей, затем поговорите со Мучей Кусора в Укрытии Маршалла."}, [42]={npc="Шиззл", tgt="Шиззл"}, [43]={npc="Майджин", tgt="Майджин"}, [44]={npc="Майджин", tgt="Майджин"}, [45]={npc="Муча Кусора", tgt="Муча Кусора"}, [46]={npc="Искр Пустокоп", tgt="Искр Пустокоп"}, [47]={npc="Холания Маршал", tgt="Холания Маршал"}, [48]={npc="Виллиден Маршал", tgt="Виллиден Маршал"}, [49]={npc="Изорванный дневник", npcObj=true, tag="Необязательно", desc="Берите задание правым щелчком, только если с монстров выпал Изорванный дневник."}, [50]={npc="Виллиден Маршал", tgt="Виллиден Маршал", tag="Необязательно"}, [51]={desc="Если у вас еще нет 51-го уровня, бейте жутедактилей к востоку от лагеря или смоляных скрытней у смоляных ям на юге до 51-го."}, [52]={bind="Стальгорн", desc="Если камень возвращения привязан к Стальгорну, вернитесь в город, когда камень можно будет использовать. Верховный жрец Рохан предлагает жрецам задание «Помощь Кенарию». Маги могут взять задание «Магическое искусство» у Динка."}, [53]={text="Идите, только если хотите взять вводное задание в Штормграде: в Стальгорне сядьте на подземный поезд до Штормграда.", tag="Необязательно"}, [54]={npc="Магинор Дюма", tgt="Магинор Дюма", tag="Необязательно", desc="Вводное задание в Штормграде можно пропустить. По прибытии в Азшару все равно нужно сначала найти Санат Лим-Йо, чтобы вас телепортировали на утес."}, [55]={text="Из Штормграда летите в Гавань Менетилов и возвращайтесь на маршрут.", tag="Необязательно"}, [56]={npc="Верховный жрец Рохан", tgt="Верховный жрец Рохан", tag="Можно заранее купить на аукционе (или попросить альта прислать) 1 × «Лимфа нежити» (позже для задания «Лимфа нежити» в Азшаре).", desc="Сдайте Огтинку в Азшаре."}, [57]={to="Menethil Harbor", toA="{a:150}", desc="Проверьте карту полётов в Укрытии Маршалла. Если доступен рейс до Аубердина или деревни Рут'теран, летите туда. Иначе вернитесь в Танарис по юго-восточному склону и проверьте рейсы в Прибамбасске."}, [58]={to="Аубердин", from="Menethil Harbor", fromA="{a:150}", desc="Этот корабль по пути заходит в Южнобережье. Сойдите в Аубердине."}, [59]={to="Rut'theran Village", toA="{a:702}", desc="В Аубердине пересядьте на транспорт до деревни Рут'теран. Если вы на корабле, сойдите после швартовки. Выберите доступный рейс или корабль у северной пристани (33.3, 39.8)."}, [60]={npc="Эрелас Янтарное Небо", tgt="Эрелас Янтарное Небо"}, [61]={npc="Дарин Добрый Ветер", tgt="Дарин Добрый Ветер"}, [62]={npc="Дарин Добрый Ветер", tgt="Дарин Добрый Ветер"}, [63]={text="Пройдите через портал в Деревне Рут'теран в Дарнас.", tag="Можно заранее купить на аукционе (или попросить альта прислать) 1 × «Мифриловая обшивка» (позже для задания «В поисках Чи-Та 3» в Кратере Ун'Горо)."}, [64]={npc="Грацина Сила Духа", tgt="Грацина Сила Духа"}, [65]={npc="Грацина Сила Духа", tgt="Грацина Сила Духа"}, [66]={npc="Астария Ловец Звезд", tgt="Астария Ловец Звезд", tag="Делайте с группой, Необязательно"}, [67]={npc="Дорион", tgt="Дорион", desc="Возьмите в Дарнасе (или Стальгорне, Штормграде) и сдайте Огтинку в Азшаре."}, [68]={text="Пройдите через портал в Дарнасе обратно в Деревню Рут'теран."}, [69]={to="Astranaar", toA="{a:415}"}, [70]={text="Привяжите камень возвращения в таверне Астранаар (37.00, 49.20).", bindA="{a:415}"}, [71]={text="Проверьте, где вы находитесь. Если вы на корабле, сойдите в порту назначения. В Аубердине пересядьте на транспорт до деревни Рут'теран. Оказавшись на берегу в Рут'теране, сдайте задания."}, [72]={text="Прежде чем отправиться в Восточные королевства за классовым заданием, проверьте в Укрытии Маршалла, доступен ли перелёт в Аубердин. Если подходящего рейса нет, вернитесь в Танарис по юго-восточному склону и проверьте рейсы в Прибамбасске. Добравшись до Аубердина, сядьте на корабль, идущий прямо в Штормград."}, [73]={text="В Аубердине сядьте на корабль, идущий прямо в Штормград. Если вы ещё на борту, дождитесь швартовки, сойдите и ждите корабль у причала до Штормграда (30.5, 40.9)."}, [74]={text="В порту Штормграда дождитесь корабля обратно в Аубердин у причала (21.8, 56.9). В Аубердине сойдите на берег и продолжите путь по Калимдору."}, [75]={text="Сначала проверьте, где вы находитесь и есть ли место в журнале заданий. Если вы едете в Восточные королевства за классовым заданием, оставьте одно свободное место. Если вы ещё на корабле, дождитесь швартовки в порту назначения и только тогда сойдите."}, [76]={text="В порту Штормграда дождитесь швартовки, сойдите и найдите в городе того, кто выдаёт ваше классовое задание. Если корабль ещё в море, оставайтесь на борту."}, [77]={npc="Брат Джошуа", tgt="Брат Джошуа"}, [78]={npc="Динк", tgt="Динк", tag="Необязательно"}, [79]={text="Узнайте у распорядителя полетов в Стальгорне, можно ли долететь до гавани Менетилов. Если рейса нет, поезжайте на Подземном поезде в Штормград и садитесь в порту на корабль до Аубердина."}, [80]={to="Talrendis Point", toA="{a:3137}"}, [81]={npc="Ло'хату", tgt="Ло'хату"}, [82]={npc="Ло'хату", tgt="Ло'хату"}, [83]={hint="Уничтожьте по 6 теней высокорожденных обоих полов и возвращайтесь к Ло'хату в Азшару."}, [84]={hint="Уничтожьте 6 сатиров, 2 плутов Халдарра и 2 скверноподданных из племени Халдарр и возвращайтесь к Ло'хату к границе Ясеневого леса."}, [85]={npc="Ло'хату", tgt="Ло'хату"}, [86]={npc="Ло'хату", tgt="Ло'хату"}, [87]={npc="Санат Лим-Йо", tgt="Санат Лим-Йо", tag="Необязательно", desc="Сдавайте здесь, только если брали вводное задание."}, [88]={text="Поговорите с Санат Лим-Йо и попросите телепортировать вас на утес к верховному магу Ксилему."}, [89]={npc="Верховный маг Ксилем", tgt="Верховный маг Ксилем"}, [90]={hint="Принесите 10 горстей сияющей пыли верховному магу Ксилему."}, [91]={npc="Верховный маг Ксилем", tgt="Верховный маг Ксилем", desc="Пыль лежит у подножия горы; вернитесь к Санат Лим-Йо тем же способом, чтобы вас телепортировали наверх."}, [92]={npc="Верховный маг Ксилем", tgt="Верховный маг Ксилем"}, [93]={hint="Соберите 6 заколдованных кораллов и принесите их верховному магу Ксилему."}, [94]={npc="Верховный маг Ксилем", tgt="Верховный маг Ксилем"}, [95]={npc="Верховный маг Ксилем", tgt="Верховный маг Ксилем", tag="Делайте с группой, Необязательно", desc="Морфаз находится в Храме Атал'Хаккара."}, [96]={hint="Добудьте кристалл тайной магии из брюха Морфаза и принесите его верховному магу Ксилему.", tag="Делайте с группой, Необязательно", desc="Морфаз находится в Храме Атал'Хаккара."}, [97]={npc="Верховный маг Ксилем", tgt="Верховный маг Ксилем", tag="Делайте с группой, Необязательно", desc="Морфаз находится в Храме Атал'Хаккара."}, [98]={text="Отправляйтесь в Оскверненный лес через Астранаар. Если камень возвращения привязан к Астранаару и готов к использованию, вернитесь с его помощью в таверну. Когда безопасно спуститесь со скалы, проверьте карту полетов на Заставе Талрендис. Если доступен перелет в Астранаар, воспользуйтесь им. В противном случае идите на запад по главной дороге через восточную часть Ясеневого леса. Из Астранаара идите по главной дороге на север в Оскверненный лес."}, [99]={npc="Огтинк", tgt="Огтинк"}, [100]={npc="Огтинк", tgt="Огтинк"}, [101]={hint="Добудьте 4 железы здорового мохоногого оленя и принесите их Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата."}, [102]={npc="Огтинк", tgt="Огтинк"}, [103]={npc="Огтинк", tgt="Огтинк", desc="«Лимфа нежити» ×1 можно купить на аукционе."}, [104]={hint="Принесите лимфу нежити Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата."}, [105]={npc="Огтинк", tgt="Огтинк"}, [106]={npc="Огтинк", tgt="Огтинк", tag="Делайте с группой, Необязательно", desc="Морфаз находится в Храме Атал'Хаккара."}, [107]={text="Если вы ещё в Азшаре, вернитесь на заставу Талрендис, летите в Астранаар и идите на север в Осквернённый лес. После храма отправляйтесь прямо в Изумрудное святилище в Осквернённом лесу."}, [108]={npc="Огтинк", tgt="Огтинк", desc="Возьмите в Дарнасе (или Стальгорне, Штормграде) и сдайте Огтинку в Азшаре."}, [109]={npc="Огтинк", tgt="Огтинк"}, [110]={hint="Принесите пару великолепных рогов мохоногого оленя Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата."}, [111]={npc="Огтинк", tgt="Огтинк"}, [112]={npc="Огтинк", tgt="Огтинк"}, [113]={hint="Принесите 6 чешуй волношлепа Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата."}, [114]={npc="Огтинк", tgt="Огтинк"}, [115]={npc="Огтинк", tgt="Огтинк", tag="Делайте с группой, Необязательно", desc="Зеленый дракон находится в Храме Атал'Хаккара."}, [116]={hint="Принесите зуб Морфаза Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.", tag="Делайте с группой, Необязательно", desc="Зеленый дракон находится в Храме Атал'Хаккара."}, [117]={npc="Огтинк", tgt="Огтинк", tag="Делайте с группой, Необязательно", desc="Зеленый дракон находится в Храме Атал'Хаккара."}, [118]={text="Вернитесь на Заставу Талрендис и летите в Астранаар, затем идите по главной дороге на север в Оскверненный лес."}, [119]={to="Astranaar", toA="{a:415}"}}},
    ["04-49"] = {grind={[1]={mob="Джеденарский страж", note="Район входа в Джеденар; обычные мобы."}, [2]={mob="Джеденаский сектант", note="Встречаются вперемешку со стражами; заклинатели."}}, steps={[1]={text="От Астранаара идите по дороге на север в Оскверненный лес.", tag="Маршрут полета еще не открыт. В первый раз доберитесь туда пешком."}, [2]={npc="Аратандис Серебряное Небо", tgt="Аратандис Серебряное Небо"}, [3]={npc="Гразл", tgt="Гразл"}, [4]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто"}, [5]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто", tag="Делайте с группой, Необязательно, Требуются материалы"}, [6]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [7]={npc="Тарун Красное Перо", tgt="Тарун Красное Перо"}, [8]={hint="Гразл желает, чтобы вы заслужили доверие. Вам нужно убить 6 воинов, 6 землепроходцев и 6 садовников из племени Мертвого Леса. Выполнив поручение, возвращайтесь в южную часть Оскверненного леса к Изумрудному святилищу."}, [9]={npc="Гразл", tgt="Гразл"}, [10]={npc="Гразл", tgt="Гразл"}, [11]={hint="Убейте 11 скверноподданных, 9 тенеловов, 9 разбойников из племени Нефритового Пламени и Ксаватраса. Возвращайтесь к Эридане Грусти Ветра в Оскверненный лес по выполнении задания."}, [12]={hint="Отправляйтесь в Джеденар и убейте 4 джеденарских гончих, 4 джеденарских стражей, 6 джеденарских адептов и 6 джеденарских сектантов, затем возвращайтесь к Грете Заиндевевшее Копыто в Оскверненный лес."}, [13]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [14]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [15]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто"}, [16]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто"}, [17]={hint="Возьмите пустую флягу и наполните ее водой из лунного колодца, что находится в центре Джеденара. Возвращайтесь к Грете Замшелому Копыту в Оскверненный лес."}, [18]={desc="Убивайте монстров около 35, 59 в Джеденаре."}, [19]={hint="Найдите и уничтожьте 2 энтропических зверей и 2 энтропических ужасов при обследовании долины Рваных Ран. После проверьте, по-прежнему ли заполнены кратеры оскверненной водой. Затем возвращайтесь к Таруну Красному Перу в Оскверненный лес."}, [20]={hint="Эридана Грусть Ветра из Оскверненного леса просит вас убить 8 призывателей огня, 8 предателей и 8 плутов из племени Нефритового огня, а также Ксаварика. По выполнении задания возвращайтесь к Эридане."}, [21]={npc="Флейта Ксаварика", npcObj=true, desc="Щелкните правой кнопкой по предмету «Флейта Ксаварика» в сумке, чтобы взять задание."}, [22]={hint="Принесите флейту Ксаварика и 5 образцов уз Скверны нефритового огня Эридане Грусти Ветра в южную часть Оскверненного леса."}, [23]={hint="Принесите 15 кровавых янтарей Аратандис Серебряному Небу в Оскверненный лес."}, [24]={nodeA="{a:1998}", node="Talonbranch Glade"}, [25]={npc="Нафиэн", tgt="Нафиэн"}, [26]={npc="Нафиэн", tgt="Нафиэн"}, [27]={hint="Нафиэн просит вас убить 6 дозорных, 6 мстителей и 6 шаманов из племени Мертвого Леса. По выполнении возвращайтесь на север Оскверненного леса ко входу в крепость Древобрюхов."}, [28]={npc="Нафиэн", tgt="Нафиэн"}, [29]={npc="Нафиэн", tgt="Нафиэн", desc="Сдайте его Сальфе, когда пройдёте через Крепость Древобрюхов в Зимние Ключи."}, [30]={text="Войдите здесь в пещеру Крепости Древобрюхов и пройдите ее насквозь — это Зимние Ключи."}, [31]={node="Лунная поляна", desc="В пещере Крепости Древобрюхов есть ответвление в Лунной поляне; сначала зайдите туда и откройте пункт полета, затем вернитесь в пещеру и идите в Зимние Ключи. Для части на Хиджале позже вы полетите в Лунную поляну."}, [32]={npc="Сальфа", tgt="Сальфа"}, [33]={npc="Сальфа", tgt="Сальфа"}, [34]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [35]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [36]={npc="Мегги Молот-Шмолот", tgt="Мегги Молот-Шмолот"}, [37]={npc="Джессика Редпат", tgt="Джессика Редпат"}, [38]={nodeA="{a:2255}", node="Everlook"}, [39]={npc="Ниби Всемогущий", tgt="Ниби Всемогущий"}, [40]={npc="Бесенок", tgt="Бесенок"}, [41]={npc="Бесенок", tgt="Бесенок", desc="«Ткань Скверны» ×1 можно купить на аукционе."}, [42]={hint="Принесите отрез ткани Скверны Бесенку в Оскверненный лес."}, [43]={npc="Бесенок", tgt="Бесенок"}, [44]={npc="Бесенок", tgt="Бесенок"}, [45]={hint="Принесите 10 кусков гнилой древесины и 4 порции экстракта ядовитой крови Бесенку в Оскверненный лес."}, [46]={npc="Бесенок", tgt="Бесенок"}, [47]={npc="Бесенок", tgt="Бесенок", tag="Делайте с группой, Необязательно"}, [48]={hint="Принесите 6 вудуистских перьев троллей из затонувшего храма.", tag="Делайте с группой, Необязательно"}, [49]={npc="Бесенок", tgt="Бесенок", tag="Делайте с группой, Необязательно"}, [50]={npc="Бесенок", tgt="Бесенок"}, [51]={hint="Бесенок из Оскверненного леса просит вас принести ему три порции безупречной субстанции скверны из трех различных мест."}, [52]={npc="Бесенок", tgt="Бесенок"}, [53]={npc="Бесенок", tgt="Бесенок", desc="Крошиус находится на севере Оскверненного леса. Нужна группа."}, [54]={hint="Обыщите долину Рваных Ран в Оскверненном лесу и найдите останки Крошиуса. Когда вы их найдете, поднесите к ним пламень Скверны и подождать, пока Крошиус не восстанет из праха. Когда инфернал очнется, убейте его и возьмите из его тела огненное ядро Крошиуса.", desc="Крошиус находится на севере Оскверненного леса. Нужна группа."}, [55]={npc="Ниби Всемогущий", tgt="Ниби Всемогущий", desc="Крошиус находится на севере Оскверненного леса. Нужна группа."}}},
    ["05-d14"] = {name="Храм Атал'Хаккар", entrance="Болото Печали 69.50, 52.50 (внешний ориентир у здания храма)", steps={[1]={npc="Ангелас Лунный Бриз", tgt="Ангелас Лунный Бриз", tag="Подготовка к подземелью"}, [2]={npc="Марвон Клепальщик", tgt="Марвон Клепальщик", tag="Подготовка к подземелью"}, [3]={npc="Марвон Клепальщик", tgt="Марвон Клепальщик", tag="Подготовка к подземелью"}, [4]={hint="Заберите круглый камень из мастерской Марвона Клепальщика в Кабестане.", tag="Подготовка к подземелью"}, [5]={npc="Марвон Клепальщик", tgt="Марвон Клепальщик", tag="Подготовка к подземелью"}, [6]={npc="Марвон Клепальщик", tgt="Марвон Клепальщик", preText="Круглый камень"}, [7]={npc="Марвон Клепальщик", tgt="Марвон Клепальщик", preText="Круглый камень"}, [8]={npc="Йе'кинья", tgt="Йе'кинья", tag="Подготовка к подземелью"}, [9]={hint="Поймайте души трех крикунов из Фераласа и возвращайтесь к Йе'кинье в Порт Картеля.", tag="Подготовка к подземелью", desc="Убивайте дольных визгунов на побережье Острова Ужаса в Фераласе. Используйте колючку Йе'кинья на каждом трупе и поговорите с появившимся духом. Повторяйте, пока в журнале не будет трёх духов."}, [10]={npc="Йе'кинья", tgt="Йе'кинья", tag="Подготовка к подземелью"}, [11]={npc="Йе'кинья", tgt="Йе'кинья", tag="Подготовка к подземелью"}, [12]={hint="Принесите первую и вторую таблички Мошару Йе'кинье в Танарис.", tag="Подготовка к подземелью"}, [13]={npc="Йе'кинья", tgt="Йе'кинья", tag="Подготовка к подземелью"}, [14]={npc="Йе'кинья", tgt="Йе'кинья", tag="Подготовка к подземелью"}, [15]={hint="Принесите древнее яйцо Йе'кинье в Танарис.", tag="Подготовка к подземелью"}, [16]={npc="Йе'кинья", tgt="Йе'кинья", tag="Подготовка к подземелью"}, [17]={npc="Йе'кинья", tgt="Йе'кинья", preText="Древнее яйцо"}, [18]={npc="Верховный маг Ксилем", tgt="Верховный маг Ксилем", tag="Подготовка к подземелью"}, [19]={hint="Принесите 10 горстей сияющей пыли верховному магу Ксилему.", tag="Подготовка к подземелью"}, [20]={npc="Верховный маг Ксилем", tgt="