[41]={npc="Огтинк", tgt="Огтинк", tag="Подготовка к подземелью"}, [42]={npc="Огтинк", tgt="Огтинк", tag="Необязательно", desc="Зеленый дракон находится в Храме Атал'Хаккара."}, [43]={text="Вход: Храм Атал'Хаккар"}, [44]={hint="Найдите алтарь Хаккара в затонувшем храме на Болоте Печали.", desc="Место: Войдя, идите вниз по ровной дороге справа и найдите на кольцевом зале алтарь Хаккара.", spot="Войдя, идите вниз по ровной дороге справа и найдите на кольцевом зале алтарь Хаккара."}, [45]={npc="Алтарь Хаккара", npcObj=true, spot="Алтарь Хаккара в кольцевом коридоре нижнего уровня"}, [46]={hint="Отправляйтесь в затонувший храм и узнайте, что скрывается в круге статуй.", desc="Неверный порядок запускает ловушку. Место: В нижнем кольцевом коридоре по порядку нажмите на шесть статуй, затем идите в центр убивать босса. Порядок: Юг → север → юго-запад → юго-восток → северо-запад → северо-восток.", spot="Активируйте шесть статуй в нижнем кольцевом зале по порядку, затем убейте босса в центре."}, [47]={npc="Идол Хаккара", npcObj=true, spot="Центр нижнего уровня: статуя Хаккара"}, [48]={hint="Отнесите заполненное яйцо Хаккара Йе'кинье в Танарис.", desc="Сначала войдите в комнату всей группой, затем запускайте событие. По западному проходу идите в комнату Хаккара. Место: От Ямы Жертвоприношений по западному коридору идите в комнату Хаккара, соберитесь и используйте яйцо. Порядок: Западный коридор ведет к Хаккару, восточный — к Джаммал'ану.", spot="От Ямы Жертвоприношений идите по западному коридору в комнату Хаккара; соберитесь всей группой и используйте яйцо."}, [49]={hint="Добудьте кристалл тайной магии из брюха Морфаза и принесите его верховному магу Ксилему.", tag="Необязательно"}, [50]={hint="Убейте Морфаза в затонувшем храме Атал'Хаккара и принесите его кровь Грете Замшелому Копыту в Оскверненный лес. Вход в храм сокрыт на болоте Печали.", tag="Необязательно"}, [51]={hint="Принесите зуб Морфаза Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.", tag="Необязательно"}, [52]={npc="Сущность Эраникуса", npcObj=true, tag="Необязательно, Делайте с группой", desc="Победите последнего босса и щёлкните правой кнопкой по подобранной вами сущности, чтобы начать задание."}, [53]={hint="Поместите сущность Эраникуса в купель сущности в его логове в затонувшем храме.", tag="Необязательно, Делайте с группой", spot="Поместите сущность в купель рядом с последним боссом."}, [54]={npc="Купель сущности", npcObj=true, tag="Необязательно, Делайте с группой", spot="Поместите сущность в купель рядом с последним боссом."}, [55]={npc="Йе'кинья", tgt="Йе'кинья"}, [56]={npc="Верховный маг Ксилем", tgt="Верховный маг Ксилем", tag="Необязательно", desc="Морфаз находится в Храме Атал'Хаккара."}, [57]={npc="Огтинк", tgt="Огтинк", tag="Необязательно", desc="Зеленый дракон находится в Храме Атал'Хаккара."}, [58]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто", tag="Необязательно, Требуются материалы"}}},
    ["04-50"] = {steps={[1]={to="Feathermoon Stronghold", toA="{a:1116}"}, [2]={npc="Пратт Макгруббен", tgt="Пратт Макгруббен"}, [3]={npc="Трояс Лунный Бриз", tgt="Трояс Лунный Бриз"}, [4]={npc="Трояс Лунный Бриз", tgt="Трояс Лунный Бриз"}, [5]={npc="Греган Пивоплюй", tgt="Греган Пивоплюй"}, [6]={hint="Найдите Грегана Пивоплюя на севере Фераласа. Выясните у него, как получить эликсир Видере, и вернитесь к Донове Снегоноре.", desc="Греган дает приманку: отвлеките ею Миблона, подберите Корень вечерника и вернитесь обменять его на Эликсир Видере."}, [7]={npc="Камнедробитель", tgt="Камнедробитель"}, [8]={hint="Зарядите посох Трояса и отыщите Монолит Равноденствия.", desc="Дальше можно запрыгнуть наверх и срезать путь."}, [9]={npc="Монолит Равноденствия", npcObj=true, desc="Используйте посох из сумки."}, [10]={npc="Монолит Равноденствия", npcObj=true}, [11]={npc="Шая Листогон", tgt="Шая Листогон"}, [12]={npc="Шая Листогон", tgt="Шая Листогон", tag="Эскорт"}, [13]={hint="Достаньте из сундучка колокольчик Шай.", tag="Эскорт"}, [14]={npc="Камнедробитель", tgt="Камнедробитель"}, [15]={hint="Принесите 10 шкур йети из пещеры Бешеного оврага Пратту Макгруббену в Крепость Оперенной Луны в Фераласе."}, [16]={npc="Нетронутая шкура йети", npcObj=true, tag="Необязательно", desc="Если с йети выпадет «Нетронутая шкура йети», щелкните по ней правой кнопкой."}, [17]={npc="Пратт Макгруббен", tgt="Пратт Макгруббен"}, [18]={npc="Пратт Макгруббен", tgt="Пратт Макгруббен", tag="Необязательно"}, [19]={npc="Трояс Лунный Бриз", tgt="Трояс Лунный Бриз"}}},
    ["04-51"] = {grind={[1]={mob="Землепроходец из племени Зимней Спячки", note="Лагерь фурболгов племени Зимней Спячки к северу от Доновы; те же мобы, что и для задания на фурболгов."}, [2]={mob="Тотемист из племени Зимней Спячки", note="Тот же лагерь; заклинатели."}}, steps={[1]={bindA="{a:415}", desc="Если камень возвращения на перезарядке, летите из Крепости Оперенной Луны в Астранаар (с пересадкой в Аубердине), а затем идите на север в Оскверненный лес."}, [2]={npc="Аратандис Серебряное Небо", tgt="Аратандис Серебряное Небо"}, [3]={npc="Аратандис Серебряное Небо", tgt="Аратандис Серебряное Небо"}, [4]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто"}, [5]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто", tag="Делайте с группой, Необязательно, Требуются материалы"}, [6]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто"}, [7]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [8]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [9]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [10]={npc="Тарун Красное Перо", tgt="Тарун Красное Перо"}, [11]={hint="Добыча с: Проклятый слизнюк, Нечистый слизнюк, Злобный слизнюк", desc="Падают, только пока в сумках лежит Маяк Кенария; железноклювы водятся к западу от святилища, слизнюки — у водоемов на северо-западе."}, [12]={npc="Аратандис Серебряное Небо", tgt="Аратандис Серебряное Небо"}, [13]={npc="Донова Снегонора", tgt="Донова Снегонора", desc="Вернитесь в Астранаар, летите на Поляну Когтистых Ветвей, а затем идите на север через Крепость Древобрюхов в Зимние Ключи."}, [14]={npc="Донова Снегонора", tgt="Донова Снегонора", desc="Выпейте Эликсир Видере на кладбище у Прибамбасска и найдите Гаэриана в облике духа."}, [15]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [16]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [17]={desc="Убивайте фурболгов около 32, 36 в лагере Зимней Спячки."}, [18]={npc="Грегор Грейстоун", tgt="Грегор Грейстоун"}, [19]={npc="Грегор Грейстоун", tgt="Грегор Грейстоун"}, [20]={to="Ratchet", toA="{a:392}", desc="Вы сделаете пересадку на Заставе Талрендис."}, [21]={npc="Лив Быстрочин", tgt="Лив Быстрочин"}, [22]={npc="Ислен Заклинатель Воды", tgt="Ислен Заклинатель Воды"}, [23]={npc="Ислен Заклинатель Воды", tgt="Ислен Заклинатель Воды"}, [24]={to="Gadgetzan", toA="{a:976}"}, [25]={npc="Алхимик Пестычинс", tgt="Алхимик Пестычинс"}, [26]={text="Выпив эликсир Видере, не воскресайте: найдите NPC задания в виде духа."}, [27]={npc="Гаэриан", tgt="Гаэриан"}, [28]={npc="Гаэриан", tgt="Гаэриан"}, [29]={text="Вернитесь к телу и воскресните."}, [30]={npc="Подозрительное надгробие", npcObj=true}, [31]={npc="Подозрительное надгробие", npcObj=true}, [32]={npc="Тран'рек", tgt="Тран'рек"}, [33]={npc="Алхимик Пестычинс", tgt="Алхимик Пестычинс", tag="Необязательно"}}},
    ["04-52"] = {name="Кратер Ун'Горо", steps={[1]={to="Marshal's Refuge", toA="{a:541}"}, [2]={npc="Линкен", tgt="Линкен"}, [3]={npc="Линкен", tgt="Линкен"}, [4]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [5]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [6]={npc="Муча Кусора", tgt="Муча Кусора"}, [7]={npc="Холания Маршал", tgt="Холания Маршал", tag="Необязательно, If offered", desc="Задание на доставку книги: берите, если НИП его предлагает. Отнесите книгу на Вершину Вечности на Хиджал и сдайте. Если задания не видно, пока пропустите."}, [8]={hint="Отнесите 12 образцов сверхлипкой смолы Тран'реку в Прибамбасск."}, [9]={npc="Кракл", tgt="Кракл"}, [10]={hint="Добудьте 9 образцов пепла Ун'Горо из элементалей огня, что водятся вокруг вулкана в Кратере Ун'Горо, и доставьте их Лив Быстрочин в Кабестан."}, [11]={hint="Выясните, где находится точка самой высокой температуры на Вулкане Огненного Венца, по просьбе Кракла из Кратера Ун'Горо.", desc="Поднимитесь по тропе на Вулкан Огненного Венца и измерьте температуру. Если вы взяли задание на пепел, соберите его по пути. Сняв показания, идите по тропе к Ринго. Начав сопровождение, ведите его прямо на север в Укрытие Маршалла."}, [12]={npc="Ринго", tgt="Ринго", desc="Задание на сопровождение: в группе берите, когда у всех одинаковый прогресс, и отключите автопринятие."}, [13]={npc="Ринго", tgt="Ринго"}, [14]={hint="Отведите Ринго к Муче Кусора в Укрытие Маршалла.", tag="Эскорт", desc="Приведите Ринго обратно в Укрытие Маршалла. Он потеряет сознание по пути; когда это случится, используйте на нем флягу Спрэггл."}, [15]={npc="Муча Кусора", tgt="Муча Кусора"}, [16]={npc="Чи-Та 3", tgt="Чи-Та 3"}, [17]={npc="Чи-Та 3", tgt="Чи-Та 3"}, [18]={hint="Найдите мифриловую обшивку и вернитесь к Чи-Та 3 в Кратер Ун'Горо.", desc="Купите мифриловый корпус заранее на аукционе или попросите инженера его сделать."}, [19]={npc="Чи-Та 3", tgt="Чи-Та 3"}, [20]={hint="Принесите шкуру Учи землепроходцу Торве ко входу в Кратер Ун'Горо."}, [21]={npc="Чи-Та 3", tgt="Чи-Та 3"}, [22]={hint="Доставьте Чи-Та 3 назад Карне Сомнамбулер в Кратер Ун'Горо.", tag="Эскорт", desc="Сопроводите Чи-Та 3 обратно к Карна Сомнамбулер; монстры по пути нападают на него, защищайте его."}, [23]={npc="Карна Сомнамбулер", tgt="Карна Сомнамбулер"}, [24]={hint="Соберите по 7 кристаллов Силы каждого цвета: красных, синих, желтых и голубых. Принесите их Джей Ди Колли в Укрытие Маршалла.", desc="Кристаллы четырех цветов разбросаны по земле по всему кратеру; доберите те, которых раньше не хватило."}, [25]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [26]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [27]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [28]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [29]={hint="Отыщите Северный хрустальный пилон в Кратере Ун'Горо."}, [30]={hint="Отыщите Восточный хрустальный пилон в Кратере Ун'Горо."}, [31]={hint="Принесите ароматическую железу Гориши и 5 образцов почвы из Кратера Ун'Горо алхимику Пестычинсу в Прибамбасск.", tag="Необязательно", desc="Ищите ос или рабочих Гориши у южного улья, чтобы добыть железу. По пути соберите пять порций почвы из куч земли. В одиночку выманивайте отдельных насекомых, не углубляясь за королевой."}, [32]={hint="Принесите ароматическую железу Гориши и 5 образцов почвы из Кратера Ун'Горо алхимику Пестычинсу в Прибамбасск.", tag="Необязательно", desc="Ищите ос или рабочих Гориши у южного улья, чтобы добыть железу. По пути соберите пять порций почвы из куч земли. В одиночку выманивайте отдельных насекомых, не углубляясь за королевой."}, [33]={hint="Отыщите Западный хрустальный пилон."}, [34]={npc="Кракл", tgt="Кракл"}, [35]={npc="Кракл", tgt="Кракл"}, [36]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [37]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [38]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [39]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [40]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [41]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [42]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [43]={hint="Соберите 8 кровошляпочников и 8 жал Гориши и вернитесь к Землепроходцу Торве в Кратер Ун'Горо."}, [44]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [45]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [46]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [47]={npc="Землепроходец Торва", tgt="Землепроходец Торва", tag="Делайте с группой, Необязательно"}, [48]={hint="Возьмите гнилую лозу у стража на дне затонувшего храма и вернитесь к Землепроходцу Торве.", tag="Делайте с группой, Необязательно"}, [49]={npc="Землепроходец Торва", tgt="Землепроходец Торва", tag="Делайте с группой, Необязательно"}, [50]={text="Если вы ещё на севере и вам не нужно к Торве, откройте карту полётов в Укрытии Маршалла и летите в Прибамбасск, если он доступен. Чтобы сдать шкуру Учи или выполнить задания друида у Торвы, сначала навестите его на юго-востоке. От Торвы или если полёт недоступен поднимитесь по юго-восточному склону в Танарис, затем идите на северо-восток до Прибамбасска."}, [51]={npc="Тран'рек", tgt="Тран'рек"}, [52]={npc="Алхимик Пестычинс", tgt="Алхимик Пестычинс", tag="Необязательно"}, [53]={to="Ratchet", toA="{a:392}", desc="Вы сделаете пересадку в Тераморе."}, [54]={npc="Лив Быстрочин", tgt="Лив Быстрочин"}, [55]={bindA="{a:415}"}, [56]={to="Аубердин"}, [57]={text="В таверне Аубердина привяжите камень возвращения (Хозяйка таверны Шосси) (37.04, 44.13).", bind="Аубердин"}, [58]={to="Rut'theran Village", toA="{a:702}"}, [59]={npc="Эрелас Янтарное Небо", tgt="Эрелас Янтарное Небо"}, [60]={text="Пройдите через портал в Деревне Рут'теран в Дарнас."}, [61]={hint="Отправляйтесь в Дарнасс и наберите в фиал Эриданы благословенной воды из храма Луны. Возвращайтесь к Эридане с полным фиалом."}, [62]={text="Пройдите через портал в Дарнасе обратно в Деревню Рут'теран."}, [63]={to="Astranaar", toA="{a:415}"}, [64]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто"}, [65]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто", tag="Необязательно, If offered", desc="Задание на доставку письма: берите, если НИП его предлагает. Отнесите на Хиджал и сдайте отшельнику Ketharas. Если задания не видно, пока пропустите."}, [66]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [67]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [68]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [69]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [70]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [71]={hint="Добудьте 11 серебристых когтей и 1 сердце Железнолесья для Эриданы Грусти Ветра.", tag="Необязательно", desc="Отдельный крюк, других целей рядом нет. Если торопитесь, пропустите."}, [72]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра", tag="Необязательно"}, [73]={text="Из Изумрудного святилища идите по дороге на юг обратно в Астранаар и летите в Аубердин. Камень возвращения вы только что использовали в Кабестане, так что он, скорее всего, еще на перезарядке; если уже готов, сразу возвращайтесь в Аубердин."}, [74]={to="Menethil Harbor", toA="{a:150}", from="Аубердин", desc="В Аубердине сядьте на корабль до Гавани Менетилов и сойдите на следующей остановке."}, [75]={to="Стальгорн"}, [76]={npc="Историк Карник", tgt="Историк Карник"}, [77]={npc="Историк Карник", tgt="Историк Карник"}, [78]={npc="Старший исследователь Магеллас", tgt="Старший исследователь Магеллас"}, [79]={npc="Старший исследователь Магеллас", tgt="Старший исследователь Магеллас"}, [80]={npc="Королевский историк Аркессон", tgt="Королевский историк Аркессон"}, [81]={npc="Королевский историк Аркессон", tgt="Королевский историк Аркессон"}, [82]={npc="Королевский историк Аркессон", tgt="Королевский историк Аркессон"}}},
    ["05-d11"] = {name="Глубины Черной Горы", entrance="Тлеющее ущелье 34.80, 85.30", pickup="По основному маршруту соберите группу в Стальгорне после второго посещения Ун'Горо. Следующая остановка — Пылающие степи. Если группа найдётся раньше, в Тлеющем ущелье, входите в Чёрную гору с южного конца ущелья.", pickupS={{"По основному маршруту соберите группу в Стальгорне после второго посещения Ун'Горо"}, {"Следующая остановка — Пылающие степи"}, {"Если группа найдётся раньше, в Тлеющем ущелье, входите в Чёрную гору с южного конца ущелья"}}, tips={{k="動線", text="Из Стальгорна летите на Ториевую заставу и входите в Чёрную гору с южного конца Тлеющего ущелья. Если перелёт недоступен, идите из Дун Морога на восток в Лок Модан, затем на юг в Бесплодные земли. Поверните на запад и обойдите Каргат, чтобы попасть в Тлеющее ущелье. → Если вы нашли группу в Зимних Ключах, летите в Аубердин. Если полёт недоступен, возвращайтесь через Крепость Древобрюхов в Осквернённый лес и идите через Ясеневый лес в Аубердин на Тёмных берегах. Плывите на корабле в Штормград и летите на Ториевую заставу. Если в Восточных королевствах не открыты полётные точки, идите из Штормграда через Элвиннский лес в Красногорье. Из Приозерья следуйте по северной дороге в Пылающие степи и поверните на запад к Чёрной горе. → Чтобы продолжить путь по Пылающим степям, выходите из Чёрной горы через южные ворота и следуйте по дороге на восток до Дозора Моргана. → Чтобы вернуться в Крепость Оперенной Луны, используйте камень возвращения, если он готов и привязан к Астранаару. Иначе идите из Пылающих степей через Красногорье и Элвиннский лес в порт Штормграда. Плывите в Аубердин и летите в Крепость Оперенной Луны. Если перелёт недоступен, пройдите из Ясеневого леса через Когтистые горы и Пустоши в Фералас. На западном побережье сядьте на корабль до острова."}}, steps={[1]={npc="Франклорн Искусник", tgt="Франклорн Искусник", desc="Найдите Франклорна в Чёрной горе в облике призрака. Возьмите и сдайте первую часть, затем возьмите вторую и только после этого воскресайте. Пути к горе описаны на этой странице."}, [2]={npc="Франклорн Искусник", tgt="Франклорн Искусник"}, [3]={npc="Франклорн Искусник", tgt="Франклорн Искусник"}, [4]={text="Вход: Глубины Черной Горы"}, [5]={hint="Убейте Точеня Темностроя и добудьте великий молот, Железный Друг. Отнесите Железного Друга в святилище Тауриссана и вложите его в руки статуи Франклорна Искусника."}, [6]={npc="Монумент Франклорну Искуснику", npcObj=true, desc="Сдайте здесь задание «Наследие Черного Железа». Для продолжения пути по Пылающим степям выходите через южные ворота Чёрной горы. Чтобы вернуться в Калимдор, следуйте указаниям на этой странице для корабля или камня возвращения."}}},
    ["04-54"] = {steps={[1]={text="Если Дозор Моргана открыт, летите туда прямо из Стальгорна. Если нет, летите в Приозерье и идите по дороге на север в Пылающие степи; Дозор Моргана находится прямо у входа.", tag="Маршрут полета еще не открыт. В первый раз доберитесь туда пешком."}, [2]={nodeA="{a:2418}", node="Morgan's Vigil"}, [3]={npc="Орелиус", tgt="Орелиус"}, [4]={npc="Орелиус", tgt="Орелиус"}, [5]={npc="Хелендис Речной Мыс", tgt="Хелендис Речной Мыс", tag="Делайте с группой, Необязательно"}, [6]={npc="Тинки Кипеллер", tgt="Тинки Кипеллер"}, [7]={npc="Максворт Суперблеск", tgt="Максворт Суперблеск"}, [8]={hint="Пойдите в руины Тауриссана в Пылающих степях и добудьте информацию из таурисанских реликвий. Вернитесь к королевскому историку Аркессону."}, [9]={hint="Принесите переписанный с таблички текст Максворту Суперблеску в Пылающие степи."}, [10]={hint="Убейте 15 огров-магов, 7 огров и 7 громил из клана Огненного Чрева. По выполнении задания вернитесь к Орелиусу."}, [11]={hint="Принесите 8 сущностей детенышей драконов и Драко-инкарцинатор 900 Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях."}, [12]={hint="Убейте 15 детенышей черного дракона, 10 черных драконидов, 4 черных драконид и 1 черного дракона. По выполнении задания вернитесь к Хелендису Речному Мысу.", tag="Делайте с группой, Необязательно", desc="Черные дракониды и драконы — элитные противники 51-53 уровня."}, [13]={npc="Цирус Раскаиватель", tgt="Цирус Раскаиватель"}, [14]={npc="Цирус Раскаиватель", tgt="Цирус Раскаиватель"}, [15]={npc="Тинки Кипеллер", tgt="Тинки Кипеллер"}, [16]={npc="Максворт Суперблеск", tgt="Максворт Суперблеск"}, [17]={npc="Орелиус", tgt="Орелиус"}, [18]={npc="Орелиус", tgt="Орелиус"}, [19]={npc="Хелендис Речной Мыс", tgt="Хелендис Речной Мыс", tag="Делайте с группой, Необязательно"}, [20]={npc="Хелендис Речной Мыс", tgt="Хелендис Речной Мыс"}, [21]={hint="Найдите Гор'теша на западе от скалы Молота Ужаса. Убейте Гор'теша и отнесите его голову Орелиусу в Пылающие степи."}, [22]={hint="Орелиусу нужны 50 медальонов Черной горы. Скорее всего их можно найти у орков Пылающих степях."}, [23]={npc="Орелиус", tgt="Орелиус"}, [24]={npc="Орелиус", tgt="Орелиус"}, [25]={to="Lakeshire", toA="{a:69}", desc="Если вы не выполняете «Подлинные хозяева», летите прямо в Штормград и пропустите следующие два шага."}, [26]={npc="Мировой судья Соломон", tgt="Мировой судья Соломон"}, [27]={npc="Мировой судья Соломон", tgt="Мировой судья Соломон"}, [28]={to="Stormwind"}, [29]={npc="Ву Шен", tgt="Ву Шен", tag="Необязательно"}, [31]={npc="Лорд Грейсон Тенелом", tgt="Лорд Грейсон Тенелом", desc="Сдайте в лагере Промозглого Ветра в Западных Чумных землях."}, [33]={npc="Верховный лорд Болвар Фордрагон", tgt="Верховный лорд Болвар Фордрагон"}, [34]={npc="Верховный лорд Болвар Фордрагон", tgt="Верховный лорд Болвар Фордрагон"}, [35]={npc="Верховный лорд Болвар Фордрагон", tgt="Верховный лорд Болвар Фордрагон"}, [36]={npc="Верховный лорд Болвар Фордрагон", tgt="Верховный лорд Болвар Фордрагон"}, [37]={npc="Глашатай Гудман", tgt="Глашатай Гудман"}, [38]={npc="Павший герой Орды", tgt="Павший герой Орды", tag="Необязательно"}, [39]={npc="Павший герой Орды", tgt="Павший герой Орды", tag="Необязательно"}, [40]={hint="Убейте 7 Зловепрей в Выжженных землях и вернитесь к павшему герою Орды.", tag="Необязательно"}, [41]={npc="Павший герой Орды", tgt="Павший герой Орды", tag="Необязательно"}, [42]={npc="Павший герой Орды", tgt="Павший герой Орды", tag="Необязательно"}, [43]={hint="Убейте Приверженцев Тени в Выжженных землях и вернитесь к павшему герою Орды.", tag="Необязательно"}, [44]={npc="Павший герой Орды", tgt="Павший герой Орды", tag="Необязательно"}, [45]={npc="Павший герой Орды", tgt="Павший герой Орды", tag="Делайте с группой, Необязательно"}, [46]={hint="Принесите вудуистские перья павшему герою Орды, забрав их у троллей в Затонувшем Храме.", tag="Делайте с группой, Необязательно"}, [47]={npc="Павший герой Орды", tgt="Павший герой Орды", tag="Делайте с группой, Необязательно"}}},
    ["05-d26"] = {name="Нижняя часть пика Черной горы", entrance="Пылающие степи 1428, 29.40, 38.30 (южный вход в Черную гору).", pickup="Возьми задания в Дозоре Моргана и у Пламенеющего Стяга. Если уровень мал, забери их перед походом. Оружейники могут взять задание на камень Вос'гаджин в Круговзоре.", pickupS={{"Возьми задания в Дозоре Моргана и у Пламенеющего Стяга"}, {"Если уровень мал, забери их перед походом"}, {"Оружейники могут взять задание на камень Вос'гаджин в Круговзоре"}}, tips={{k="動線", text="Общий портал → спуск справа → Омокк → Вос'гаджин и Блестяшка → Вун → Мать Дымная Паутина → Халикон → Змейталак."}, {k="說明", text="Сначала передайте донесение Блестяшки Максвеллу. Задание на трех боссов оставьте на следующий забег. Для верхнего яруса достаточно одного ключа на группу.", s={{"Сначала передайте донесение Блестяшки Максвеллу"}, {"Задание на трех боссов оставьте на следующий забег"}, {"Для верхнего яруса достаточно одного ключа на группу"}}}}, steps={[1]={npc="Хелендис Речной Мыс", tgt="Хелендис Речной Мыс"}, [2]={npc="Киблер", tgt="Киблер"}, [3]={npc="Киблер", tgt="Киблер"}, [4]={npc="Джон-Оборванец", tgt="Джон-Оборванец", tag="Необязательно"}, [5]={npc="Килрам", tgt="Килрам", tag="Необязательно", desc="Бери, если уже куёшь оружие и хочешь освоить изготовление топоров."}, [6]={text="Требуется: Утраченные таблички Мошару", tag="Необязательно"}, [7]={npc="Геолог Железный Башмак", tgt="Геолог Железный Башмак", tag="Необязательно", preText="Утраченные таблички Мошару"}, [8]={text="Вход: Нижняя часть пика Черной горы"}, [9]={npc="Секретный агент из легиона Изрубленного Щита", tgt="Секретный агент из легиона Изрубленного Щита", tag="Необязательно", desc="Спуститесь справа от входа и пройдите по осыпи в боковую комнату к Ваелану."}, [10]={npc="Варош", tgt="Варош", tag="Необязательно", desc="За первым мостом от входа на нижний ярус."}, [11]={hint="Отправляйтесь на Пик Черной горы, убейте Темную охотницу Вос'гаджин. Заберите у нее змеекамень и принесите Килраму.", tag="Необязательно", desc="Место: Пройдите Омокка, идите по проходу и найдите Темную охотницу Вос'гаджин. Порядок: Сначала убейте Вос'гаджин, затем по склону ее комнаты найдите Блестяшку.", spot="Пройдя Омокка, идите по туннелю к охотнице за тенями Вош'гаджин."}, [12]={hint="Принесите пятую и шестую таблички Мошару геологу Железному Башмаку в Танарисе.", tag="Необязательно", desc="Место: По одной табличке возле Вос'гаджин и Вуна.", spot="По одной табличке возле Вос'гаджин и Вуна."}, [13]={npc="Блестяшка", tgt="Блестяшка", desc="Около Вос'гаджин пройдите по склону к Блестяшке."}, [14]={hint="Найдите вещи Блестяшки и верните их владелице. Удачи!", desc="Место: Проход от орков нижнего яруса к паукам.", spot="Проход от орков нижнего яруса к паукам."}, [15]={npc="Блестяшка", tgt="Блестяшка", spot="Блестяшка на склоне рядом с Вос'гаджин."}, [16]={npc="Блестяшка", tgt="Блестяшка", preText="Вещи Блестяшки"}, [17]={hint="Отправьтесь на пик Черной горы и принесите Киблеру 15 яиц скального паука.", desc="Место: Рядом с Матерью Дымной Паутиной. Берегитесь вылупившихся паучков.", spot="Рядом с Матерью Дымной Паутиной. Берегитесь вылупившихся паучков."}, [18]={hint="Найдите в самом сердце пика Черной горы мать Дымную Паутину. Сражайтесь с ней, пока она не введет вам свой яд. Скорее всего ее также придется убить. Когда яд будет в вас, вернитесь к Джону-Оборванцу, чтобы он смог добыть яд.", tag="Необязательно", desc="Место: В глубине паучьего логова.", spot="В глубине паучьего логова."}, [19]={hint="Отправьтесь на пик Черной горы и отыщите там щенков воргов легиона Кровавого Топора. Посадите маленьких тварей в клетку и отнесите Киблеру.", desc="Место: У воргов. Не убивайте щенков.", spot="У воргов. Не убивайте щенков."}, [20]={hint="Отправьтесь на пик Черной горы и уничтожьте источник опасности. Хелендис кричит вам вслед одно имя: Халикон. Именно его упоминали орки в связи с воргами.", desc="Место: У воргов на нижнем ярусе.", spot="У воргов на нижнем ярусе."}, [21]={hint="Прочитайте записку Вароша. Принесите Варошу его амулет.", tag="Необязательно", desc="Место: У груды подношений перед Змейталаком.", spot="У груды подношений перед Змейталаком."}, [22]={npc="Варош", tgt="Варош", tag="Необязательно", spot="Варош за мостом у входа."}, [23]={hint="Отправляйтесь на пик Черной горы и устраните воеводу Вуна, вождя Омокка и повелителя Змейталака. По выполнении задания вернитесь к маршалу Максвеллу.", tag="Необязательно", desc="Место: Убейте всех трех боссов нижнего яруса.", spot="Убейте всех трех боссов нижнего яруса."}, [24]={npc="Распоряжения генерала Драккисата", npcObj=true, tag="Необязательно", desc="Подберите приказ со Змейталака и нажмите ПКМ, чтобы принять задание."}, [25]={hint="Найдите самоцвет Тлеющего Терновника, самоцвет Черной Вершины и самоцвет Кровавого Топора. Верните их Ваелану вместе с простой печатью Вознесения.", tag="Необязательно", desc="Шанс выпадения самоцветов и печатей ограничен, заранее договоритесь с командой о распределении. Если идете только на верхний уровень, достаточно, чтобы один человек в группе имел готовый предмет. Место: с каждого из трех боссов подберите самоцвет, а неукрашенную печать ищите у обычных мобов по пути. Порядок: Омокк → Вун → Вирмталак.", spot="С каждого из трех боссов подберите по самоцвету; Неукрашенную печать ищите у обычных мобов по пути."}, [26]={npc="Секретный агент из легиона Изрубленного Щита", tgt="Секретный агент из легиона Изрубленного Щита", tag="Необязательно"}, [27]={npc="Секретный агент из легиона Изрубленного Щита", tgt="Секретный агент из легиона Изрубленного Щита", tag="Необязательно", preText="Печать Вознесения"}, [28]={npc="Джон-Оборванец", tgt="Джон-Оборванец", tag="Необязательно", desc="После отравления как можно скорее вернитесь к Джону."}, [29]={npc="Киблер", tgt="Киблер"}, [30]={npc="Киблер", tgt="Киблер"}, [31]={npc="Хелендис Речной Мыс", tgt="Хелендис Речной Мыс"}, [32]={npc="Килрам", tgt="Килрам", tag="Необязательно"}, [33]={npc="Геолог Железный Башмак", tgt="Геолог Железный Башмак", tag="Необязательно"}, [34]={npc="Маршал Максвелл", tgt="Маршал Максвелл"}, [35]={npc="Маршал Максвелл", tgt="Маршал Максвелл", tag="Необязательно"}, [36]={npc="Маршал Максвелл", tgt="Маршал Максвелл", tag="Необязательно", desc="Понадобится еще один забег.", preText="Донесение Максвелла"}, [37]={npc="Маршал Максвелл", tgt="Маршал Максвелл", tag="Необязательно"}, [38]={hint="Идите в Драконьи топи в Пылевых топях. Найдите Огнебора и бейте его, не жалея, чтобы сломить его волю.", tag="Необязательно", desc="Элитный моб: лучше идти группой. Перед управлением драконом прекратите наносить урон и оставьте достаточно здоровья."}, [39]={npc="Секретный агент из легиона Изрубленного Щита", tgt="Секретный агент из легиона Изрубленного Щита", tag="Необязательно", desc="Найдите Ваэлана внутри входа в Нижнюю часть пика Черной горы."}}},
    ["05-d25"] = {name="Забытый Город: Север", entrance="Фералас (1444), 62.50, 24.90. Портал северного крыла.", pickup="Из Крепости Оперенной Луны идите на север Фераласа. Убедитесь, что у группы есть Серповидный ключ. Для дани можно заранее взять Масло льда, Ториевое устройство, Рулон рунной ткани, Грубую кожу и Руническую нить.", pickupS={{"Из Крепости Оперенной Луны идите на север Фераласа"}, {"Убедитесь, что у группы есть Серповидный ключ"}, {"Для дани можно заранее взять Масло льда, Ториевое устройство, Рулон рунной ткани, Грубую кожу и Руническую нить"}}, tips={{k="動線", text="Северный вход → двор Фенгуса → Уззл и ловушка → Давигром → Король Гордок. Для дани оставьте стражников в живых, а после короля поговорите с Кригом и Давигромом."}, {k="說明", text="Если не выполнены условия дани или Давигром мертв, пропустите Неоконченное дело Гордоков. Классовые книги и манускрипты сдавайте в библиотеке.", s={{"Если не выполнены условия дани или Давигром мертв, пропустите Неоконченное дело Гордоков"}, {"Классовые книги и манускрипты сдавайте в библиотеке"}}}}, steps={[1]={text="Вход: Забытый Город: Север"}, [2]={npc="Сломанная ловушка", npcObj=true, tag="Необязательно"}, [3]={hint="Добыча с: Маршал из клана Ярости Горна, Драконид Яростного Когтя, Железный страж легиона Чернорука", tag="Необязательно", desc="Место: Пройдите двор Фенгуса и найдите ловушку рядом с Уззлом.", spot="Пройдите двор Фенгуса и найдите ловушку рядом с Уззлом."}, [4]={npc="Сломанная ловушка", npcObj=true, tag="Необязательно"}, [5]={npc="Уззл Наперстяк", tgt="Уззл Наперстяк", tag="Необязательно"}, [6]={hint="Принесите 4 рулона рунной ткани, 8 кусков прочной кожи, 2 мотка рунной нити и огрскую дубильную кислоту Уззлу Наперстяку. Он прикован в секторе Гордока в Забытом Городе.", tag="Необязательно", desc="Место: Пройдя Фенгуса, поднимитесь наверх и подберите танин, затем найдите Узла возле ловушки.", spot="Пройдя Фенгуса, поднимитесь наверх и подберите танин, затем найдите Узла возле ловушки."}, [7]={npc="Уззл Наперстяк", tgt="Уззл Наперстяк", tag="Необязательно", spot="За Фенгусом, у ловушки: Нотт"}, [8]={npc="Уззл Наперстяк", tgt="Уззл Наперстяк", tag="Необязательно"}, [9]={hint="Добыча с: Громила из клана Гордок, Маг-лорд из клана Гордок, Капитан из клана Гордок", tag="Необязательно", desc="Место: Пройдя двор Фенгуса, у сломанной ловушки используйте ключ, чтобы освободить Узла.", spot="Пройдя двор Фенгуса, у сломанной ловушки используйте ключ, чтобы освободить Узла."}, [10]={npc="Уззл Наперстяк", tgt="Уззл Наперстяк", tag="Необязательно", spot="Двор Фенгуса, у сломанной ловушки: Нотт"}, [11]={npc="Топотун Криг", tgt="Топотун Криг", tag="Необязательно", desc="После прохождения по пути дани и получения статуса короля найдите Крига."}, [12]={npc="Топотун Криг", tgt="Топотун Криг", tag="Необязательно"}, [13]={npc="Капитан Давигром", tgt="Капитан Давигром", tag="Необязательно", desc="После забега за данью поговорите с Давигромом, если он жив."}, [14]={npc="Капитан Давигром", tgt="Капитан Давигром", tag="Необязательно", desc="В следующий забег за данью на севере оставьте Давигрома в живых, чтобы сдать задание."}, [15]={npc="Гарона: Исследование скрытности и предательства", npcObj=true, tag="Необязательно", desc="Книги выпадают с боссов или находятся в стопках книг. Подберите книгу своего класса и нажмите ПКМ, чтобы принять задание."}, [16]={npc="Сказитель Килдрат", tgt="Сказитель Килдрат", tag="Необязательно", desc="Войдите в библиотеку через боковую дверь во дворе северного входа."}, [17]={npc="Кодекс Защиты", npcObj=true, tag="Необязательно", desc="Книги выпадают с боссов или находятся в стопках книг. Подберите книгу своего класса и нажмите ПКМ, чтобы принять задание."}, [18]={npc="Сказитель Килдрат", tgt="Сказитель Килдрат", tag="Необязательно", desc="Войдите в библиотеку через боковую дверь во дворе северного входа."}, [19]={npc="Поваренная книга чародея", npcObj=true, tag="Необязательно", desc="Книги выпадают с боссов или находятся в стопках книг. Подберите книгу своего класса и нажмите ПКМ, чтобы принять задание."}, [20]={npc="Сказитель Килдрат", tgt="Сказитель Килдрат", tag="Необязательно", desc="Войдите в библиотеку через боковую дверь во дворе северного входа."}, [21]={npc="Свет и как его раскачать", npcObj=true, tag="Необязательно", desc="Книги выпадают с боссов или находятся в стопках книг. Подберите книгу своего класса и нажмите ПКМ, чтобы принять задание."}, [22]={npc="Сказительница Микос", tgt="Сказительница Микос", tag="Необязательно", desc="Войдите в библиотеку через боковую дверь во дворе северного входа."}, [23]={npc="Укрощая тени", npcObj=true, tag="Необязательно", desc="Книги выпадают с боссов или находятся в стопках книг. Подберите книгу своего класса и нажмите ПКМ, чтобы принять задание."}, [24]={npc="Сказительница Микос", tgt="Сказительница Микос", tag="Необязательно", desc="Войдите в библиотеку через боковую дверь во дворе северного входа."}, [25]={npc="Величайшая гонка охотников", npcObj=true, tag="Необязательно", desc="Книги выпадают с боссов или находятся в стопках книг. Подберите книгу своего класса и нажмите ПКМ, чтобы принять задание."}, [26]={npc="Сказительница Микос", tgt="Сказительница Микос", tag="Необязательно", desc="Войдите в библиотеку через боковую дверь во дворе северного входа."}, [27]={npc="Святая Болонья: О чем не говорит свет", npcObj=true, tag="Необязательно", desc="Книги выпадают с боссов или находятся в стопках книг. Подберите книгу своего класса и нажмите ПКМ, чтобы принять задание."}, [28]={npc="Сказитель Явон", tgt="Сказитель Явон", tag="Необязательно", desc="Войдите в библиотеку через боковую дверь во дворе северного входа."}, [29]={npc="Ледяной шок и вы", npcObj=true, tag="Необязательно", desc="Книги выпадают с боссов или находятся в стопках книг. Подберите книгу своего класса и нажмите ПКМ, чтобы принять задание."}, [30]={npc="Сказитель Явон", tgt="Сказитель Явон", tag="Необязательно", desc="Войдите в библиотеку через боковую дверь во дворе северного входа."}, [31]={npc="Изумрудный Сон", npcObj=true, tag="Необязательно", desc="Книги выпадают с боссов или находятся в стопках книг. Подберите книгу своего класса и нажмите ПКМ, чтобы принять задание."}, [32]={npc="Сказитель Явон", tgt="Сказитель Явон", tag="Необязательно", desc="Войдите в библиотеку через боковую дверь во дворе северного входа."}, [33]={npc="Справочник Ностро по истреблению драконов", npcObj=true, tag="Необязательно", desc="Книги выпадают с боссов или находятся в стопках книг. Подберите книгу своего класса и нажмите ПКМ, чтобы принять задание."}, [34]={npc="Сказитель Лидрос", tgt="Сказитель Лидрос", tag="Необязательно", desc="Войдите в библиотеку через боковую дверь во дворе северного входа."}, [35]={npc="Сказитель Лидрос", tgt="Сказитель Лидрос", tag="Необязательно", preText="Эльфийские легенды"}, [36]={hint="Принесите сказителю Лидросу в Забытом Городе \"Манускрипт Скорости\", 1 безупречный черный алмаз, 2 больших сияющих осколка и 2 образца крови героев, чтобы получить магический камень стремительности.", tag="Необязательно"}, [37]={npc="Сказитель Лидрос", tgt="Сказитель Лидрос", tag="Необязательно"}, [38]={npc="Сказитель Лидрос", tgt="Сказитель Лидрос", tag="Необязательно", preText="Эльфийские легенды"}, [39]={hint="Принесите сказителю Лидросу в Забытом Городе \"Манускрипт Средоточия\", 1 безупречный черный алмаз, 4 больших сияющих осколка и 2 образца шкуры Тени, чтобы получить магический камень сосредоточения.", tag="Необязательно"}, [40]={npc="Сказитель Лидрос", tgt="Сказитель Лидрос", tag="Необязательно"}, [41]={npc="Сказитель Лидрос", tgt="Сказитель Лидрос", tag="Необязательно", preText="Эльфийские легенды"}, [42]={hint="Принесите сказителю Лидросу в Забытом Городе \"Манускрипт Защиты\", 1 безупречный черный алмаз, 2 больших сияющих осколка и 1 потертый шовный материал поганища, чтобы получить магический камень защиты.", tag="Необязательно"}, [43]={npc="Сказитель Лидрос", tgt="Сказитель Лидрос", tag="Необязательно"}}},
    ["05-d24"] = {name="Забытый Город: Запад", entrance="Фералас 60.30, 30.20 (портал на западной стороне двора)", pickup="С 54-го уровня возьмите «Эльфийские легенды» у Школяра Рунного Шипа в Крепости Оперенной Луны. Для западного и северного крыльев нужен Серповидный ключ с Пузиллина в восточном крыле.", pickupS={{"С 54-го уровня возьмите «Эльфийские легенды» у Школяра Рунного Шипа в Крепости Оперенной Луны"}, {"Для западного и северного крыльев нужен Серповидный ключ с Пузиллина в восточном крыле"}}, tips={{k="動線", text="Западный вход → Тендрис Криводрев → Прародительница Шен'дралар наверху → пять кристальных пилонов → Бессмер'тер → принц Тортелдрин в библиотеке."}, {k="說明", text="Классовые книги можно сдать в библиотеке. Для северного забега за данью сначала возьмите задание у Давигрома, затем откройте сундук принца.", s={{"Классовые книги можно сдать в библиотеке"}, {"Для северного забега за данью сначала возьмите задание у Давигрома, затем откройте сундук принца"}}}}, steps={[1]={npc="Школяр Рунный Шип", tgt="Школяр Рунный Шип"}, [2]={text="Вход: Забытый Город: Запад"}, [3]={npc="Прародительница Шен'дралар", tgt="Прародительница Шен'дралар", desc="В верхней части западного крыла сначала поговорите с Прародительницей Шен'дралар."}, [4]={hint="Перебейте стражей, которые охраняют 5 столпов, снабжающих энергией Тюрьму Бессмер'тера. После того как столпы угаснут, силовое поле, удерживающее Бессмер'тера, рассеется.", desc="Сначала зачистите пять кристальных башен. Место: Зачистите пять башен в саду и на верхнем этаже, пройдите через запертую дверь и убейте Бессмер'тера и принца. Порядок: Пять башен → Бессмер'тер → принц в библиотеке.", spot="Зачистите пять столпов в саду и на верхнем уровне, пройдите через запертую дверь и убейте Иммол'тара и принца."}, [5]={npc="Прародительница Шен'дралар", tgt="Прародительница Шен'дралар", spot="Библиотека: Прародительница Шен'дралар"}, [6]={npc="Прародительница Шен'дралар", tgt="Прародительница Шен'дралар", preText="Древнее безумие"}, [7]={hint="Вернитесь в Читальню и найдите сокровище Шен'дралар. Получите свою награду!", desc="Место: От клетки Иммол'тара пройдите по коридору и найдите сундук под лестницей в Библиотеке.", spot="От клетки Иммол'тара пройдите по коридору и найдите сундук под лестницей в Библиотеке."}, [8]={npc="Сокровище Шен'дралар", npcObj=true, spot="Сундук Шен'дралар под лестницей библиотеки"}, [9]={hint="Отыщите в Забытом Городе Тельмия Сновидца. Вернитесь в крепость Оперенной Луны к исследовательнице Рунический Шип и сообщите ей все, что вам удалось узнать.", desc="Место: От клетки по коридору дойдите до Библиотеки и найдите останки у книжных полок.", spot="От клетки по коридору дойдите до Библиотеки и найдите останки у книжных полок."}, [10]={hint="Добудьте латную рукавицу Мощи Гордока и вернитесь с ней к капитану Давигрому в Забытом Городе.", tag="Необязательно", desc="Место: В библиотеке западного крыла, за принцем.", spot="В библиотеке западного крыла, за принцем."}, [11]={npc="Школяр Рунный Шип", tgt="Школяр Рунный Шип"}}},
    ["05-d23"] = {name="Забытый Город: Восток", entrance="Фералас 1444, 64.80, 30.20 (портал у восточной стены арены).", pickup="На 54-м уровне сначала поговорите с Латроникусом в Крепости Оперенной Луны. По дороге к восточному входу зайдите к Аж'Тордину в павильоне Лорисс. Если уровень ниже, возьмите задания перед сбором группы.", pickupS={{"На 54-м уровне сначала поговорите с Латроникусом в Крепости Оперенной Луны"}, {"По дороге к восточному входу зайдите к Аж'Тордину в павильоне Лорисс"}, {"Если уровень ниже, возьмите задания перед сбором группы"}}, tips={{k="動線", text="Восточный вход → догоните Пузиллина и возьмите ключ → Лефтендрис → Алззин. Магам с заданием на сотворение воды стоит пройти по каналу к Гидротвари."}, {k="說明", text="Восточный вход открыт без ключа. За «Реликварий Чистоты» беритесь, если уже начали цепочку. Для западного и северного крыльев нужен Серповидный ключ с Пузиллина в восточном крыле.", s={{"Восточный вход открыт без ключа"}, {"За «Реликварий Чистоты» беритесь, если уже начали цепочку"}, {"Для западного и северного крыльев нужен Серповидный ключ с Пузиллина в восточном крыле"}}}}, steps={[1]={npc="Латроникус Лунное Копье", tgt="Латроникус Лунное Копье"}, [2]={npc="Аж'Тордин", tgt="Аж'Тордин"}, [3]={npc="Рабин Сатурна", tgt="Рабин Сатурна", tag="Необязательно"}, [4]={hint="Отправляйтесь в Силитус и найдите реликварий Чистоты в руинах деревни Южного Ветра. Если вам удастся его найти, возвращайтесь к Рабину Сатурне в Ночную Гавань в Лунной поляне.", tag="Необязательно"}, [5]={npc="Рабин Сатурна", tgt="Рабин Сатурна", tag="Необязательно"}, [6]={npc="Рабин Сатурна", tgt="Рабин Сатурна", tag="Необязательно", preText="Реликварий Чистоты"}, [7]={npc="Сказитель Лидрос", tgt="Сказитель Лидрос", tag="Необязательно", desc="Войдите в библиотеку через боковую дверь во дворе северного входа."}, [8]={text="Вход: Забытый Город: Восток"}, [9]={hint="Отправляйтесь в Забытый Город и отыщите беса Пузиллина. Любыми доступными средствами убедите Пузиллина отдать вам книгу заклинаний Аж'Тордина.", desc="Поговорите с Пузиллином у восточных ворот и идите за ним по проходу до самого конца. Каждый раз, когда он останавливается, снова заговаривайте с ним."}, [10]={hint="Принесите сеть Лефтендрис Латроникусу Лунному Копью в Крепость Оперенной Луны в Фераласе.", desc="Место: Пройдите по верхнему проходу из сада на платформу Лефтендрис.", spot="Пройдите по верхнему проходу из сада на платформу Лефтендрис."}, [11]={hint="Отыщите Сквернит в Забытом Городе и подберите его осколок. Есть шанс, что вам удастся его добыть, только убив Алззина Вертоградаря. Крепко заприте осколок в реликварии Чистоты, затем верните его Рабину Сатурне в Ночную Гавань в Лунной поляне.", tag="Необязательно", desc="Место: Комната Алззина.", spot="Комната Алззина."}, [12]={hint="Ступайте в Квартал Криводревов Забытого Города и убейте элементаля воды Гидротварь. Вернитесь в Читальню к сказителю Лидросу и принесите ему сущность Гидротвари.", tag="Необязательно", desc="Место: Идите по нижнему водному проходу восточного крыла и убейте Гидротварь у бассейна.", spot="Идите по нижнему водному проходу восточного крыла и убейте Гидротварь у бассейна."}, [13]={npc="Латроникус Лунное Копье", tgt="Латроникус Лунное Копье"}, [14]={npc="Аж'Тордин", tgt="Аж'Тордин"}, [15]={npc="Рабин Сатурна", tgt="Рабин Сатурна", tag="Необязательно"}, [16]={npc="Сказитель Лидрос", tgt="Сказитель Лидрос", tag="Необязательно", desc="Войдите в библиотеку через боковую дверь во дворе северного входа."}}},
    ["04-55"] = {steps={[1]={to="Aerie Peak", toA="{a:348}", desc="Если лагерь Промозглого Ветра открыт, летите прямо туда и пропустите следующий шаг. Если Заоблачного пика нет на карте полетов, летите в Южнобережье и бегите на восток до Заоблачного пика тем же путем, что и во Внутренних землях."}, [2]={text="От Заоблачного пика идите по горной тропе на север в юго-восточный угол Западных Чумных земель (65.30, 86.80), а затем по дороге на запад до лагеря Промозглого Ветра.", tag="Маршрут полета еще не открыт. В первый раз доберитесь туда пешком."}, [3]={nodeA="{a:3197}", node="Chillwind Camp"}, [4]={npc="Командир Ашлам Отважный Кулак", tgt="Командир Ашлам Отважный Кулак"}, [5]={npc="Командир Ашлам Отважный Кулак", tgt="Командир Ашлам Отважный Кулак"}, [6]={hint="Принесите 20 камней Плети приспешников верховному жрецу Тель'данису в Западные Чумные земли."}, [7]={npc="Верховный жрец Тель'данис", tgt="Верховный жрец Тель'данис"}, [8]={npc="Верховный жрец Тель'данис", tgt="Верховный жрец Тель'данис"}, [9]={npc="Командир Ашлам Отважный Кулак", tgt="Командир Ашлам Отважный Кулак"}, [10]={npc="Командир Ашлам Отважный Кулак", tgt="Командир Ашлам Отважный Кулак", tag="Делайте с группой, Необязательно", desc="Сдайте задание, чтобы получить Камень мощи."}, [11]={hint="Принесите вудуистские перья Ашламу Отважному Кулаку.", tag="Делайте с группой, Необязательно", desc="Сдайте задание, чтобы получить Камень мощи."}, [12]={npc="Командир Ашлам Отважный Кулак", tgt="Командир Ашлам Отважный Кулак", tag="Делайте с группой, Необязательно", desc="Сдайте задание, чтобы получить Камень мощи."}, [13]={npc="Командир Ашлам Отважный Кулак", tgt="Командир Ашлам Отважный Кулак"}, [14]={npc="Командир Ашлам Отважный Кулак", tgt="Командир Ашлам Отважный Кулак"}, [15]={npc="Офицер Чистосердая из ордена Серебряного Рассвета", tgt="Офицер Чистосердая из ордена Серебряного Рассвета"}, [16]={npc="Офицер Чистосердая из ордена Серебряного Рассвета", tgt="Офицер Чистосердая из ордена Серебряного Рассвета"}, [17]={npc="Офицер Чистосердая из ордена Серебряного Рассвета", tgt="Офицер Чистосердая из ордена Серебряного Рассвета"}, [18]={npc="Офицер Чистосердая из ордена Серебряного Рассвета", tgt="Офицер Чистосердая из ордена Серебряного Рассвета", desc="Задание на доставку письма; сдайте его у входа на Хиджал."}, [19]={npc="Флинт Тенемор", tgt="Флинт Тенемор", tag="Необязательно"}, [20]={npc="Флинт Тенемор", tgt="Флинт Тенемор", tag="Необязательно"}, [21]={hint="Убейте 10 скелетов-свежевателей и 10 слюнявых вурдалаков на холме Печали."}, [22]={npc="Командир Ашлам Отважный Кулак", tgt="Командир Ашлам Отважный Кулак"}, [23]={npc="Командир Ашлам Отважный Кулак", tgt="Командир Ашлам Отважный Кулак"}, [24]={npc="Командир Ашлам Отважный Кулак", tgt="Командир Ашлам Отважный Кулак"}, [25]={npc="Верховная жрица Макдонелл", tgt="Верховная жрица Макдонелл"}, [26]={npc="Верховная жрица Макдонелл", tgt="Верховная жрица Макдонелл"}, [27]={hint="Отметьте все башни Андорала при помощи сигнального факела; задействовать факел следует, находясь в дверном проеме каждой из башен."}, [28]={hint="Отправляйтесь на поле Джанис в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Джанис."}, [29]={npc="Котел Плети", npcObj=true}, [30]={npc="Котел Плети", npcObj=true}, [31]={npc="Джанис Фелстоун", tgt="Джанис Фелстоун"}, [32]={npc="Посылка Дженис", npcObj=true}, [33]={npc="Посылка Дженис", npcObj=true}, [34]={npc="Командир Ашлам Отважный Кулак", tgt="Командир Ашлам Отважный Кулак"}, [35]={npc="Верховная жрица Макдонелл", tgt="Верховная жрица Макдонелл"}, [36]={npc="Верховная жрица Макдонелл", tgt="Верховная жрица Макдонелл"}, [37]={hint="Отправляйтесь в Слезы Далсона в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Слез Далсона."}, [38]={npc="Котел Плети", npcObj=true}, [39]={npc="Котел Плети", npcObj=true}, [40]={npc="Дневник миссис Далсон", npcObj=true, desc="Дневник в амбаре рядом с котлом."}, [41]={hint="Выполните задачи задания."}, [42]={npc="Дневник миссис Далсон", npcObj=true}, [43]={npc="Уборная", npcObj=true, desc="Прочитав дневник, найдите бродячего скелета. Когда откроете уборную, появится фермер."}, [44]={hint="Добыча с: Бродячий скелет"}, [45]={npc="Уборная", npcObj=true}, [46]={npc="Запертый шкаф", npcObj=true, desc="Сначала зачистите территорию вокруг уборной; открыв шкафчик, можно сразу сдать квест."}, [47]={hint="Добыча с: Фермер Далсон"}, [48]={npc="Запертый шкаф", npcObj=true}, [49]={npc="Верховная жрица Макдонелл", tgt="Верховная жрица Макдонелл"}, [50]={npc="Верховная жрица Макдонелл", tgt="Верховная жрица Макдонелл"}, [51]={npc="Натаниэль Дамах", tgt="Натаниэль Дамах"}, [52]={hint="Отправляйтесь в Удел Страданий в Западных Чумных землях. Найдите и одолейте Хранителя котла. Взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с Удела Страданий."}, [53]={npc="Котел Плети", npcObj=true}, [54]={npc="Котел Плети", npcObj=true}, [55]={npc="Мулгрис Глубокая Река", tgt="Мулгрис Глубокая Река"}, [56]={hint="Убейте 8 больных волков и вернитесь к Мулгрису Глубокой Реке в Удел Страданий в Западных Чумных землях."}, [57]={npc="Мулгрис Глубокая Река", tgt="Мулгрис Глубокая Река"}, [58]={npc="Мулгрис Глубокая Река", tgt="Мулгрис Глубокая Река"}, [59]={hint="Убейте 8 болезненных гризли и вернитесь к Мулгрису Глубокой Реке в Удел Страданий в Западных Чумных землях."}, [60]={npc="Мулгрис Глубокая Река", tgt="Мулгрис Глубокая Река"}, [61]={npc="Мулгрис Глубокая Река", tgt="Мулгрис Глубокая Река"}, [62]={text="Идите на юго-восток и отсюда горной тропой во Внутренние земли."}, [63]={text="Привяжите камень возвращения в таверне Заоблачный Пик (13.80, 41.60).", bindA="{a:348}"}, [64]={npc="Сокровище Кортелло", npcObj=true, tag="Необязательно", desc="Сокровище находится на восточном побережье Внутренних земель, придется пересечь всю карту; после сдачи вернитесь с помощью камня возвращения."}, [65]={bindA="{a:348}"}}},
    ["04-56"] = {steps={[1]={text="От Заоблачного пика идите по горной тропе на север в Западные Чумные земли, затем на восток через реку Тондрорил в Восточные Чумные земли. Тирион Фордринг находится в хижине прямо у входа."}, [2]={npc="Тирион Фордринг", tgt="Тирион Фордринг"}, [3]={npc="Тирион Фордринг", tgt="Тирион Фордринг"}, [4]={npc="Тирион Фордринг", tgt="Тирион Фордринг"}, [5]={hint="Убейте 20 карликовых чумных псов, 5 чумных псов и 5 бесноватых чумных псов. По выполнении задания вернитесь к Тириону Фордрингу."}, [6]={hint="Убейте 30 чумных нетопырей и вернитесь к Тириону Фордрингу."}, [7]={hint="Найдите личинок-падальщиков и падальщиков-пожирателей. Убейте побольше и наберите из мяса. Возвращайтесь к Тириону Фордрингу, когда накопите 15 кусков мяса червей-трупоедов."}, [8]={npc="Тирион Фордринг", tgt="Тирион Фордринг"}, [9]={npc="Тирион Фордринг", tgt="Тирион Фордринг"}, [10]={npc="Тирион Фордринг", tgt="Тирион Фордринг"}, [11]={npc="Тирион Фордринг", tgt="Тирион Фордринг"}, [12]={npc="Тирион Фордринг", tgt="Тирион Фордринг"}, [13]={npc="Тирион Фордринг", tgt="Тирион Фордринг"}, [14]={npc="Памела Редпат", tgt="Памела Редпат"}, [15]={npc="Памела Редпат", tgt="Памела Редпат"}, [16]={hint="Найдите куклу Памелы.", desc="В разрушенных домах Дарроушира соберите голову, левую и правую половины и соедините их правым щелчком."}, [17]={npc="Памела Редпат", tgt="Памела Редпат"}, [18]={npc="Памела Редпат", tgt="Памела Редпат"}, [19]={npc="Памела Редпат", tgt="Памела Редпат"}, [20]={npc="Герцог Николас Зверенхофф", tgt="Герцог Николас Зверенхофф"}, [21]={npc="Герцог Николас Зверенхофф", tgt="Герцог Николас Зверенхофф", tag="Необязательно, Делайте с группой"}, [22]={npc="Бетина Биггльцинк", tgt="Бетина Биггльцинк", tag="Необязательно, Делайте с группой"}, [23]={npc="Леонид Барталомей Чтимый", tgt="Леонид Барталомей Чтимый", tag="Необязательно, Делайте с группой"}, [24]={npc="Дымок ЛаРу", tgt="Дымок ЛаРу", tag="Необязательно, Делайте с группой"}, [25]={node="Часовня Последней Надежды"}, [26]={npc="Карлин Редпат", tgt="Карлин Редпат"}, [27]={npc="Карлин Редпат", tgt="Карлин Редпат", tag="Необязательно"}, [28]={npc="Управляющий Ален", tgt="Управляющий Ален"}, [29]={hint="Освободите 15 духов Дарроушира и возвращайтесь к Карлину Редпату.", tag="Необязательно", desc="Отдельный крюк, других целей рядом нет. Если торопитесь, пропустите."}, [30]={hint="Отправляйтесь в Крипту - в самой южной части Восточных Чумных земель - и добудьте молот Таэлана. Отнесите его Тириону Фордрингу."}, [31]={hint="Принесите голову Зельдарра Управляющему Алену в Часовню Последней Надежды."}, [32]={npc="Разорванный свиток", npcObj=true}, [33]={hint="Поищите в Восточных Чумных землях сведения про некоего Гнилостеня и пропавших агентов ШРУ. Если удастся найти знаки отличия ШРУ, отнесите их Флинту Тенемору в Лагерь Промозглого Ветра.", tag="Необязательно", desc="Возьмите по знаку отличия с каждого из трёх тел. Собрав все три, проверьте цель разведки в журнале. Если она ещё не выполнена, разведайте окрестности отмеченного места, обходя элитного противника."}, [34]={npc="Тирион Фордринг", tgt="Тирион Фордринг"}, [35]={npc="Тирион Фордринг", tgt="Тирион Фордринг"}, [36]={npc="Управляющий Ален", tgt="Управляющий Ален"}, [37]={npc="Карлин Редпат", tgt="Карлин Редпат", tag="Необязательно"}}},
    ["04-53"] = {steps={[1]={to="Southshore", toA="{a:271}", desc="Вы сделаете пересадку в лагере Промозглого Ветра или на Заоблачном пике; если Южнобережья нет на карте полетов, летите в Штормград, как обычно, и плывите в Аубердин с порта."}, [2]={npc="Ролей Благочестивый", tgt="Ролей Благочестивый", tag="Необязательно, Требуются материалы"}, [3]={to="Аубердин", from="Southshore", fromA="{a:271}", desc="В порту Южнобережья сядьте на корабль до Аубердина. Если вы летите в Штормград, садитесь на корабль в порту Штормграда."}, [4]={to="Everlook", toA="{a:2255}"}, [5]={hint="По просьбе Доновы Снегоноры из Зимних Ключей убейте 8 землепроходцев, 8 дозорных и 8 тотемистов из племени Зимней Спячки."}, [6]={hint="Сальфа хочет, чтобы вы убили 8 |4шамана:шаманов:шаманов; из племени Зимней Спячки, 8 |4дозорного:дозорных:дозорных; из племени Зимней Спячки и 8 |4ведмедя:ведмедей:ведмедей; из племени Зимней Спячки. Сальфа находится у входа в крепость Древобрюхов в Зимних Ключах."}, [7]={npc="Пустая фляга из-под огненной воды", npcObj=true, tag="Берите, если выпал, Необязательно", desc="С фурболгов племени Зимней Спячки падает Пустая фляга из-под огненной воды; подобрав ее, щелкните по ней правой кнопкой, чтобы взять задание; если она еще не выпала, продолжайте бить фурболгов."}, [8]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [9]={npc="Донова Снегонора", tgt="Донова Снегонора", tag="Если выпало"}, [10]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [11]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [12]={npc="Донова Снегонора", tgt="Донова Снегонора", desc="Исследование Теснина Зловещего Шепота засчитается по пути на Хиджал на следующей остановке; сдайте задание до возвращения в Зимних Ключах и перелета в Лунной поляне. Сдайте до возвращения в Зимних Ключах и перелета в Лунной поляне."}, [13]={hint="Соберите в Зимних Ключах 10 светолунных перьев, принести их Эреласу Янтарному Небу в деревню Рут'теран."}, [14]={npc="Сальфа", tgt="Сальфа"}, [15]={npc="Котел Мертвого Леса", npcObj=true}, [16]={npc="Котел Мертвого Леса", npcObj=true}, [17]={to="Rut'theran Village", toA="{a:702}", desc="От Котла Мертвого Леса идите на юг к точке полета на Поляне Когтистых Ветвей (62.49, 24.24) и вылетайте оттуда; пересадка будет в Аубердине."}, [18]={npc="Эрелас Янтарное Небо", tgt="Эрелас Янтарное Небо"}, [19]={npc="Эрелас Янтарное Небо", tgt="Эрелас Янтарное Небо"}, [20]={npc="Дарин Добрый Ветер", tgt="Дарин Добрый Ветер"}, [21]={to="Everlook", toA="{a:2255}"}, [22]={npc="Харло Торгуместец", tgt="Харло Торгуместец"}, [23]={npc="Харло Торгуместец", tgt="Харло Торгуместец", tag="Необязательно", desc="Задание-разговор в городе; в продолжении нужно бить элитных великанов — не берите."}, [24]={npc="Знахарь Мау'ари", tgt="Знахарь Мау'ари", tag="Необязательно"}, [25]={npc="Юми Румпельшникер", tgt="Юми Румпельшникер", desc="Бейте йети после возвращения от Доновы, перед тем как отправиться на юг."}, [26]={npc="Вунд Ночной Охотник", tgt="Вунд Ночной Охотник"}, [27]={npc="Вунд Ночной Охотник", tgt="Вунд Ночной Охотник"}, [28]={npc="Джерон Гранильщик", tgt="Джерон Гранильщик"}, [29]={npc="Джерон Гранильщик", tgt="Джерон Гранильщик"}, [30]={npc="Джерон Гранильщик", tgt="Джерон Гранильщик"}, [31]={npc="Джерон Гранильщик", tgt="Джерон Гранильщик"}, [32]={hint="Используйте кирку Джерона, чтобы добыть фрагменты реликвии высокорожденных, Принесите их Авроре Зову Небес в Восточные Чумные земли."}, [33]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [34]={hint="Соберите 10 толстых кусков меха йети для Юми Румпельшникер из Круговзора."}, [35]={npc="Юми Румпельшникер", tgt="Юми Румпельшникер"}, [36]={npc="Юми Румпельшникер", tgt="Юми Румпельшникер", tag="Необязательно", desc="Рога падают только с матриархов и патриархов в пещере, и шанс выпадения низкий; делайте, если хотите добрать опыта."}, [37]={hint="Добудьте 2 безупречных рога Йети для Юми Румпельшникер из Круговзора.", tag="Необязательно"}, [38]={npc="Юми Румпельшникер", tgt="Юми Румпельшникер", tag="Необязательно", desc="Для продолжения нужно ехать в Ун'Горо и Прибамбасск — не берите."}, [39]={npc="Поврежденный ящик", npcObj=true}, [40]={npc="Поврежденный ящик", npcObj=true}, [41]={npc="Фургон Джерона", npcObj=true}, [42]={npc="Фургон Джерона", npcObj=true}, [43]={hint="Подберите припасы Джерона из снега, и найдите дикого совуха, похитившего амулет, о котором говорил Джерон."}, [44]={npc="Раншалла", tgt="Раншалла"}, [45]={npc="Раншалла", tgt="Раншалла"}, [46]={hint="Защитите Раншаллу, пока она пытается активировать алтарь Элуны. Сообщите о ваших находках Эреласу Янтарному Небу в деревне Рут'теран."}}},
    ["04-57"] = {danger={[1]="Ghansurok (химера 61 уровня, элита) патрулирует от оскверненного гибискуса до мастерской Кайлаэны (около x55-62,5, y61,5-72,2); смотрите, где он, когда бьете кусты и возвращаетесь в мастерскую.", [2]="Горький Селаструс (элита 57 уровня) бродит у оскверненного гибискуса; будьте осторожны, когда бьете кусты.", [3]="Куча костей призывает слизь 58 уровня (элита); без группы не щелкайте по ней второй раз."}, grind={[1]={note="Северная часть Сквернокровного Шрама; все задания Felflick выполняются здесь."}}, supply={[1]={}}, steps={[1]={text="От Раншаллы идите на юг в Теснину Зловещего Шепота (59.82, 74.25) и следуйте по ней на запад до самого конца — так вы попадете на Гору Хиджал. У входа в теснину стоят элитные ледяные великаны, внутри — элитные демоны; держитесь дороги и не останавливайтесь.", tag="Маршрут полета еще не открыт. В первый раз доберитесь туда пешком."}, [2]={hint="Последуйте указаниям Доновы Снегоноры, а затем вернитесь к ней.", desc="Засчитывается при проходе через ущелье на Хиджале, отдельного крюка не нужно. Достаточно, чтобы журнал заданий показывал ее как выполненную."}, [3]={text="Войдите на Хиджал в юго-восточном углу и идите по дороге на запад."}, [4]={npc="Квинтий Вейнворт", tgt="Квинтий Вейнворт"}, [5]={npc="Квинтий Вейнворт", tgt="Квинтий Вейнворт"}, [6]={npc="Незакрепленный зубец", npcObj=true, desc="Шестеренка на земле у дороги; щелкните правой кнопкой, чтобы подобрать ее и взять задание."}, [7]={npc="Кетарас", tgt="Кетарас", tag="Необязательно", desc="Сдавайте, только если брали это в Оскверненном лесу."}, [8]={npc="Кетарас", tgt="Кетарас"}, [9]={npc="Кетарас", tgt="Кетарас"}, [10]={npc="Кетарас", tgt="Кетарас"}, [11]={npc="Кетарас", tgt="Кетарас"}, [12]={npc="Кетарас", tgt="Кетарас"}, [13]={hint="Найдите 12 |4яйцо:яйца:яиц; хиджальской совы и принесите Кетарасу."}, [14]={hint="Соберите 10 |4неоскверненное семя:неоскверненных семени:неоскверненных семян; для Кетараса."}, [15]={npc="Кетарас", tgt="Кетарас"}, [16]={npc="Кетарас", tgt="Кетарас"}, [17]={npc="Кетарас", tgt="Кетарас"}, [18]={npc="Кетарас", tgt="Кетарас"}, [19]={hint="Добудьте 2 |4кусок хиджальской оленины:куска хиджальской оленины:кусков хиджальской оленины; и 6 |4алый стрелокорень:алых стрелокорня:алых стрелокорней; для похлебки отшельника."}, [20]={hint="Посадите зачарованные семена рядом со сломанной баллистой, сломанной катапультой и сломанным ветролетом.", desc="Обломки баллисты, катапульты и летательного аппарата считаются отдельными целями, засеять нужно все три. Ищите на склоне у Пещеры отшельника."}, [21]={npc="Кетарас", tgt="Кетарас"}, [22]={npc="Кетарас", tgt="Кетарас"}, [23]={npc="Кетарас", tgt="Кетарас"}, [24]={hint="Похороните останки у алтаря Кетараса."}, [25]={npc="Кетарас", tgt="Кетарас"}, [26]={npc="Кетарас", tgt="Кетарас"}, [27]={nodeA="{a:16853}", node="Tainted Foothills", desc="Идите по дороге на запад; пункт полета находится рядом с заставой древних."}, [28]={npc="Разломий", tgt="Разломий"}, [29]={npc="Гиацинт", tgt="Гиацинт"}, [30]={npc="Гиацинт", tgt="Гиацинт"}, [31]={npc="Тилаэна", tgt="Тилаэна", tag="Делайте с группой, Необязательно", desc="Цель — элита 57 уровня; если в одиночку не победить, не берите."}, [32]={hint="Добудьте 6 |4образец:образца:образцов; неоскверненной земли на подножьях горы Хиджал."}, [33]={npc="Кайлена Шепот Ключей", tgt="Кайлена Шепот Ключей"}, [34]={npc="Кайлена Шепот Ключей", tgt="Кайлена Шепот Ключей"}, [35]={npc="Кайлена Шепот Ключей", tgt="Кайлена Шепот Ключей", desc="Когда позже будете в Круговзоре, найдите Nami за деталями."}, [36]={hint="Уничтожьте 15 |4зараженный куст:зараженных куста:зараженных кустов; для Кайлены Шепот Ключей, чья мастерская находится в Оскверненных предгорьях.", desc="С тех же кустов гибискуса выпадают и кровоостанавливающие листья; бейте их сразу для обоих заданий. Сдайте в мастерской, когда доставите ящик."}, [37]={hint="Добудьте 12 |4зеленый лист:зеленых листа:зеленых листьев; с зараженных кустов у подножья горы Хиджал."}, [38]={hint="Найдите и уничтожьте Целастрия едкого, а затем вернитесь к Тилаэне с его обломанным листом.", tag="Делайте с группой, Необязательно"}, [39]={npc="Тилаэна", tgt="Тилаэна", tag="Делайте с группой, Необязательно"}, [40]={npc="Гиацинт", tgt="Гиацинт"}, [41]={npc="Гиацинт", tgt="Гиацинт"}, [42]={npc="Гиацинт", tgt="Гиацинт"}, [43]={hint="Нанесите припарку на раны Разломия."}, [44]={npc="Разломий", tgt="Разломий"}, [45]={npc="Разломий", tgt="Разломий", tag="Делайте с группой, Необязательно", desc="Цель — Сандербарк, древний 56 уровня (элита); делайте, когда есть группа; без группы пропустите — последующая сдача пропустится автоматически."}, [46]={npc="Разломий", tgt="Разломий"}, [47]={npc="Любопытная ворона", tgt="Любопытная ворона"}, [48]={npc="Любопытная ворона", tgt="Любопытная ворона"}, [49]={npc="Любопытная ворона", tgt="Любопытная ворона"}, [50]={npc="Сквернопых", tgt="Сквернопых"}, [51]={npc="Сквернопых", tgt="Сквернопых"}, [52]={hint="Убейте 12 |4пепельного послушника:пепельных послушников:пепельных послушников;.", desc="Записки падают с тех же служителей, так что выполняйте оба задания сразу."}, [53]={hint="Найдите 12 |4запись:записи:записей; об экспериментах с пеплом Скверны."}, [54]={npc="Сквернопых", tgt="Сквернопых"}, [55]={npc="Сквернопых", tgt="Сквернопых"}, [56]={hint="Добудьте 8 |4кусок:куска:кусков; кристаллизованной слизи Скверны и 1 |4кусок:куска:кусков; безупречной кристаллизованной слизи Скверны."}, [57]={npc="Любопытная ворона", tgt="Любопытная ворона"}, [58]={npc="Любопытная ворона", tgt="Любопытная ворона"}, [59]={npc="Любопытная ворона", tgt="Любопытная ворона"}, [60]={hint="Соберите 8 |4порцию:порции:порций; густой слизи Скверны."}, [61]={hint="Соберите 10 |4колючую шишку:колючие шишки:колючих шишек; под здоровыми деревьями."}, [62]={npc="Любопытная ворона", tgt="Любопытная ворона"}, [63]={npc="Любопытная ворона", tgt="Любопытная ворона"}, [64]={npc="Сквернопых", tgt="Сквернопых"}, [65]={npc="Сквернопых", tgt="Сквернопых"}, [66]={npc="Сквернопых", tgt="Сквернопых"}, [67]={hint="Добудьте кости Фреззли Шустрого Ловкача, Тайехи Мрачная Клятва и Дазки Сон Теней."}, [68]={hint="Убейте Брашанна Темномрака и обыщите тело, чтобы забрать камень души."}, [69]={npc="Сквернопых", tgt="Сквернопых"}, [70]={npc="Сквернопых", tgt="Сквернопых"}, [71]={npc="Сквернопых", tgt="Сквернопых"}, [72]={npc="Груда костей", npcObj=true, desc="Бросьте кости чернокнижника в кучу костей рядом с лужей слизи."}, [73]={npc="Груда костей", npcObj=true, tag="Делайте с группой, Необязательно", desc="Призывает слизь 58 уровня (элита); без группы пропустите «Amalgamated Marrow» и последующие задания."}, [74]={hint="Убейте пробужденного слизнюка оскверненного пепла.", tag="Делайте с группой, Необязательно"}, [75]={npc="Велициан", tgt="Велициан"}, [76]={npc="Сквернопых", tgt="Сквернопых", tag="Делайте с группой, Необязательно"}, [77]={npc="Сквернопых", tgt="Сквернопых"}, [78]={npc="Любопытная ворона", tgt="Любопытная ворона"}, [79]={npc="Любопытная ворона", tgt="Любопытная ворона"}, [80]={npc="Любопытная ворона", tgt="Любопытная ворона"}, [81]={npc="Любопытная ворона", tgt="Любопытная ворона"}, [82]={hint="С помощью шишек уничтожьте мастерские Пепельной империи."}, [83]={npc="Любопытная ворона", tgt="Любопытная ворона"}, [84]={npc="Любопытная ворона", tgt="Любопытная ворона", desc="Сдайте в Стародревье на западе на следующей остановке."}, [85]={hint="Найдите и уничтожьте оскверненное древо по имени Сколодрев, а затем посадите семя в его останки.", tag="Делайте с группой, Необязательно", desc="По пути назад на восток к Пещере отшельника."}, [86]={npc="Кетарас", tgt="Кетарас"}, [87]={npc="Кетарас", tgt="Кетарас"}, [88]={npc="Разломий", tgt="Разломий", tag="Делайте с группой, Необязательно"}, [89]={to="Everlook", toA="{a:2255}"}, [90]={npc="Нами", tgt="Нами", desc="Следующий ящик ограничен по времени; возьмите его после возвращения из Лунной поляны."}, [91]={npc="Джерон Гранильщик", tgt="Джерон Гранильщик", desc="От Круговзора пройдите по дороге немного на запад до Деревни Звездопада."}, [92]={text="Скачите от Деревни Звездопада по дороге на юго-запад к горячему источнику и найдите Donova."}, [93]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [94]={to="Лунная поляна", desc="Скачите от горячего источника обратно к пункту полета Круговзор и летите (пункт полета Лунная поляна открыт на {s:04-49}). Если репутация у Древобрюхов уже нейтральная, скачите от источника на север ко входу в Крепость Древобрюхов (27.70, 34.50); через пещеру к выходу в Лунной поляне ближе; если пункт полета Лунная поляна не открыт, идите этим же путем и по прибытии сначала откройте его (48.10, 67.34); при репутации ниже нейтральной вас атакуют. Друиды могут сразу использовать «Телепортация: Лунная поляна»; по прибытии идите к обычному пункту полета (48.10, 67.34) и откройте его, чтобы вернуться по воздуху. Если пункт полета Лунная поляна не открыт, идите этим же путем и по прибытии сначала откройте его (48.10, 67.34). При репутации ниже нейтральной вас атакуют. Друиды могут сразу использовать «Телепортация: Лунная поляна»; по прибытии идите к обычному пункту полета (48.10, 67.34) и откройте его, чтобы вернуться по воздуху."}, [95]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [96]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [97]={npc="Орокай", tgt="Орокай"}, [98]={npc="Орокай", tgt="Орокай"}, [99]={hint="Поговорите с Орокаем, когда будете готовы увидеть то, что он узнал от тускло светящейся ветви."}, [100]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [101]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [102]={to="Everlook", toA="{a:2255}", desc="Вылетите из обычного пункта полета Лунная поляна (48.10, 67.34) и сойдите в Круговзор, чтобы забрать ящик."}, [103]={npc="Нами", tgt="Нами", desc="Батареи в ящике выходят из строя примерно через два часа, поэтому доставьте его Кайлаэне прямо от пункта полета."}, [104]={to="Tainted Foothills", toA="{a:16853}", desc="От пункта полета скачите прямо на север к мастерской Кайлаэны и сначала доставьте ящик."}}},
    ["04-58"] = {danger={[1]="Ghansurok (химера 61 уровня, элита) патрулирует к востоку от Святилища Авианы; будьте осторожны, когда бьете гарпий."}, supply={[1]={}, [2]={}}, steps={[1]={hint="Аккуратно доставьте ящик с запчастями и безделушками Кайлене Шепот Ключей на гору Хиджал.", desc="Принесите ящик Кайлаэне в мастерскую и следуйте указаниям в диалоге задания."}, [2]={npc="Кайлена Шепот Ключей", tgt="Кайлена Шепот Ключей", desc="От пункта полета скачите прямо на север к мастерской и сначала доставьте ящик."}, [3]={npc="Кайлена Шепот Ключей", tgt="Кайлена Шепот Ключей"}, [4]={npc="Кайлена Шепот Ключей", tgt="Кайлена Шепот Ключей", desc="Материалы лежат в остатках лагеря Орды в Даэ'гане на севере; подберите их, когда будете проходить позже."}, [5]={npc="Кетарас", tgt="Кетарас", desc="Скачите от мастерской на юго-восток обратно к Пещере отшельника."}, [6]={npc="Кетарас", tgt="Кетарас"}, [7]={npc="Кетарас", tgt="Кетарас"}, [8]={npc="Повелитель небес Омнурон", tgt="Повелитель небес Омнурон", desc="Скачите от Пещеры отшельника на северо-запад к Святилищу Авианы."}, [9]={npc="Повелитель небес Омнурон", tgt="Повелитель небес Омнурон"}, [10]={npc="Повелитель небес Омнурон", tgt="Повелитель небес Омнурон"}, [11]={npc="Феба Высокопарящая", tgt="Феба Высокопарящая"}, [12]={npc="Феба Высокопарящая", tgt="Феба Высокопарящая"}, [13]={hint="Убейте 18 |4гарпию:гарпий:гарпий; из стаи Червивого Крыла на горе Хиджал и принесите их перья Фебе Высокопарящей."}, [14]={hint="Добудьте 8 |4потускневший браслет:потускневших браслета:потускневших браслетов; Высокопарящих из гнезд гарпий Червивого Крыла."}, [15]={hint="Найдите драгоценный камень горизонта в гнездах гарпий Червивого Крыла на горе Хиджал и отнесите его Кетарасу."}, [16]={hint="Убейте Заррат Червивое Крыло и верните копье Омнурона."}, [17]={npc="Нарост порчи", npcObj=true, desc="Щелкните правой кнопкой по оскверненному наросту на дереве, чтобы взять задание."}, [18]={hint="Найдите и срежьте 6 |4оскверненный сучок:оскверненных сучка:оскверенных сучков; с деревьев поблизости."}, [19]={npc="Феба Высокопарящая", tgt="Феба Высокопарящая"}, [20]={npc="Феба Высокопарящая", tgt="Феба Высокопарящая"}, [21]={npc="Феба Высокопарящая", tgt="Феба Высокопарящая"}, [22]={npc="Повелитель небес Омнурон", tgt="Повелитель небес Омнурон"}, [23]={npc="Любопытная ворона", tgt="Любопытная ворона"}, [24]={npc="Любопытная ворона", tgt="Любопытная ворона", desc="Выполнить можно только на мосту в Колыбели Спокойствия на севере, поэтому пока носите с собой."}, [25]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring", desc="Идите вдоль подножия на запад."}, [26]={hint="Locate a sturdy branch capable of reaching Fenwick Togglespring."}, [27]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [28]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [29]={hint="Убить: Tree Branch"}, [30]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [31]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [32]={npc="Personal Survival Pack", tgt="Personal Survival Pack"}, [33]={npc="Personal Survival Pack", tgt="Personal Survival Pack"}, [34]={hint="Wait until you can safely open the Personal Survival Pack."}, [35]={npc="Personal Survival Pack", tgt="Personal Survival Pack"}, [36]={npc="Бреруфа", tgt="Бреруфа"}, [37]={hint="Победите 9 |4стража:стражей:стражей; из племени Мертвого Леса и вернитесь к Бреруфе"}, [38]={npc="Бреруфа", tgt="Бреруфа"}, [39]={npc="Бреруфа", tgt="Бреруфа", tag="Необязательно, If offered", desc="Берите, только если задание видно. Сдавайте, только если у вас уже есть 8 нитей бус; специально добывать не нужно."}, [40]={npc="Бреруфа", tgt="Бреруфа"}, [41]={npc="Оси Туманная Лапа", tgt="Оси Туманная Лапа"}, [42]={npc="Оси Туманная Лапа", tgt="Оси Туманная Лапа"}, [43]={hint="Соберите 30 |4медвежью ягоду:медвежьи ягоды:медвежьих ягод; на Хиджале и вернитесь к Оси Туманная Лапа."}, [44]={npc="Оси Туманная Лапа", tgt="Оси Туманная Лапа"}, [45]={npc="Оси Туманная Лапа", tgt="Оси Туманная Лапа"}, [46]={hint="Найдите и поговорите со старейшинами Туманная Лапа и Хвоеуст в норе Древокожих"}, [47]={npc="Старейшина Туманная Лапа", tgt="Старейшина Туманная Лапа"}, [48]={npc="Старейшина Туманная Лапа", tgt="Старейшина Туманная Лапа"}, [49]={npc="Старейшина Хвоеуст", tgt="Старейшина Хвоеуст"}, [50]={npc="Сума Мохогрив", tgt="Сума Мохогрив"}, [51]={npc="Феннар Моховая Грива", tgt="Феннар Моховая Грива", tag="Необязательно, If offered", desc="Берите, только если задание видно (нужна репутация пещеры древесных фурболгов)."}, [52]={npc="Феннар Моховая Грива", tgt="Феннар Моховая Грива", tag="Необязательно, If offered", desc="Берите, только если задание видно (нужна репутация пещеры древесных фурболгов). Наполните бурдюк в пруду у логова Мертвого Леса."}, [53]={hint="Collect 10 Dried Hanging Herbs from around Barkskin Burrow and return them to Fennar Mossmane.", tag="Необязательно"}, [54]={npc="Старейшина Туманная Лапа", tgt="Старейшина Туманная Лапа", tag="Необязательно, If offered", desc="Берите, только если задание видно. Сдать можно только после того, как репутация пещеры древесных фурболгов достигнет нейтральной."}, [55]={hint="Добыча с: Хиджальская сова"}, [56]={hint="Соберите 12 |4комок:комка:комков; мха лунной пелены и вернитесь к Суме Мохогрив."}, [57]={hint="Победите 8 |4тотемиста:тотемистов:тотемистов; и 8 |4скверновода:скверноводов:скверноводов; из племени Мертвого Леса и вернитесь к старейшине Хвоеуст"}, [58]={hint="Fill a waterskin provided by Fennar Mossmane at the pond outside of the Deadwood Furbolg den.", tag="Необязательно", desc="Ищите пруд у логова Мертвого Леса."}, [59]={npc="Матриарх из племени Древокожих", tgt="Матриарх из племени Древокожих"}, [60]={hint="Заберите ключ Мертвого Леса у заступника из племени Мертвого Леса и вернитесь к клетке Древокожих."}, [61]={npc="Матриарх из племени Древокожих", tgt="Матриарх из племени Древокожих"}, [62]={npc="Матриарх из племени Древокожих", tgt="Матриарх из племени Древокожих"}, [63]={hint="Сопроводите матриарха Древокожих из логова племени Мертвого Леса и вернитесь в нору Древокожих", desc="Задание на сопровождение; в группе дождитесь, пока все возьмут его, и только потом начинайте."}, [64]={npc="Бреруфа", tgt="Бреруфа"}, [65]={npc="Бреруфа", tgt="Бреруфа", tag="Необязательно", desc="Сдавайте, только если у вас есть 8 нитей бус."}, [66]={npc="Сума Мохогрив", tgt="Сума Мохогрив"}, [67]={npc="Феннар Моховая Грива", tgt="Феннар Моховая Грива", tag="Необязательно"}, [68]={npc="Феннар Моховая Грива", tgt="Феннар Моховая Грива", tag="Необязательно"}, [69]={npc="Старейшина Туманная Лапа", tgt="Старейшина Туманная Лапа", tag="Необязательно", desc="Сдавайте, только когда репутация достигнет нейтральной."}, [70]={npc="Старейшина Хвоеуст", tgt="Старейшина Хвоеуст"}, [71]={npc="Старейшина Хвоеуст", tgt="Старейшина Хвоеуст"}, [72]={npc="Старейшина Хвоеуст", tgt="Старейшина Хвоеуст", tag="Необязательно, If offered", desc="Берите, только если задание видно. Сдать можно только после того, как репутация пещеры древесных фурболгов достигнет дружелюбной."}, [73]={npc="Старейшина Хвоеуст", tgt="Старейшина Хвоеуст", tag="Необязательно", desc="Сдавайте, только когда репутация достигнет дружелюбной. Если недостаточно, пока оставьте."}, [74]={npc="Элунет", tgt="Элунет", desc="Идите на север."}, [75]={npc="Ветеран Третьей войны", tgt="Ветеран Третьей войны"}, [76]={npc="Сефира Эвербрайт", tgt="Сефира Эвербрайт"}, [77]={npc="Сефира Эвербрайт", tgt="Сефира Эвербрайт"}, [78]={npc="Сефира Эвербрайт", tgt="Сефира Эвербрайт"}, [79]={npc="Mirt", tgt="Mirt"}, [80]={npc="Хназ Огнепых", tgt="Хназ Огнепых", desc="Рядом с таверной Стародревья; совиные гнезда в долине на юге, соберите их по пути, когда вернетесь к Eluneth."}, [81]={hint="Убить: Сбежавшая овца"}, [82]={npc="Mirt", tgt="Mirt"}, [83]={npc="Вышитые ножны", npcObj=true, desc="Смотровая площадка к западу от Стародревья."}, [84]={npc="Вышитые ножны", npcObj=true}, [85]={hint="Используйте вышитые ножны, чтобы поговорить с ветераном войны на высоте в Стародревье и узнать его историю."}, [86]={npc="Ветеран Третьей войны", tgt="Ветеран Третьей войны"}, [87]={npc="Unmarked Grave", npcObj=true, desc="У дороги на восток щелкните правой кнопкой по безымянной могиле, чтобы взять задание."}, [88]={npc="Гальвинкуам Листволорд", tgt="Гальвинкуам Листволорд"}, [89]={hint="Наберите в тыкву-горлянку Гальвинкуама Листволорда воды из водопада, расположенного дальше.", desc="Наберите воду в пустую тыкву из задания у водопада впереди, а не рядом с Galvinquam."}, [90]={npc="Гальвинкуам Листволорд", tgt="Гальвинкуам Листволорд"}, [91]={npc="Гальвинкуам Листволорд", tgt="Гальвинкуам Листволорд", desc="Отнесите багаж на Вершину Вечности."}, [92]={npc="Лисбаэль Высокопарящая", tgt="Лисбаэль Высокопарящая", desc="Позже сдайте у Святилища Авианы."}, [93]={hint="Прикоснитесь к фигурке вороны на мосту, с которого видна Колыбель Спокойствия, чтобы призвать Дикую богиню Джереман."}, [94]={npc="Джереман", tgt="Джереман"}, [95]={npc="Джереман", tgt="Джереман"}, [96]={npc="Джереман", tgt="Джереман"}, [97]={npc="Джереман", tgt="Джереман"}, [98]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [99]={hint="Make skunks leave the area around Johun's equipment without killing them."}, [100]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [101]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [102]={hint="Добыча с: Ржаволистная лиса"}, [103]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [104]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [105]={npc="Кала'т", tgt="Кала'т", desc="Идите на запад."}, [106]={npc="Кала'т", tgt="Кала'т"}, [107]={hint="Убедите оленей прекратить вести себя как хищники."}, [108]={hint="Look through the burned buildings in the Cradle of Tranquility for 6 Metal Brackets and 30 Nails and return to Johun \"Punchy\" Dillas in Hyjal."}, [109]={npc="Кала'т", tgt="Кала'т"}, [110]={npc="Костозис", tgt="Костозис"}, [111]={npc="Костозис", tgt="Костозис"}, [112]={npc="Костозис", tgt="Костозис"}, [113]={hint="Убить: Забытый солдат, Плотоядный глодатель"}, [114]={hint="Добыча с: Плотоядный глодатель, Fleshflayer Ravener"}, [115]={hint="Заполучите каплю украденной жизни у Плети в руинах на горе Хиджал, после чего вернитесь к Кетарасу."}, [116]={hint="Добыча с: Воскреситель из Плети"}, [117]={hint="Соберите 20 |4побелевшую кость:побелевшие кости:побелевших костей;."}, [118]={hint="Добудьте 8 |4глаз:глаза:глаз; дозорного для Элунет."}, [119]={npc="Костозис", tgt="Костозис"}, [120]={npc="Элунет", tgt="Элунет"}, [121]={hint="Добыча с: Хиджальская сова, Зараженная хиджальская сова", desc="Недалеко к югу от Eluneth; их роняют и хиджальские совы. Соберите и вернитесь в Стародревье."}, [122]={npc="Хназ Огнепых", tgt="Хназ Огнепых"}, [123]={npc="Сефира Эвербрайт", tgt="Сефира Эвербрайт"}, [124]={npc="Сефира Эвербрайт", tgt="Сефира Эвербрайт"}, [125]={npc="Сефира Эвербрайт", tgt="Сефира Эвербрайт"}, [126]={npc="Сефира Эвербрайт", tgt="Сефира Эвербрайт"}, [127]={npc="Сефира Эвербрайт", tgt="Сефира Эвербрайт"}, [128]={npc="Daythor Brellan", tgt="Daythor Brellan"}, [129]={npc="Daythor Brellan", tgt="Daythor Brellan"}, [130]={npc="Сефира Эвербрайт", tgt="Сефира Эвербрайт"}, [131]={npc="Сефира Эвербрайт", tgt="Сефира Эвербрайт"}, [132]={npc="Daythor Brellan", tgt="Daythor Brellan"}}},
    ["04-60"] = {danger={[1]="Ghansurok (химера 61 уровня, элита) бродит по гребню к югу от мастерской Кайлаэны.", [2]="Mazzogore (элита 60 уровня) патрулирует к югу от Даэ'гана; обходите его, когда бьете гончих.", [3]="Ve'han Talongrasp (элита 60 уровня) охраняет хижину у Нордрассила; не подходите слишком близко во время заданий с культистами."}, grind={[1]={mob="Караульный-страж Скверны", note="Южная половина Даэ'ган; заодно подбирайте брошенные припасы и материалы из остатков лагеря Орды."}, [2]={note="Лагерь культистов к востоку от Вершины Вечности; все задания вершины выполняются здесь."}}, supply={[1]={}, [2]={}, [3]={}}, steps={[1]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas", desc="Возвращайтесь по дороге на восток."}, [2]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [3]={npc="Элейна Шепот Луны", tgt="Элейна Шепот Луны"}, [4]={npc="Сухобород", tgt="Сухобород"}, [5]={npc="Ясиро", tgt="Ясиро"}, [6]={hint="Зажгите два костра в Даэ'гане и вернитесь к Ясиро."}, [7]={text="Зажгите костер на юго-востоке и идите дальше на юго-восток к Renalard; сначала сдайте «Умное создание», возьмите задания про пепел и лису, а на обратном пути еще раз зачистите Даэ'ган."}, [8]={npc="Реналард", tgt="Реналард"}, [9]={npc="Реналард", tgt="Реналард"}, [10]={npc="Реналард", tgt="Реналард"}, [11]={hint="Соберите 8 |4контейнер:контейнера:контейнеров; брошенных припасов.", desc="Отвлеките демона пучком лисьей шерсти (Tuft of Fox Fur) из задания, затем подберите 8 брошенных припасов. Припасы лежат не рядом с Renalard."}, [12]={hint="Обыщите развалины базы Орды и принесите Кайлене 5 |4кусок:куска:кусков; потертой проволоки, 5 |4кусок:куска:кусков; металлолома и 5 |4кусок:куска:кусков; окаменевших экскрементов."}, [13]={hint="Соберите 6 |4образец:образца:образцов; эфемерной субстанции для Элейны Шепот Луны."}, [14]={hint="Убейте 12 стражей Скверны - часовых в Даэ'гане."}, [15]={hint="Принесите щепотку пепла Азгалора из руин Даэ'гана на горе Хиджал."}, [16]={hint="Enter Dae'gun and locate a high vantage point, then report details to Johun."}, [17]={npc="Ясиро", tgt="Ясиро", desc="Зачистив Даэ'ган, вернитесь сюда к Yashiro и сдайте."}, [18]={npc="Ясиро", tgt="Ясиро", tag="Необязательно"}, [19]={hint="Убивайте врагов в Даэ'гане вместе с Ясиро.", tag="Делайте с группой, Необязательно", desc="Следуйте за Yashiro, пока он расчищает путь; задание выполнено, когда в конце вы победите стражника ужаса Xarkul (Doomguard Xarkul)."}, [20]={npc="Ясиро", tgt="Ясиро", tag="Необязательно", desc="Сдайте Yashiro там, где закончится событие; это не обязательно место начала."}, [21]={npc="Элейна Шепот Луны", tgt="Элейна Шепот Луны"}, [22]={npc="Элейна Шепот Луны", tgt="Элейна Шепот Луны", tag="Делайте с группой, Необязательно", desc="Обе цели — элитные демоны 60 уровня; без группы пропустите — продолжения пропустятся автоматически."}, [23]={hint="Убить: Bethra'zel, Mazzogore", tag="Делайте с группой, Необязательно"}, [24]={npc="Элейна Шепот Луны", tgt="Элейна Шепот Луны", tag="Делайте с группой, Необязательно"}, [25]={npc="Элейна Шепот Луны", tgt="Элейна Шепот Луны"}, [26]={npc="Сухобород", tgt="Сухобород"}, [27]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [28]={npc="Реналард", tgt="Реналард", desc="Идите на юго-восток."}, [29]={nodeA="{a:16849}", node="Summit of Eternity", desc="От Renalard немного поднимитесь в гору на восток и откройте пункт полета Fayran Elthas. Сначала сдайте несколько заданий, принесенных на гору, чтобы разгрузить журнал."}, [30]={npc="Марн Вечный Рог", tgt="Марн Вечный Рог"}, [31]={npc="Тиала Белая Грива", tgt="Тиала Белая Грива", tag="Необязательно", desc="Сдавайте, только если брали это в Кратере Ун'Горо."}, [32]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [33]={npc="Себелия", tgt="Себелия", desc="Письмо-пакет вскоре сдайте в Круговзоре, затем пройдите цепочку почты."}, [34]={npc="Кайлена Шепот Ключей", tgt="Кайлена Шепот Ключей", desc="С Вершины Вечности спуститесь на запад мимо Renalard, затем на юг к мастерской. Если горная тропа непроходима, летите в Оскверненные предгорья и скачите на север."}, [35]={npc="Кайлена Шепот Ключей", tgt="Кайлена Шепот Ключей"}, [36]={hint="Turn the two gears and connect the two battery terminals on both sides of Kaylaena's Glaive Thrower."}, [37]={npc="Кайлена Шепот Ключей", tgt="Кайлена Шепот Ключей"}, [38]={npc="Кайлена Шепот Ключей", tgt="Кайлена Шепот Ключей", tag="Делайте с группой, Необязательно", desc="Выманиваемый Ghansurok — химера 61 уровня (элита)."}, [39]={hint="Walk to the ridge south of Kaylaena's workshop and find a way to make a loud distracting commotion to draw the chimaera Ghansurok in range to be attacked.", tag="Делайте с группой, Необязательно", desc="Взаимодействуйте с барабаном на утесе к югу от мастерской и заманите химеру в зону действия метателя лезвий, чтобы им управлял NPC; не тяните ее далеко, чтобы драться силой."}, [40]={npc="Кайлена Шепот Ключей", tgt="Кайлена Шепот Ключей", tag="Делайте с группой, Необязательно"}, [41]={npc="Феба Высокопарящая", tgt="Феба Высокопарящая", desc="От мастерской пройдите немного на юго-запад до Святилища Авианы."}, [42]={npc="Кетарас", tgt="Кетарас", desc="Скачите от святилища на юго-восток обратно к Пещере отшельника."}, [43]={npc="Кетарас", tgt="Кетарас"}, [44]={npc="Кетарас", tgt="Кетарас"}, [45]={npc="Кетарас", tgt="Кетарас"}, [46]={to="Everlook", toA="{a:2255}", desc="Скачите от Пещеры отшельника на запад и вылетайте из пункта полета Оскверненные предгорья."}, [47]={npc="Хозяйка таверны Виззи", tgt="Хозяйка таверны Виззи"}, [48]={npc="Хозяйка таверны Виззи", tgt="Хозяйка таверны Виззи"}, [49]={hint="Найдите 4 |4пропавшее письмо:пропавших письма:пропавших писем; в холмах к северу от Круговзора и принесите хозяйке таверны Виззи.", desc="Почта разбросана по холмам за Круговзором; ищите ее по подсказкам в журнале заданий; если не найдете, пока можно пропустить."}, [50]={npc="Хозяйка таверны Виззи", tgt="Хозяйка таверны Виззи"}, [51]={npc="Хозяйка таверны Виззи", tgt="Хозяйка таверны Виззи", desc="Отнесите почту обратно на вершину Хиджала и сдайте."}, [52]={to="Summit of Eternity", toA="{a:16849}", desc="Вы сделаете пересадку в Оскверненных предгорьях."}, [53]={npc="Себелия", tgt="Себелия"}, [54]={npc="Марн Вечный Рог", tgt="Марн Вечный Рог"}, [55]={npc="Торон Каменное Копыто", tgt="Торон Каменное Копыто"}, [56]={npc="Тиала Белая Грива", tgt="Тиала Белая Грива"}, [57]={npc="Тиала Белая Грива", tgt="Тиала Белая Грива"}, [58]={npc="Тиала Белая Грива", tgt="Тиала Белая Грива"}, [59]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [60]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [61]={hint="Найдите семена терна в лесу на вершине горы Хиджал и принесите их Тиале Белой Гриве."}, [62]={hint="Примените посох Горы к 10 |4сектанту:сектантам:сектантам; из культа Черношипа на Вершине Вечности, чтобы снять обереги, а затем убейте их.", desc="Те же культисты считаются и для «Конца неистовства», и для «Искаженных орудий»; сначала используйте посох, затем убивайте, и делайте все три задания вместе."}, [63]={hint="Убейте 10 |4адепта:адептов:адептов; Черношипа и 10 |4дикомеченого сектанта:дикомеченых сектантов:дикомеченых сектантов;."}, [64]={hint="Добудьте крис злобного ритуалиста и отскакивающий посох Кривой Коры у членов культа Черношипа."}, [65]={hint="Соберите 5 |4большое перо:больших пера:больших перьев; гиппогрифа и 3 |4клочок:клочка:клочков; сальной шерсти химеры для Марна."}, [66]={npc="Тиала Белая Грива", tgt="Тиала Белая Грива"}, [67]={npc="Тиала Белая Грива", tgt="Тиала Белая Грива"}, [68]={npc="Тиала Белая Грива", tgt="Тиала Белая Грива"}, [69]={npc="Тиала Белая Грива", tgt="Тиала Белая Грива"}, [70]={hint="Plant thorn seeds near the inn, the storage tower, and the grouping of trees at the loyalist druid camp."}, [71]={npc="Тиала Белая Грива", tgt="Тиала Белая Грива"}, [72]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [73]={npc="Thisalee Crow", tgt="Thisalee Crow", desc="После получения сначала идите к Marn Euhorn, чтобы сдать «Ветры очищения» и взять «Помилование Archimonde» (Archimonde's Pardon); выполните оба задания за один заход."}, [74]={npc="Марн Вечный Рог", tgt="Марн Вечный Рог"}, [75]={npc="Марн Вечный Рог", tgt="Марн Вечный Рог"}, [76]={hint="Reactivate the sentinel stones north, west, and south around the Blackthorne cultists.", desc="Северный, западный и южный камни считаются отдельными целями, нужно побывать у всех трех."}, [77]={hint="Use the Enchanted Branch to release 5 wisps around Nordrassil.", desc="Освободите огонек, который уже находится под корнями, а не вызывайте его предметом на поляне. Выполните за один заход с «Помилованием Archimonde»."}, [78]={hint="Take Marn's incense and allow the smoke to ward the air around Archimonde's remains."}, [79]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [80]={npc="Тиала Белая Грива", tgt="Тиала Белая Грива"}, [81]={npc="Марн Вечный Рог", tgt="Марн Вечный Рог"}, [82]={npc="Торон Каменное Копыто", tgt="Торон Каменное Копыто"}, [83]={to="Rut'theran Village", toA="{a:702}", desc="Вы сделаете пересадки в Оскверненных предгорьях и Круговзор."}, [84]={npc="Эрелас Янтарное Небо", tgt="Эрелас Янтарное Небо"}, [85]={npc="Эрелас Янтарное Небо", tgt="Эрелас Янтарное Небо"}, [86]={text="Пройдите через портал в Деревне Рут'теран в Дарнас."}, [87]={npc="Верховный друид Фэндрал Олений Шлем", tgt="Верховный друид Фэндрал Олений Шлем"}, [88]={npc="Матренгил Медвежья Лапа", tgt="Матренгил Медвежья Лапа"}}},
    ["05-d30"] = {name="Blackmaw Hold", entrance="Азшара 1447, 38.70, 33.40 (вход в тоннель, ведущий к порталу).", pickup="При первом визите на Заставу Талрендис возьмите «Среди корней Нордрассила». Сдайте его и возьмите продолжение при следующем посещении Дарнаса. Собрав группу, идите на северо-восток от заставы к тоннелю в Азшаре. Верховный маг Времиар стоит по дороге из Южнобережья в Даларан. Если вам не по пути, пропустите.", pickupS={{"При первом визите на Заставу Талрендис возьмите «Среди корней Нордрассила»"}, {"Сдайте его и возьмите продолжение при следующем посещении Дарнаса"}, {"Собрав группу, идите на северо-восток от заставы к тоннелю в Азшаре"}, {"Верховный маг Времиар стоит по дороге из Южнобережья в Даларан"}, {"Если вам не по пути, пропустите"}}, tips={{k="動線", text="Тоннель → на нижнем ярусе соберите корневые шляпки, сумки и тотемы → убейте Костерыла и Withermaw в боковых проходах → старейшина-шаман → Варрокс."}, {k="說明", text="Для «Двух медведей» и задания на последнего босса нужна репутация «Равнодушие» у Древобрюхов. Начните с «Угрозы Легаши» у Эккаля, затем поговорите с Грозноревом, Корсой и Горном Одноглазом. Победите принца Халанокса снаружи и сдайте задание, чтобы открыть продолжение в подземелье. Зараженную Скверной плоть можно обменять на стручок у Flesh-Eating Lasher за залом старейшины-шамана, в задании «Время кормежки!».", s={{"Для «Двух медведей» и задания на последнего босса нужна репутация «Равнодушие» у Древобрюхов"}, {"Начните с «Угрозы Легаши» у Эккаля, затем поговорите с Грозноревом, Корсой и Горном Одноглазом"}, {"Победите принца Халанокса снаружи и сдайте задание, чтобы открыть продолжение в подземелье"}, {"Зараженную Скверной плоть можно обменять на стручок у Flesh-Eating Lasher за залом старейшины-шамана, в задании «Время кормежки!»"}}}}, steps={[1]={npc="Командир Песня Истины", tgt="Командир Песня Истины"}, [2]={npc="Матренгил Медвежья Лапа", tgt="Матренгил Медвежья Лапа"}, [3]={npc="Матренгил Медвежья Лапа", tgt="Матренгил Медвежья Лапа", preText="Среди корней Нордрассила"}, [4]={npc="Верховный маг Времиар", tgt="Верховный маг Времиар", tag="Необязательно"}, [5]={npc="Огтинк", tgt="Огтинк"}, [6]={npc="Эккаль", tgt="Эккаль"}, [7]={npc="Сказитель Нок", tgt="Сказитель Нок", tag="Необязательно", desc="Берите задание с репутацией не ниже «Равнодушия» у Древобрюхов."}, [8]={npc="Привратник Грознорев", tgt="Привратник Грознорев", tag="Необязательно", desc="Берите только если проходите длинную цепочку Древобрюхов.", preText="Blackmaw Counter-Offensive"}, [9]={text="Вход: Blackmaw Hold"}, [10]={hint="Добудьте 10 апексов корней Нордрассила в логове Черночревов для Матренгила Медвежьей Лапы из Дарнаса.", desc="Место: Внешняя роща и тоннель.", spot="Внешняя роща и тоннель."}, [11]={hint="Проникните в логово Черночревов, соберите 5 |4кошель:кошеля:кошелей; Черночревов и принесите Эккалю в руины Эльдарата, что в Азшаре.", desc="Место: Лагеря фурболгов по пути.", spot="Лагеря фурболгов по пути."}, [12]={hint="Найдите в крепости Черночревов тотем Урсока и тотем Урсола, а затем отнесите их Сказителю Ноку в Урсолан.", tag="Необязательно", desc="Место: После входа ищите тотемы в обоих боковых проходах.", spot="После входа ищите тотемы в обоих боковых проходах."}, [13]={hint="Принесите когти Великого Медведя и бивни Несломленного Огтинку в Азшару.", desc="Место: Убейте по одному боссу в каждом ответвлении.", spot="Убейте по одному боссу в каждом ответвлении."}, [14]={hint="Раздобудьте в логове Черночревов ритуальный тотем Черночревов.", tag="Необязательно", desc="Место: Старейшина-шаман в квартале фурболгов.", spot="Старейшина-шаман в квартале фурболгов."}, [15]={npc="Ожерелье с оперенным амулетом", npcObj=true, tag="Необязательно", desc="Подберите ожерелье и нажмите ПКМ, чтобы принять задание."}, [16]={hint="Принесите голову Варрокса Мутное Копыто привратнику Грознореву в Урсолан.", tag="Необязательно", desc="Место: Площадка последнего босса.", spot="Площадка последнего босса."}, [17]={npc="Огтинк", tgt="Огтинк"}, [18]={npc="Эккаль", tgt="Эккаль"}, [19]={npc="Сказитель Нок", tgt="Сказитель Нок", tag="Необязательно"}, [20]={npc="Привратник Грознорев", tag="Необязательно"}, [21]={npc="Унеле", tgt="Унеле", tag="Необязательно"}, [22]={npc="Матренгил Медвежья Лапа", tgt="Матренгил Медвежья Лапа"}, [23]={npc="Верховный маг Времиар", tgt="Верховный маг Времиар", tag="Необязательно"}}},
    ["04-59"] = {name="Западные Чумные земли", steps={[1]={bindA="{a:348}", desc="Используйте камень возвращения, только если он все еще привязан к Заоблачному Пику и не на перезарядке. Иначе используйте запасной маршрут на корабле: вернитесь через портал в деревню Рут'теран, летите в Аубердин, плывите сначала до Гавани Менетилов, затем по северному маршруту до Южнобережья, сойдите там и летите в лагерь Чиллвинд."}, [2]={to="Chillwind Camp", toA="{a:3197}", desc="Пропустите, если вы уже в лагере Чиллвинд. Если на карте полетов нет лагеря Чиллвинд, идите от Заоблачного Пика по горной дороге на север в Западные Чумные земли, а затем на запад до лагеря Чиллвинд."}, [3]={npc="Верховная жрица Макдонелл", tgt="Верховная жрица Макдонелл"}, [4]={npc="Флинт Тенемор", tgt="Флинт Тенемор", tag="Необязательно"}, [5]={npc="Флинт Тенемор", tgt="Флинт Тенемор", tag="Необязательно"}, [6]={npc="Верховная жрица Макдонелл", tgt="Верховная жрица Макдонелл"}, [7]={npc="Командир Ашлам Отважный Кулак", tgt="Командир Ашлам Отважный Кулак"}, [8]={npc="Алхимик Арбингтон", tgt="Алхимик Арбингтон"}, [9]={npc="Алхимик Арбингтон", tgt="Алхимик Арбингтон", desc="Фрагменты скелета начинают падать только после взятия задания; собирайте их попутно, когда бьете скелетов на Холме Печали и в Андорале."}, [10]={npc="Марлен Редпат", tgt="Марлен Редпат"}, [11]={npc="Марлен Редпат", tgt="Марлен Редпат"}, [12]={hint="Принесите Хроми обручальное кольцо Джозефа."}, [13]={hint="Принесите 15 фрагментов скелетов алхимику Арбингтону в Берег Промозглого Ветра в Западных Чумных землях."}, [14]={npc="Хроми", tgt="Хроми"}, [15]={npc="Хроми", tgt="Хроми"}, [16]={npc="Хроми", tgt="Хроми"}, [17]={hint="Принесите Анналы Дарроушира Хроми в Андорал."}, [18]={hint="Воспользуйтесь временным переместителем рядом с одним из амбаров Андорала и найдите временных паразитов."}, [19]={npc="Хроми", tgt="Хроми"}, [20]={npc="Хроми", tgt="Хроми"}, [21]={npc="Хроми", tgt="Хроми"}, [22]={hint="Найдите 5 часов Андорала, спрятанных в сундуки среди руин. Принесите их Хроми в таверну Андорала в Западных Чумных землях."}, [23]={npc="Хроми", tgt="Хроми"}, [24]={npc="Хроми", tgt="Хроми"}, [25]={to="Часовня Последней Надежды", desc="В Андорхале нет пункта полета. Сначала вернитесь пешком на юг в лагерь Промозглого Ветра и летите оттуда."}, [26]={npc="Герцог Николас Зверенхофф", tgt="Герцог Николас Зверенхофф", tag="Необязательно, Делайте с группой"}, [27]={npc="Карлин Редпат", tgt="Карлин Редпат"}, [28]={npc="Карлин Редпат", tgt="Карлин Редпат", tag="Необязательно"}, [29]={npc="Карлин Редпат", tgt="Карлин Редпат"}, [30]={npc="Бетина Биггльцинк", tgt="Бетина Биггльцинк", tag="Необязательно, Делайте с группой"}, [31]={npc="Бетина Биггльцинк", tgt="Бетина Биггльцинк", tag="Необязательно, Делайте с группой", desc="Выполните задание в следующий раз, когда группа пойдёт в крыло нежити."}, [32]={npc="Леонид Барталомей Чтимый", tgt="Леонид Барталомей Чтимый", tag="Необязательно, Делайте с группой"}, [33]={npc="Дымок ЛаРу", tgt="Дымок ЛаРу", tag="Необязательно, Делайте с группой"}, [34]={hint="Отправляйтесь в Северный дол, что в северо-восточной части Восточных Чумных земель и найдите там символ утраченной чести. После этого вернитесь к Тириону Фордрингу."}, [35]={hint="Убейте секретного агента Хамейю. С помощью ключа извлеките сокровище из кучи грязи за Криптой."}, [36]={npc="Аврора Зов Небес", tgt="Аврора Зов Небес"}, [37]={hint="Возьмите пустую банку для термитов и отправляйтесь к большим термитникам в Восточных Чумных землях. Наберите 100 термитов Восточных Чумных земель и возвращайтесь к Натаниэлю Дамаху в Лагерь Промозглого Ветра в Восточные Чумные земли."}, [38]={hint="Принести череп Хоргуса и сломанный меч Мардука Карлину Редпату в Часовню Последней Надежды.", tag="Необязательно", desc="Отдельный крюк, других целей рядом нет. Если торопитесь, пропустите."}, [39]={npc="Куча грязи", npcObj=true}, [40]={npc="Тирион Фордринг", tgt="Тирион Фордринг"}, [41]={npc="Тирион Фордринг", tgt="Тирион Фордринг"}, [42]={hint="Принесите книгу Дейвила и щит Крассена Карлину Редпату."}, [43]={hint="Отправляйтесь на пустошь Гаррона в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с путоши Гаррона."}, [44]={npc="Котел Плети", npcObj=true}, [45]={npc="Котел Плети", npcObj=true}, [46]={npc="Художница Ренфри", tgt="Художница Ренфри"}, [47]={npc="Верховная жрица Макдонелл", tgt="Верховная жрица Макдонелл"}, [48]={npc="Алхимик Арбингтон", tgt="Алхимик Арбингтон", desc="Продолжение ведет в Некроситет — не берите."}, [49]={npc="Командир Ашлам Отважный Кулак", tgt="Командир Ашлам Отважный Кулак"}, [50]={npc="Командир Ашлам Отважный Кулак", tgt="Командир Ашлам Отважный Кулак"}, [51]={npc="Натаниэль Дамах", tgt="Натаниэль Дамах"}, [52]={npc="Натаниэль Дамах", tgt="Натаниэль Дамах"}, [53]={npc="Термитная бочка", npcObj=true}, [54]={npc="Термитная бочка", npcObj=true}, [55]={hint="Выпустите термитов с Чумных земель на лесопилке Северного Кряжа и возвращайтесь к Натаниэлю Дамаху в Лагерь Промозглого Ветра в Западные Чумные земли."}, [56]={npc="Криста Чернотень", tgt="Криста Чернотень"}, [57]={hint="Убейте 2 медиков, 2 охотников, 2 волхвов и 2 рыцарей Алого ордена и вернитесь к Кристе Чернотени в Западных Чумных землях."}, [58]={npc="Криста Чернотень", tgt="Криста Чернотень"}, [59]={npc="Криста Чернотень", tgt="Криста Чернотень"}, [60]={hint="Убейте охотника Радли и кавалериста Даргена и вернитесь к Кристе Чернотени в Западные Чумные земли."}, [61]={npc="Криста Чернотень", tgt="Криста Чернотень"}, [62]={npc="Криста Чернотень", tgt="Криста Чернотень"}, [63]={hint="Проберитесь в Дольный Очаг и найдите возвышенность, с которой открывается вид на весь город. Оцените силы Алого ордена и вернитесь к Кристе Чернотени в Западных Чумных землях.", desc="Координаты приблизительные. У входа и у башни стоят стражи Алого крестового похода; тяните их по одному."}, [64]={npc="Криста Чернотень", tgt="Криста Чернотень"}, [65]={npc="Натаниэль Дамах", tgt="Натаниэль Дамах"}, [66]={to="Часовня Последней Надежды", desc="Вы уже в Лагере Промозглого Ветра — идите прямо к распорядителю полетов."}, [67]={npc="Карлин Редпат", tgt="Карлин Редпат", tag="Необязательно"}, [68]={npc="Карлин Редпат", tgt="Карлин Редпат"}, [69]={to="Стальгорн"}, [70]={npc="Королевский историк Аркессон", tgt="Королевский историк Аркессон"}, [71]={to="Stormwind"}, [72]={npc="Королевский представитель Батрилор", tgt="Королевский представитель Батрилор"}, [73]={npc="Королевский представитель Батрилор", tgt="Королевский представитель Батрилор"}, [74]={npc="Старушка Эмма", tgt="Старушка Эмма"}, [75]={npc="Верховный лорд Болвар Фордрагон", tgt="Верховный лорд Болвар Фордрагон", tag="Необязательно"}, [76]={npc="Мастер Матиас Шоу", tgt="Мастер Матиас Шоу", tag="Необязательно"}, [77]={npc="Мастер Матиас Шоу", tgt="Мастер Матиас Шоу", tag="Необязательно"}, [78]={npc="Мастер Матиас Шоу", tgt="Мастер Матиас Шоу", tag="Необязательно"}, [79]={to="Lakeshire", toA="{a:69}", tag="Необязательно", desc="Идите в Приозерье, только если у вас есть «Подлинные хозяева»; если нет, летите из Штормграда прямо в Дозор Моргана."}, [80]={npc="Мировой судья Соломон", tgt="Мировой судья Соломон"}, [81]={npc="Мировой судья Соломон", tgt="Мировой судья Соломон"}, [82]={to="Morgan's Vigil", toA="{a:2418}"}, [83]={npc="Маршал Максвелл", tgt="Маршал Максвелл"}, [84]={npc="Маршал Максвелл", tgt="Маршал Максвелл"}, [85]={npc="Орелиус", tgt="Орелиус", tag="Необязательно"}, [86]={hint="Поговорите с Джоном-Оборванцем и узнайте о судьбе маршала Виндзора. По выполнении задания вернитесь к маршалу Максвеллу."}, [87]={hint="Отнесите голову Гор'теша на вершину скалы Молота Ужаса. Поищите кучу рыхлой земли и воткните в нее пику.", tag="Необязательно", desc="Отдельный крюк, других целей рядом нет. Если торопитесь, пропустите."}, [88]={npc="Маршал Максвелл", tgt="Маршал Максвелл"}, [89]={npc="Орелиус", tgt="Орелиус", tag="Необязательно"}, [90]={text="Еще не 60? Пройдите один раз Глубины Черной горы. Если мало, фармите Стратхольм или Некроситет."}}},
    ["05-d29"] = {name="Терраса Создателя", entrance="Кратер Ун'Горо 1449, 48.10, 6.10 (ориентир снаружи сооружения титанов).", pickup="На 55-м уровне найдите Ториуса в Зале Исследователей Стальгорна. Если при визите в Стальгорн после Ун'Горо еще нет 55-го уровня, возьмите задания в следующий приезд. Переплывите на другой континент и поднимитесь на север от Укрытия Маршалла ко входу.", pickupS={{"На 55-м уровне найдите Ториуса в Зале Исследователей Стальгорна"}, {"Если при визите в Стальгорн после Ун'Горо еще нет 55-го уровня, возьмите задания в следующий приезд"}, {"Переплывите на другой континент и поднимитесь на север от Укрытия Маршалла ко входу"}}, tips={{k="動線", text="Дневник у первого пруда → отметьте ориентиры и убивайте равазавров → убейте Venomridge → проверьте отметки и страницы."}, {k="說明", text="Все три задания можно выполнить за один заход. Кристаллы силы нужны, только если группа хочет убить дополнительных боссов.", s={{"Все три задания можно выполнить за один заход"}, {"Кристаллы силы нужны, только если группа хочет убить дополнительных боссов"}}}}, steps={[1]={npc="Куратор Ториус", tgt="Куратор Ториус"}, [2]={npc="Куратор Ториус", tgt="Куратор Ториус"}, [3]={text="Вход: Терраса Создателя"}, [4]={npc="Partially Digested Journal", npcObj=true, desc="В подземелье нажмите на дневник в лагере у первого пруда."}, [5]={hint="Collect 15 Partially Digested Journal Pages from the Shaper's Terrace.", desc="Место: По тому же пути, где нужно убивать равазавров.", spot="По тому же пути, где нужно убивать равазавров."}, [6]={hint="Убейте 6 равазавров-матриархов, 9 сталешкурых равазавров и Ядогорба на Террасе Создателя.", desc="Место: Стаи равазавров встречаются по пути.", spot="Стаи равазавров встречаются по пути."}, [7]={hint="Найдите интересные достопримечательности на террасе Создателя и отметьте их на исследовательской карте.", desc="Место: Примените набор картографа по одному разу у каждого из пяти ориентиров.", spot="Примените набор картографа по одному разу у каждого из пяти ориентиров."}, [8]={npc="Куратор Ториус", tgt="Куратор Ториус"}, [9]={npc="Куратор Ториус", tgt="Куратор Ториус"}, [10]={npc="Куратор Ториус", tgt="Куратор Ториус"}}},
    ["05-d28"] = {name="Некроситет", entrance="Западные Чумные земли 1422, 68.90, 72.80 (подземный вход на Каэр Дарроу).", pickup="Поговорите с Вэлдоном в лагере Промозглого Ветра, с Бетиной в часовне Последней Надежды, а перед входом — с Евой у моста на Каэр Дарроу. Если уже ушли из Западных Чумных земель, летите обратно в лагерь Промозглого Ветра.", pickupS={{"Поговорите с Вэлдоном в лагере Промозглого Ветра, с Бетиной в часовне Последней Надежды, а перед входом — с Евой у моста на Каэр Дарроу"}, {"Если уже ушли из Западных Чумных земель, летите обратно в лагерь Промозглого Ветра"}}, tips={{k="動線", text="Крыльцо → грамоты в первом зале → комната дракончиков → Громоклин → Рас Снегошепот → шесть нижних комнат → Темный магистр Гандлинг."}, {k="說明", text="Для двери хватит одной Отмычки на группу. В Прибамбасск и на Огненный венец отправляйтесь, только если делаете свой ключ. В первый заход займитесь грамотами, дракончиками и профессором. Для «Рассветного гамбита» нужны два забега за яйцами на верхний ярус Пика Черной горы. Длинная цепочка Снегошепота также ведет в Стромгард и квартал нежити Стратхольма.", s={{"Для двери хватит одной Отмычки на группу"}, {"В Прибамбасск и на Огненный венец отправляйтесь, только если делаете свой ключ"}, {"В первый заход займитесь грамотами, дракончиками и профессором"}, {"Для «Рассветного гамбита» нужны два забега за яйцами на верхний ярус Пика Черной горы"}, {"Длинная цепочка Снегошепота также ведет в Стромгард и квартал нежити Стратхольма"}}}}, steps={[1]={npc="Вэлдон Баров", tgt="Вэлдон Баров"}, [2]={npc="Бетина Биггльцинк", tgt="Бетина Биггльцинк"}, [3]={npc="Ева Саркофф", tgt="Ева Саркофф"}, [4]={npc="Командир Ашлам Отважный Кулак", tgt="Командир Ашлам Отважный Кулак", tag="Необязательно"}, [5]={hint="Убейте 10 скелетов-свежевателей и 10 слюнявых вурдалаков на холме Печали.", tag="Необязательно"}, [6]={npc="Командир Ашлам Отважный Кулак", tgt="Командир Ашлам Отважный Кулак", tag="Необязательно"}, [7]={npc="Командир Ашлам Отважный Кулак", tgt="Командир Ашлам Отважный Кулак", tag="Необязательно"}, [8]={hint="Отметьте все башни Андорала при помощи сигнального факела; задействовать факел следует, находясь в дверном проеме каждой из башен.", tag="Необязательно"}, [9]={npc="Командир Ашлам Отважный Кулак", tgt="Командир Ашлам Отважный Кулак", tag="Необязательно"}, [10]={npc="Командир Ашлам Отважный Кулак", tgt="Командир Ашлам Отважный Кулак", tag="Необязательно"}, [11]={npc="Алхимик Арбингтон", tgt="Алхимик Арбингтон", tag="Необязательно"}, [12]={npc="Алхимик Арбингтон", tgt="Алхимик Арбингтон", tag="Необязательно"}, [13]={hint="Принесите 15 фрагментов скелетов алхимику Арбингтону в Берег Промозглого Ветра в Западных Чумных землях.", tag="Необязательно"}, [14]={npc="Алхимик Арбингтон", tgt="Алхимик Арбингтон", tag="Необязательно"}, [15]={npc="Алхимик Арбингтон", tgt="Алхимик Арбингтон", tag="Необязательно", preText="Фрагменты скелетов"}, [16]={hint="Отнесите Кринкелю Сталлинну из Прибамбасска прочные фрагменты скелета и 15 золотых монет.", tag="Необязательно"}, [17]={npc="Кринкель Сталлер", tgt="Кринкель Сталлер", tag="Необязательно"}, [18]={npc="Кринкель Сталлер", tgt="Кринкель Сталлер", tag="Необязательно"}, [19]={hint="Отнесите форму для отливки отмычек и 2 ториевых слитка на вершину Вулкана Огненного Венца в Кратере Ун'Горо. Окуните форму для отливки отмычки в озеро лавы. Получится недоделанная отмычка.", tag="Необязательно"}, [20]={npc="Алхимик Арбингтон", tgt="Алхимик Арбингтон", tag="Необязательно"}, [21]={npc="Алхимик Арбингтон", tgt="Алхимик Арбингтон", tag="Необязательно"}, [22]={hint="Убейте Аража Призывателя отнесите его скарабея алхимику Арбингтону на Берег Промозглого Ветра, что в Западных Чумных землях.", tag="Необязательно"}, [23]={npc="Алхимик Арбингтон", tgt="Алхимик Арбингтон", tag="Необязательно"}, [24]={npc="Алхимик Арбингтон", tgt="Алхимик Арбингтон", tag="Необязательно"}, [25]={npc="Алхимик Арбингтон", tgt="Алхимик Арбингтон", tag="Необязательно"}, [26]={text="Требуется: Рассветный гамбит", tag="Необязательно"}, [27]={text="Требуется: Рас Снегошепот - лич", tag="Необязательно"}, [28]={text="Вход: Некроситет"}, [29]={hint="Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Велдону Барову.", desc="Место: На столах или скамьях в комнатах.", spot="На столах или скамьях в комнатах."}, [30]={hint="Убейте 20 зачумленных детенышей дракона, затем возвращайтесь к Бетине Биггльцинк в Часовню Последней Надежды.", desc="Место: От крыльца пройдите через зал призыва в комнату дракончиков.", spot="От крыльца пройдите через зал призыва в комнату дракончиков."}, [31]={npc="Здоровая чешуя дракона", npcObj=true, tag="Необязательно"}, [32]={hint="Найдите в Некроситете Джандис Баров и уничтожьте ее. Заберите мешок ужасов Крастинова. Отнесите мешок Еве Саркофф.", tag="Необязательно", desc="Место: В затопленном склепе под первым залом.", spot="В затопленном склепе под первым залом."}, [33]={hint="Вернитесь в Некроситет с кровью невинных. Найдите балкон и вылейте кровь в жаровню. На зов явится Киртонос.", tag="Необязательно", desc="Место: На крыльце подземелья.", spot="На крыльце подземелья."}, [34]={hint="Отнесите \"Рассветный гамбит\" в Демонстрационную комнату в Некроситете. Уничтожьте Вектуса и возвращайтесь к Бетине Биггльцинк.", tag="Необязательно", desc="Место: Убейте Громоклина, заберите ключ и вернитесь в смотровой зал.", spot="Убейте Громоклина, заберите ключ и вернитесь в смотровой зал."}, [35]={hint="Отыщите в Некроситете Раса Снегошепота. Найдя его, воспользуйтесь Книгой Души против его посмертного облика. Если удастся превратить Раса в смертного, убейте его и заберите человеческую голову Раса Снегошепота. Отнесите голову мировому судье Мардуку.", tag="Необязательно", desc="Место: В алхимической лаборатории перед последними шестью комнатами.", spot="В алхимической лаборатории перед последними шестью комнатами."}, [36]={hint="Найдите в Некроситете доктора Теолена Крастинова. Убейте его, затем сожгите останки Евы и Люсьена Саркофф. Выполнив задание, возвращайтесь к Еве Саркофф.", desc="Место: Оба тела находятся в комнате профессора.", spot="Оба тела находятся в комнате профессора."}, [37]={npc="Ева Саркофф", tgt="Ева Саркофф"}, [38]={npc="Ева Саркофф", tgt="Ева Саркофф", tag="Необязательно", desc="Убейте Джандис в следующий заход.", preText="Доктор Теолен Крастинов - Мясник"}, [39]={npc="Ева Саркофф", tgt="Ева Саркофф", tag="Необязательно"}, [40]={npc="Ева Саркофф", tgt="Ева Саркофф", tag="Необязательно", desc="Если та же группа продолжает, вернитесь на крыльцо для призыва.", preText="Мешок ужасов Крастинова"}, [41]={npc="Ева Саркофф", tgt="Ева Саркофф", tag="Необязательно"}, [42]={npc="Мировой судья Мардук", tgt="Мировой судья Мардук", tag="Необязательно", desc="Наденьте Сущность привидения, чтобы увидеть магистрата."}, [43]={npc="Вэлдон Баров", tgt="Вэлдон Баров"}, [44]={npc="Бетина Биггльцинк", tgt="Бетина Биггльцинк"}, [45]={npc="Бетина Биггльцинк", tgt="Бетина Биггльцинк", tag="Необязательно"}, [46]={npc="Бетина Биггльцинк", tgt="Бетина Биггльцинк", tag="Необязательно"}}},
    ["05-d27"] = {name="Верхняя часть пика Черной горы", entrance="Пылающие степи 1428, 29.40, 38.30 (южный вход в Черную гору).", pickup="По маршруту Альянса в Пылающих степях возьмите задания в Дозоре Моргана и у Пламенеющего Стяга. Если не хватает уровня, возьмите их перед сбором группы. После нижнего яруса сдайте «Приказ генерала Драккисата» в Дозоре Моргана и возьмите задание на последнего босса верхнего яруса.", pickupS={{"По маршруту Альянса в Пылающих степях возьмите задания в Дозоре Моргана и у Пламенеющего Стяга"}, {"Если не хватает уровня, возьмите их перед сбором группы"}, {"После нижнего яруса сдайте «Приказ генерала Драккисата» в Дозоре Моргана и возьмите задание на последнего босса верхнего яруса"}}, tips={{k="動線", text="Общий портал → подъем и запертая дверь слева → Созерцатель Углей → гнездовье → арена → Драккисат."}, {k="說明", text="Вход общий с нижним ярусом. Дверь наверх откроет игрок с Печатью вознесения. Два задания на яйца делаются за два захода, а продолжение ведет в Некроситет.", s={{"Вход общий с нижним ярусом"}, {"Дверь наверх откроет игрок с Печатью вознесения"}, {"Два задания на яйца делаются за два захода, а продолжение ведет в Некроситет"}}}}, steps={[1]={npc="Майра Светлое Крыло", tgt="Майра Светлое Крыло"}, [2]={text="Требуется: Приказ генерала Драккисата", tag="Необязательно"}, [3]={text="Требуется: Око дракона", tag="Необязательно"}, [4]={npc="Маршал Максвелл", tgt="Маршал Максвелл", tag="Необязательно", preText="Приказ генерала Драккисата"}, [5]={npc="Тинки Кипеллер", tgt="Тинки Кипеллер", tag="Необязательно"}, [6]={hint="Принесите 8 сущностей детенышей драконов и Драко-инкарцинатор 900 Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях.", tag="Необязательно"}, [7]={npc="Тинки Кипеллер", tgt="Тинки Кипеллер", tag="Необязательно"}, [8]={npc="Тинки Кипеллер", tgt="Тинки Кипеллер", tag="Необязательно"}, [9]={npc="Фелнок Сталлист", tgt="Фелнок Сталлист", tag="Необязательно"}, [10]={npc="Фелнок Сталлист", tgt="Фелнок Сталлист", tag="Необязательно"}, [11]={hint="Принесите 8 безупречных рогов стылодыха Фелноку Сталлисту.", tag="Необязательно"}, [12]={npc="Фелнок Сталлист", tgt="Фелнок Сталлист", tag="Необязательно"}, [13]={npc="Фелнок Сталлист", tgt="Фелнок Сталлист", tag="Необязательно"}, [14]={npc="Тинки Кипеллер", tgt="Тинки Кипеллер", tag="Необязательно"}, [15]={npc="Тинки Кипеллер", tgt="Тинки Кипеллер", tag="Необязательно", preText="Возвращение к Тинки"}, [16]={npc="Тинки Кипеллер", tgt="Тинки Кипеллер", tag="Необязательно", desc="Понадобится еще один забег.", preText="Заморозка яйца"}, [17]={npc="Лоракс", tgt="Лоракс", tag="Необязательно", desc="Нужно только кузнецам."}, [18]={npc="Лоракс", tgt="Лоракс", tag="Необязательно"}, [19]={npc="Лоракс", tgt="Лоракс", tag="Необязательно", desc="Нужно только кузнецам.", preText="История Лоракса"}, [20]={npc="Халех", tgt="Халех", tag="Необязательно", desc="Берите в подземелье, если делаете цепочку доступа к Ониксии.", preText="Око дракона"}, [21]={text="Вход: Верхняя часть пика Черной горы"}, [22]={hint="Принесите пряжку Роковой оснастки Майре Светлое Крыло в Пылающие степи.", desc="Место: Пройдите мимо Созерцателя Углей и найдите ящик в гнездовье.", spot="Пройдите мимо Созерцателя Углей и найдите ящик в гнездовье."}, [23]={hint="Испытайте прототип яйцехладоскопа на одном из яиц в Гнездовье.", tag="Необязательно", desc="Место: Гнездовье на верхнем ярусе.", spot="Гнездовье на верхнем ярусе."}, [24]={hint="Принесите 8 драконьих яиц и устройство-коллекционер Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях.", tag="Необязательно", desc="Место: Гнездовье на верхнем ярусе.", spot="Гнездовье на верхнем ярусе."}, [25]={hint="Отправляйтесь на пик Черной горы и найдите Горалука Треснувшую Наковальню. Убейте его, а потом воткните в труп окровавленную пику. Таким образом пика вытянет его душу и окрасится ей.", tag="Необязательно", desc="Место: Кузня на верхнем ярусе.", spot="Кузня на верхнем ярусе."}, [26]={npc="Пип Смышлен", tgt="Пип Смышлен", tag="Необязательно", desc="Поговорите с Пипом после боя на арене."}, [27]={npc="Ауби", tgt="Ауби", tag="Необязательно", desc="За ареной найдите Ауби на верхнем балконе."}, [28]={hint="Отправьтесь на пик Черной горы и устраните генерала Драккисата. По выполнении задания вернитесь к маршалу Максвеллу.", tag="Необязательно", desc="Место: Комната последнего босса верхнего яруса.", spot="Комната последнего босса верхнего яруса."}, [29]={hint="Добудьте кровь могучего черного дракона у генерала Драккисата.", tag="Необязательно", desc="Место: Комната последнего босса верхнего яруса.", spot="Комната последнего босса верхнего яруса."}, [30]={npc="Майра Светлое Крыло", tgt="Майра Светлое Крыло"}, [31]={npc="Майра Светлое Крыло", tgt="Майра Светлое Крыло", tag="Необязательно"}, [32]={npc="Граф Ремингтон Риджвелл", tgt="Граф Ремингтон Риджвелл", tag="Необязательно"}, [33]={npc="Маршал Максвелл", tgt="Маршал Максвелл", tag="Необязательно"}, [34]={npc="Тинки Кипеллер", tgt="Тинки Кипеллер", tag="Необязательно"}, [35]={npc="Тинки Кипеллер", tgt="Тинки Кипеллер", tag="Необязательно"}, [36]={npc="Тинки Кипеллер", tgt="Тинки Кипеллер", tag="Необязательно", preText="Сбор яиц"}, [37]={npc="Леонид Барталомей Чтимый", tgt="Леонид Барталомей Чтимый", tag="Необязательно"}, [38]={npc="Леонид Барталомей Чтимый", tgt="Леонид Барталомей Чтимый", tag="Необязательно", preText="Леонид Барталомей"}, [39]={npc="Бетина Биггльцинк", tgt="Бетина Биггльцинк", tag="Необязательно"}, [40]={npc="Лоракс", tgt="Лоракс", tag="Необязательно"}, [41]={npc="Малифой Черномолот", tgt="Малифой Черномолот", tag="Необязательно"}, [42]={npc="Халех", tgt="Халех", tag="Необязательно"}, [43]={npc="Халех", tgt="Халех", tag="Необязательно"}}},
    ["05-d13"] = {name="Стратхольм", entrance="Восточные Чумные земли 26.52, 10.36 (главные ворота Алого ордена; служебный вход в квартал нежити на 43.50, 19.40)", steps={[1]={text="Летите в лагерь Промозглого Ветра, если вам нужно получить задание «Любовь и семья» у художницы на Каэр Дарроу в Западных Чумных землях. Если задание уже у вас или нужны только задания в часовне, сразу встречайтесь с группой."}, [2]={npc="Тирион Фордринг", tgt="Тирион Фордринг", tag="Подготовка к подземелью"}, [3]={hint="Убейте 20 карликовых чумных псов, 5 чумных псов и 5 бесноватых чумных псов. По выполнении задания вернитесь к Тириону Фордрингу.", tag="Подготовка к подземелью"}, [4]={npc="Тирион Фордринг", tgt="Тирион Фордринг", tag="Подготовка к подземелью"}, [5]={npc="Тирион Фордринг", tgt="Тирион Фордринг", tag="Подготовка к подземелью"}, [6]={hint="Убейте 30 чумных нетопырей и вернитесь к Тириону Фордрингу.", tag="Подготовка к подземелью"}, [7]={npc="Тирион Фордринг", tgt="Тирион Фордринг", tag="Подготовка к подземелью"}, [8]={npc="Тирион Фордринг", tgt="Тирион Фордринг", tag="Подготовка к подземелью"}, [9]={hint="Найдите личинок-падальщиков и падальщиков-пожирателей. Убейте побольше и наберите из мяса. Возвращайтесь к Тириону Фордрингу, когда накопите 15 кусков мяса червей-трупоедов.", tag="Подготовка к подземелью"}, [10]={npc="Тирион Фордринг", tgt="Тирион Фордринг", tag="Подготовка к подземелью"}, [11]={npc="Тирион Фордринг", tgt="Тирион Фордринг", tag="Подготовка к подземелью"}, [12]={hint="Выслушайте Тириона Фордринга.", tag="Подготовка к подземелью"}, [13]={npc="Тирион Фордринг", tgt="Тирион Фордринг", tag="Подготовка к подземелью"}, [14]={npc="Тирион Фордринг", tgt="Тирион Фордринг", tag="Подготовка к подземелью"}, [15]={hint="Отправляйтесь в Крипту - в самой южной части Восточных Чумных земель - и добудьте молот Таэлана. Отнесите его Тириону Фордрингу.", tag="Подготовка к подземелью"}, [16]={npc="Тирион Фордринг", tgt="Тирион Фордринг", tag="Подготовка к подземелью"}, [17]={npc="Тирион Фордринг", tgt="Тирион Фордринг", tag="Подготовка к подземелью"}, [18]={hint="Отправляйтесь в Северный дол, что в северо-восточной части Восточных Чумных земель и найдите там символ утраченной чести. После этого вернитесь к Тириону Фордрингу.", tag="Подготовка к подземелью"}, [19]={npc="Тирион Фордринг", tgt="Тирион Фордринг", tag="Подготовка к подземелью"}, [20]={npc="Тирион Фордринг", tgt="Тирион Фордринг", tag="Подготовка к подземелью"}, [21]={npc="Художница Ренфри", tgt="Художница Ренфри", tag="Подготовка к подземелью"}, [22]={npc="Художница Ренфри", tgt="Художница Ренфри"}, [23]={npc="Герцог Николас Зверенхофф", tgt="Герцог Николас Зверенхофф", tag="Необязательно, Делайте с группой"}, [24]={npc="Бетина Биггльцинк", tgt="Бетина Биггльцинк", tag="Необязательно, Делайте с группой"}, [25]={npc="Леонид Барталомей Чтимый", tgt="Леонид Барталомей Чтимый", tag="Необязательно, Делайте с группой"}, [26]={npc="Дымок ЛаРу", tgt="Дымок ЛаРу", tag="Необязательно, Делайте с группой"}, [27]={text="От часовни Последней Надежды отправляйтесь с группой в Стратхольм. Метка показывает главные ворота к рынку и бастиону Алого ордена. Если идёте только в квартал нежити, встретьтесь у восточного служебного входа с тем, кто может его открыть."}, [28]={text="Вход: Стратхольм"}, [29]={hint="Отправляйтесь на север, в Стратхольм. Обыщите брошенные ящики с припасами и соберите 5 мер святой воды Стратхольма. Возвращайтесь к Леониду Бартоломею Чтимому, как только воды будет достаточно.", tag="Необязательно, Делайте с группой", spot="Осматривайте ящики с припасами на улицах обоих кварталов. Оставьте пять флаконов стра́тхольмской святой воды для сдачи и восполните запас, если потратите часть."}, [30]={hint="Принесите 20 препаратов чумной плоти из Стратхольма Бетине Биггльцинк. Предположительно, любая тварь из Стратхольма сойдет за препарат.", tag="Необязательно, Делайте с группой", spot="Собирайте образцы чумной плоти по пути с группой в любом из двух кварталов. Оставьте собранное до следующего захода и вернитесь в часовню, когда наберёте двадцать."}, [31]={hint="Найдите табачную лавку Эзры Гримма в Стратхольме, отыщите в ней коробку отличного табака Эзры Гримма и принесите ее Дымку ЛаРу.", tag="Необязательно, Делайте с группой", spot="В квартале Алого ордена идите от главных ворот на рынок. Откройте ящик у табачной лавки, победите Эзру Гримма и заберите коробку его отборного табака. Если группа идёт только в квартал нежити, оставьте это задание на другой раз."}, [32]={hint="Отправляйтесь в Статхольм в северную часть Чумных земель. Найдите в Бастионе Алого ордена картину \"Символ семейной любви\", спрятанную за другой, изображающей две луны нашего мира.", spot="Сначала победите Галфорда. Прежде чем сжигать архив, спросите у группы, все ли, кому нужна картина «Символ семейной любви», забрали её из-за картины с двумя лунами. Если она никому не нужна, архив можно сжечь сразу."}, [33]={hint="Отправляйтесь в Стратхольм и отыщите архивариуса Галфорда из Алого ордена. Убейте его и сожгите архив Алых.", tag="Необязательно, Делайте с группой", spot="Сначала победите Галфорда. Прежде чем сжигать архив, спросите у группы, все ли, кому нужна картина «Символ семейной любви», забрали её из-за картины с двумя лунами. Если она никому не нужна, архив можно сжечь сразу."}, [34]={npc="Голова Бальназара", npcObj=true, tag="Необязательно, Делайте с группой", desc="Сдав задание «Архивариус», щёлкните правой кнопкой мыши по голове, которую вы сами подобрали с Балназара."}, [35]={hint="Отправляйтесь в Стратхольм и исследуйте зиккураты. Доставьте сведения о Плети Бетине Биггльцинк.", tag="Необязательно, Делайте с группой", spot="Обыщите три зиккурата крыла нежити. Найдите маленький сундук и лично заберите документы."}, [36]={hint="Отправляйтесь в Стратхольм и убейте барона Ривендера. Принесите его голову герцогу Николасу Зверенхоффу.", tag="Необязательно, Делайте с группой", spot="Пройдите через бойню в крыле нежити, победите барона Ривендера и лично заберите его голову."}, [37]={hint="Стреляйте в призраков и неупокоенных на улицах Стратхольма из излучателя Эгана. Когда душа вырвется из призрачной оболочки, выстрелите в нее еще раз, и она обретет свободу.", tag="Необязательно, Делайте с группой", spot="Найдите призрачных горожан на улицах Стратхольма. Примените бластер Эгана сначала к горожанину, затем к появившейся душе. Освободите пятнадцать душ."}, [38]={npc="Тирион Фордринг", tgt="Тирион Фордринг", desc="Тирион Фордринг находится в хижине на берегу реки в западной части Восточных Чумных земель."}, [39]={text="Возвращайтесь в часовню Последней Надежды. Если у вас есть картина «Символ семейной любви», сначала отнесите её Тириону на западном берегу реки в Восточных Чумных землях, а затем вернитесь в часовню."}, [40]={npc="Герцог Николас Зверенхофф", tgt="Герцог Николас Зверенхофф", tag="Необязательно, Делайте с группой"}, [41]={npc="Голова Бальназара", npcObj=true, tag="Необязательно, Делайте с группой", desc="Сдав задание «Архивариус», щёлкните правой кнопкой мыши по голове, которую вы сами подобрали с Балназара."}, [42]={npc="Герцог Николас Зверенхофф", tgt="Герцог Николас Зверенхофф", tag="Необязательно, Делайте с группой"}, [43]={npc="Герцог Николас Зверенхофф", tgt="Герцог Николас Зверенхофф", tag="Необязательно, Делайте с группой", desc="Выполните задание в следующий раз, когда группа пойдёт в крыло нежити."}, [44]={npc="Герцог Николас Зверенхофф", tgt="Герцог Николас Зверенхофф", tag="Необязательно, Делайте с группой"}, [45]={npc="Бетина Биггльцинк", tgt="Бетина Биггльцинк", tag="Необязательно, Делайте с группой"}, [46]={npc="Бетина Биггльцинк", tgt="Бетина Биггльцинк", tag="Необязательно, Делайте с группой", desc="Выполните задание в следующий раз, когда группа пойдёт в крыло нежити."}, [47]={npc="Бетина Биггльцинк", tgt="Бетина Биггльцинк", tag="Необязательно, Делайте с группой"}, [48]={npc="Леонид Барталомей Чтимый", tgt="Леонид Барталомей Чтимый", tag="Необязательно, Делайте с группой"}, [49]={npc="Дымок ЛаРу", tgt="Дымок ЛаРу", tag="Необязательно, Делайте с группой"}, [50]={npc="Эган", tgt="Эган", tag="Необязательно, Делайте с группой"}, [51]={to="Стальгорн"}}},
    ["05-d12"] = {name="Глубины Черной Горы", entrance="Тлеющее ущелье 34.80, 85.30", pickup="Берите «Каран Могучий Молот», как только сдадите «Дымящиеся руины Тауриссана» в Стальгорне. Задания Пылающих степей берут в районе Дозора Моргана.", pickupS={{"Берите «Каран Могучий Молот», как только сдадите «Дымящиеся руины Тауриссана» в Стальгорне"}, {"Задания Пылающих степей берут в районе Дозора Моргана"}}, steps={[1]={npc="Королевский историк Аркессон", tgt="Королевский историк Аркессон", tag="Подготовка к подземелью"}, [2]={hint="Узнайте от королевского историка Аркессона историю Тауриссана.", tag="Подготовка к подземелью"}, [3]={npc="Королевский историк Аркессон", tgt="Королевский историк Аркессон", tag="Подготовка к подземелью"}, [4]={npc="Королевский историк Аркессон", tgt="Королевский историк Аркессон", tag="Подготовка к подземелью"}, [5]={hint="Пойдите в руины Тауриссана в Пылающих степях и добудьте информацию из таурисанских реликвий. Вернитесь к королевскому историку Аркессону.", tag="Подготовка к подземелью"}, [6]={npc="Королевский историк Аркессон", tgt="Королевский историк Аркессон", tag="Подготовка к подземелью"}, [7]={npc="Король Магни Бронзобород", tgt="Король Магни Бронзобород", desc="Предварительное задание — «Руины Таурисса» (Дымящиеся руины Тауриссана); возьмите его после сдачи в Стальгорне на Западные Чумные земли главы 04."}, [8]={npc="Рагнар Громовар", tgt="Рагнар Громовар", tag="Необязательно", desc="Сдавайте, только когда возьмете его в Выжженных землях."}, [9]={npc="Рагнар Громовар", tgt="Рагнар Громовар", tag="Необязательно", desc="Каранос не по пути; пропустите, если не хотите делать крюк."}, [10]={npc="Орелиус", tgt="Орелиус"}, [11]={npc="Максворт Суперблеск", tgt="Максворт Суперблеск"}, [12]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез", tag="Подготовка к подземелью"}, [13]={hint="Выслушайте Веларока Ветрореза.", tag="Подготовка к подземелью"}, [14]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез", tag="Подготовка к подземелью"}, [15]={npc