    [4740] = {n="РАЗЫСКИВАЕТСЯ: Глубомрак!", d="Найдите и убейте мурлока, известного как Глубомрак. Предполагается, что это существо охраняет и защищает хижины мурлоков в поселении к югу от Аубердина, у воды.\nО смерти Глубомрака доложите часовому Глинде Нал'Шии в Аубердине.", tgo={{"Глубомрак"}}},
    [4742] = {n="Печать Вознесения", d="Найдите самоцвет Тлеющего Терновника, самоцвет Черной Вершины и самоцвет Кровавого Топора. Верните их Ваелану вместе с простой печатью Вознесения.\nКамни могут быть у трех генералов: у воеводы Вуна из клана Тлеющего Терновника, у вождя Омокка из клана Черной Вершины и у повелителя Змейталака из клана Кровавого Топора.", tgo={{"Вождь Омокк"}, {"Воевода Вун"}, {"Властитель Змейталак"}, {"Рубака из легиона Изрубленного Щита", "Караульный из легиона Изрубленного Щита", "Послушник из легиона Изрубленного Щита", "Интендант из легиона Изрубленного Щита", "Легионер из легиона Изрубленного Щита", "Чароплет из легиона Изрубленного Щита", "Вождь Омокк", "Боевой маг из клана Черной Вершины"}}},
    [4743] = {n="Печать Вознесения", d="Идите в Драконьи топи в Пылевых топях. Найдите Огнебора и бейте его, не жалея, чтобы сломить его волю.\nКак только воля великого зверя ослабнет, надо немедленно положить перед ним заготовку печати Вознесения и воспользоваться сферой Энергии дракона, чтобы подчинить себе его разум и направить его пламя на заготовку.", objs={"Закаленная печать Вознесения"}},
