    [4762] = {n="Река Скалистая", d="Отправляйтесь на север от Аубердина, к первому водопаду вверх по реке Скалистой, и там возьмите пробу.\nС пробой воды Скалистой реки возвращайтесь в Аубердин к Тандрису Ветропряду.", objs={"Cliffspring River Waterfall"}},
    [4763] = {n="Порабощенные фурболги Чернолесья", d="Наполните пустую чашу очищения из лунного колодца Аубердина.\nСоберите образцы фруктов, орехов и зерна в расположенных на севере лагерях фурболгов.\nСмешайте все в чаше и поместите ее возле ближайшего к реке Скалистой большого костра в северном лагере, вызвав таким образом сатира.\nСнимите с него талисман порчи и принесите его Тандрису Ветропряду в Аубердин.", objs={"Демонова сума Забраксиса"}},
    [4764] = {n="Пряжка Роковой оснастки", d="Принесите пряжку Роковой оснастки Майре Светлое Крыло в Пылающие степи.", objs={"Металлический ящик Рокового Зажима"}},
