    [5343] = {n="Сокровище Баровых", d="Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Велдону Барову.", objs={"Документы на Брилл", "Документы на Каэр Дарроу", "Документы на Южнобережье", "Документы на Мельницу Таррен"}},
    [5382] = {n="Доктор Теолен Крастинов - Мясник", d="Найдите в Некроситете доктора Теолена Крастинова. Убейте его, затем сожгите останки Евы и Люсьена Саркофф. Выполнив задание, возвращайтесь к Еве Саркофф.", tgo={{"Доктор Теолен Крастинов"}, {}, {}}, objs={"Останки Ева Саркофф", "Останки Люсьена Саркофф"}},
    [5384] = {n="Киртонос Глашатай", d="Вернитесь в Некроситет с кровью невинных. Найдите балкон и вылейте кровь в жаровню. На зов явится Киртонос.\nСражайтесь как герой, не сдавайтесь! Уничтожьте Киртоноса и возвращайтесь к Еве Саркофф.", tgo={{"Киртонос Глашатай"}}},
    [5401] = {n="Жетон Серебряного Рассвета"},
    [5466] = {n="Рас Снегошепот - лич", d="Отыщите в Некроситете Раса Снегошепота. Найдя его, воспользуйтесь Книгой Души против его посмертного облика. Если удастся превратить Раса в смертного, убейте его и заберите человеческую голову Раса Снегошепота. Отнесите голову мировому судье Мардуку.", tgo={{"Рас Снегошепот"}}},
