    [5781] = {n="Символ ушедших дней", d="Отправляйтесь в Крипту - в самой южной части Восточных Чумных земель - и добудьте молот Таэлана. Отнесите его Тириону Фордрингу.", tgo={{"Меркуцио Грязежор"}}},
    [5801] = {n="Кузня Пламенного хребта", d="Отнесите форму для отливки отмычек и 2 ториевых слитка на вершину Вулкана Огненного Венца в Кратере Ун'Горо. Окуните форму для отливки отмычки в озеро лавы. Получится недоделанная отмычка.\nОтнесите недоделанную отмычку алхимику Арбингтону на Берег Промозглого Ветра в Западные Чумные земли.", objs={"Лавовое озеро Пламенного хребта"}},
    [5803] = {n="Скарабей Араджи", d="Убейте Аража Призывателя отнесите его скарабея алхимику Арбингтону на Берег Промозглого Ветра, что в Западных Чумных землях.", objs={"Оберег Араджа"}},
    [5845] = {n="Символ утраченной чести", d="Отправляйтесь в Северный дол, что в северо-восточной части Восточных Чумных земель и найдите там символ утраченной чести. После этого вернитесь к Тириону Фордрингу.", objs={"Символ утраченной чести"}},
    [5846] = {n="Символ семейной любви", d="Отправляйтесь на остров Каэр Дарроу в центральной части Чумных земель и поищите там картину."},
    [5848] = {n="Символ семейной любви", d="Отправляйтесь в Статхольм в северную часть Чумных земель. Найдите в Бастионе Алого ордена картину \"Символ семейной любви\", спрятанную за другой, изображающей две луны нашего мира.\nОтнесите картину Тириону Фордрингу.", objs={"Незаконченная картина"}},
    [5863] = {n="Поселение Песчаного Молота", d="Анди Линн из Прибамбасска просит уничтожить поселение Песчаного Молота, убив 10 громил и 10 мародеров из клана Песчаного Молота и Гор'марока Опустошителя.", tgo={{"Громила из клана Песчаного Молота"}, {"Головорез из клана Песчаного Молота"}, {"Гор'марок Опустошитель"}}},
