    [5903] = {n="Чума на вашу лесопилку!", d="Возьмите пустую банку для термитов и отправляйтесь к большим термитникам в Восточных Чумных землях. Наберите 100 термитов Восточных Чумных земель и возвращайтесь к Натаниэлю Дамаху в Лагерь Промозглого Ветра в Восточные Чумные земли.", objs={"Большой термитник"}},
    [5904] = {n="Чума на вашу лесопилку!", d="Найдите подходящее место в центре лесопилки Северного Кряжа в Западных Чумных землях и оставьте там бочонок термитов из Чумных земель."},
    [5921] = {n="Лунная поляна", d="При помощи заклинания \"Телепортация: Лунная поляна\" перенеситесь в Лунную поляну. По прибытии поговорите с Дендритом Блеском Звезд в селении Ночная Гавань."},
    [5929] = {n="Дух Великого Медведя", d="Найдите духа Великого Медведя на северо-западе Лунной поляны и усвойте все, что он расскажет вам о природе медведя. Когда уроки будут закончены, вернитесь к Дендриту Блеску Звезд в Ночную Гавань в Лунной поляне.", tgo={{"Дух Великого Медведя"}}},
    [5931] = {n="Возвращение в Дарнасс", d="Вернитесь в Дарнасс и поговорите с Матренгилом Медвежьей Лапой в анклаве Кенария."},
    [6001] = {n="Тело и дух", d="Посыпьте лунной пылью Кенария камень лунного совуха в Аубердине, чтобы вызвать Лунокогтя. Победите Лунокогтя, чтобы получить силу его тела и духа.\nЗатем поговорите с Матренгилом Медвежьей Лапой в Дарнассе.", tgo={{"Дух Лунокогтя"}}},
    [6004] = {n="Неоконченное дело", d="Убейте 2 медиков, 2 охотников, 2 волхвов и 2 рыцарей Алого ордена и вернитесь к Кристе Чернотени в Западных Чумных землях.", tgo={{"Медик из Алого ордена"}, {"Охотница из Алого ордена"}, {"Маг из Алого ордена"}, {"Рыцарь из Алого ордена"}}},
