    [6122] = {n="Основной источник", d="Используйте пустую колбу для взятия пробы воды из устья пещеры у водопада Скалистый.\nДоставьте наполненную колбу Аландариан Песне Ночи в Аубердин, на Темный Берег.", objs={"Cliffspring Falls Cave Mouth"}},
    [6123] = {n="Сбор лекарственных ингредиентов", d="Принесите 5 корешков землекорня и 12 лунных грибов Аландариан Песне Ночи в Аубердине, чтобы она могла сделать целительную мазь.", tgo={{"Плеточник-росток", "Гневная лоза"}, {}}, objs={"Лунный Плеснецвет"}},
    [6124] = {n="Исцеление больных", d="Нанесите мазь исцеления животных на 10 больных оленей, обитающих на Темном Берегу, - это должно их исцелить. По слухам, ареал обитания больных оленей - южнее реки Скалистой и севернее Аубердина, а далее - по всей области, вплоть до южных границ Темного Берега, где начинается Ясеневый лес.", tgo={{"Больной олень"}}},
