    [6185] = {n="Чума на востоке", d="Поищите в Восточных Чумных землях сведения про некоего Гнилостеня и пропавших агентов ШРУ. Если удастся найти знаки отличия ШРУ, отнесите их Флинту Тенемору в Лагерь Промозглого Ветра.", objs={"Изуродованный человеческий труп"}},
