    [6392] = {n="Возвращение к Броку", d="Заплатите укротителю грифонов Гриту Турдену, долетите на грифоне до Телcамара и отдайте почетные кирки Броку Камнекопу."},
    [6502] = {n="Амулет Пламени дракона", d="Добудьте кровь могучего черного дракона у генерала Драккисата.\nЕго можно найти сидящим на троне в залах Вознесения в Пике Черной горы.", tgo={{"Генерал Драккисат"}}},
