    [6681] = {n="Поместье, Черный Ворон", d="Отнесите печать Черного Ворона Фахраду в поместье Черный Ворон, сокрытое среди холмов Хилсбрада.\nНе теряйте бдительности. Поиски поместья - проверка на ловкость.", tgo={{"Черный Ворон"}}},
    [6701] = {n="Эмблемы Синдиката", d="Добыча с: Убийца из Синдиката, Окудник Синдиката, Преступник Синдиката", tgo={{"Убийца из Синдиката", "Окудник Синдиката", "Преступник Синдиката", "Проходимец Синдиката", "Наемник Синдиката", "Налетчик Синдиката", "Тать Синдиката", "Шпионка из Синдиката"}}},
