    [7041] = {n="Порча Злоязыкого", d="Наполните церуленовый фиал с покрытием в оранжевом пруду Мародона.\nПолейте гнусь-лозу из полного церуленового фиала, выгнав ядовитую лозу.\nИсцелите 8 растений, убивая ядовитые лозы, и вернитесь к Талендрии из Высоты Найджела.", tgo={{"Ядовитая лоза"}, {}}, objs={"Оранжевый пруд Мародона"}},
    [7044] = {n="Легенды Мародона", d="Добудьте две части скипетра Келебраса - жезл Келебраса и бриллиант Келебраса.\nНайдите способ поговорить с Келебрасом.", tgo={{"Лорд Злоязыкий"}, {"Ноксион", "Порождение Пагубника"}}},
    [7046] = {n="Скипетр Келебраса", d="Помогите Селебрасу Искупленному воссоздать скипетр Селебраса.\nПо завершении ритуала снова обратитесь к нему.", objs={"Incantation of Celebras"}},
    [7065] = {n="Яблочко от яблоньки...", d="Убейте принцессу Терадрас и вернитесь к хранителю Марандису на Высоту Найджела в Пустоши.", tgo={{"Принцесса Терадрас"}}},
    [7066] = {n="Семя Жизни", d="Найдите в Лунной поляне Ремулоса и отдайте ему Семя Жизни."},
    [7067] = {n="Инструкции кентавра-парии", d="Прочтите инструкции кентавра-парии, добудьте из Мародона амулет Соединения и верните его кентавру-парии из южной части Пустошей."},
    [7070] = {n="Фрагменты осколка сумрака", d="Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их верховному магу Тервошу в Терамор на побережье Пылевых топей.", tgo={{"Темнокаменный грохотун", "Темнокаменный крушитель", "Темнокаменный рокотун"}}},
    [7383] = {n="Венец Земли", d="Наполните аметистовый фиал и принесите его Коритрасу Лунному Гневу в Доланаар.", objs={"Лунный колодец на Поляне Оракула"}},
    [7441] = {n="Пузиллин и старейший Аж'Тордин", d="Отправляйтесь в Забытый Город и отыщите беса Пузиллина. Любыми доступными средствами убедите Пузиллина отдать вам книгу заклинаний Аж'Тордина.\nЕсли добудете книгу, вернитесь к Аж'Тордину в павильон Лорисс в Фераласе.", tgo={{"Пузиллин"}}},
    [7461] = {n="Древнее безумие", d="Перебейте стражей, которые охраняют 5 столпов, снабжающих энергией Тюрьму Бессмер'тера. После того как столпы угаснут, силовое поле, удерживающее Бессмер'тера, рассеется.\nВойдите в Тюрьму Бессмер'тера и уничтожьте злого демона, который находится внутри. И, наконец, сразитесь с принцем Тортелдрином в Читальне.\nЕсли задание будет выполнено успешно, вернитесь во двор, к прародительнице Шен'дралар.", tgo={{"Бессмер'тер"}, {"Принц Тортелдрин"}}},
    [7462] = {n="Сокровище Шен'дралар", d="Вернитесь в Читальню и найдите сокровище Шен'дралар. Получите свою награду!"},
    [7463] = {n="Магический напиток", d="Ступайте в Квартал Криводревов Забытого Города и убейте элементаля воды Гидротварь. Вернитесь в Читальню к сказителю Лидросу и принесите ему сущность Гидротвари.", tgo={{"Гидротварь"}}},
    [7482] = {n="Эльфийские легенды", d="Отыщите в Забытом Городе Тельмия Сновидца. Вернитесь в крепость Оперенной Луны к исследовательнице Рунический Шип и сообщите ей все, что вам удалось узнать.", objs={"Останки Тельмия Сновидца"}},
    [7483] = {n="\"Манускрипт Скорости\"", d="Принесите сказителю Лидросу в Забытом Городе \"Манускрипт Скорости\", 1 безупречный черный алмаз, 2 больших сияющих осколка и 2 образца крови героев, чтобы получить магический камень стремительности.", tgo={{"Громила из клана Гордок", "Маг-лорд из клана Гордок", "Капитан из клана Гордок", "Чернокнижник из клана Гордок", "Разоритель из клана Гордок", "Сатир из племени Исчадий Природы", "Разбойник из племени Исчадий Природы", "Плут из племени Исчадий Природы"}, {"Скелет-вождь", "Мясной голем", "Волхв из Алого ордена", "Кавалерист из Алого ордена", "Штейгер Джеррис", "Верховный заступник Лорик", "Араж Призыватель", "Проклятый вершитель правосудия"}, {}, {}}, objs={"Кровь героев"}},
    [7484] = {n="\"Манускрипт Средоточия\"", d="Принесите сказителю Лидросу в Забытом Городе \"Манускрипт Средоточия\", 1 безупречный черный алмаз, 4 больших сияющих осколка и 2 образца шкуры Тени, чтобы получить магический камень сосредоточения.", tgo={{"Громила из клана Гордок", "Маг-лорд из клана Гордок", "Капитан из клана Гордок", "Чернокнижник из клана Гордок", "Разоритель из клана Гордок", "Сатир из племени Исчадий Природы", "Разбойник из племени Исчадий Природы", "Плут из племени Исчадий Природы"}, {"Скелет-вождь", "Мясной голем", "Волхв из Алого ордена", "Кавалерист из Алого ордена", "Штейгер Джеррис", "Верховный заступник Лорик", "Араж Призыватель", "Проклятый вершитель правосудия"}, {}, {"Восставшее создание", "Восставший костостраж", "Леди Иллюсия Баров", "Инструктор Коварница", "Равениан", "Сказитель Полкелт"}}},
    [7485] = {n="\"Манускрипт Защиты", d="Принесите сказителю Лидросу в Забытом Городе \"Манускрипт Защиты\", 1 безупречный черный алмаз, 2 больших сияющих осколка и 1 потертый шовный материал поганища, чтобы получить магический камень защиты.", tgo={{"Громила из клана Гордок", "Маг-лорд из клана Гордок", "Капитан из клана Гордок", "Чернокнижник из клана Гордок", "Разоритель из клана Гордок", "Одеревеневший древень", "Железнокор-заступник", "Огнечар Элдрета"}, {"Скелет-вождь", "Мясной голем", "Волхв из Алого ордена", "Кавалерист из Алого ордена", "Штейгер Джеррис", "Верховный заступник Лорик", "Араж Призыватель", "Проклятый вершитель правосудия"}, {}, {"Лоскутный ужас", "Желчеплюй", "Изрыгатель яда", "Рамштайн Ненасытный"}}},
